    // ---------------------------------------------------------------- Aurelion skin: custom images inside the game UI (all reflection, never throws)
    // The image lives as a loose PNG in <module>\GUI\SpriteSheets\<file>; its sprite/part definitions are in GUI\Sprites\AurelionSpriteData.xml.
    // EnsureSprite() hands the PNG to the game's sprite category, and returns false (caller keeps the plain background) if anything is off.
    public static class AurelionSkin
    {
        static readonly Dictionary<string, int> fails = new Dictionary<string, int>(); public static string Status = "";
        static void Fail(string category) { int n; fails.TryGetValue(category, out n); fails[category] = n + 1; }
        const BindingFlags All = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static;

        static Type T(string name) { foreach (var a in AppDomain.CurrentDomain.GetAssemblies()) { try { var t = a.GetType(name, false); if (t != null) return t; } catch { } } return null; }
        static object Static(Type t, string prop) { var p = t.GetProperty(prop, All); if (p != null) return p.GetValue(null, null); var f = t.GetField(prop, All); return f != null ? f.GetValue(null) : null; }
        static object Get(object o, string prop) { var p = o.GetType().GetProperty(prop, All); if (p != null) return p.GetValue(o, null); var f = o.GetType().GetField(prop, All); return f != null ? f.GetValue(o) : null; }

        static void Note(string s) { Status = s; try { Aurelion.Core.Log.W("Skin: " + s); } catch { } }

        static string Sig(MethodInfo m) { return m.Name + "(" + string.Join(", ", m.GetParameters().Select(x => x.ParameterType.Name).ToArray()) + ")"; }
        static bool Alive(object tex)
        {
            if (tex == null) return false;
            try { var v = Get(tex, "IsValid"); if (v is bool) return (bool)v; } catch { }
            return true;
        }

        // The engine's texture factory changed between game versions, so every overload is tried with arguments built from its parameter types.
        static object MakeEngineTexture(string dir, string file, string moduleName)
        {
            var tt = T("TaleWorlds.Engine.Texture");
            if (tt == null) { Note("Texture type missing"); return null; }
            var full = Path.Combine(dir, file);
            var rel1 = "../../Modules/" + moduleName + "/GUI/SpriteSheets/"; var rel2 = "Modules/" + moduleName + "/GUI/SpriteSheets/";
            var dirSep = dir + Path.DirectorySeparatorChar;
            var names = new[] { "CreateTextureFromPath", "LoadTextureFromPath", "CreateFromByteArray", "CreateFromMemory" };
            foreach (var m in tt.GetMethods(All)) if (m.IsStatic && names.Contains(m.Name)) Note("overload " + Sig(m));

            // easiest route: hand the PNG file bytes to the engine
            try
            {
                var bytes = File.ReadAllBytes(full);
                foreach (var m in tt.GetMethods(All))
                {
                    if (!m.IsStatic || m.Name != "CreateFromMemory") continue;
                    var ps0 = m.GetParameters();
                    if (ps0.Length < 1 || ps0[0].ParameterType != typeof(byte[])) continue;
                    var a0 = new object[ps0.Length]; a0[0] = bytes;
                    for (int i = 1; i < ps0.Length; i++) a0[i] = ps0[i].HasDefaultValue ? ps0[i].DefaultValue : (ps0[i].ParameterType.IsValueType ? Activator.CreateInstance(ps0[i].ParameterType) : null);
                    try { var r0 = m.Invoke(null, a0); Note("CreateFromMemory returned " + (r0 == null ? "null" : r0.GetType().Name + " valid=" + Alive(r0))); if (Alive(r0)) { Note("texture via " + Sig(m)); return r0; } } catch (Exception e0) { Note("memory try failed: " + (e0.InnerException ?? e0).Message); }
                }
            }
            catch (Exception e1) { Note("memory route failed: " + e1.Message); }

            foreach (var m in tt.GetMethods(All))
            {
                if (!m.IsStatic || m.Name != "CreateTextureFromPath") continue;
                var ps = m.GetParameters();
                var tries = new List<object[]>();
                if (ps.Length == 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                { tries.Add(new object[] { dirSep, file }); tries.Add(new object[] { rel1, file }); tries.Add(new object[] { rel2, file }); tries.Add(new object[] { dir, file }); }
                else if (ps.Length == 1 && ps[0].ParameterType == typeof(string)) { tries.Add(new object[] { full }); tries.Add(new object[] { rel1 + file }); }
                else if (ps.Length >= 1 && ps[0].ParameterType.Name == "PlatformFilePath")
                {
                    var fpT = ps[0].ParameterType; var dpT = T("TaleWorlds.Library.PlatformDirectoryPath"); var ftT = T("TaleWorlds.Library.PlatformFileType");
                    if (dpT != null && ftT != null)
                        foreach (var ft in Enum.GetValues(ftT))
                            foreach (var d in new[] { dir, rel1, rel2 })
                            {
                                try
                                {
                                    var dp = Activator.CreateInstance(dpT, new object[] { ft, d });
                                    var fp = Activator.CreateInstance(fpT, new object[] { dp, file });
                                    var args = new object[ps.Length]; args[0] = fp;
                                    for (int i = 1; i < ps.Length; i++) args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : (ps[i].ParameterType.IsValueType ? Activator.CreateInstance(ps[i].ParameterType) : null);
                                    tries.Add(args);
                                } catch (Exception ec) { Note("path ctor failed: " + (ec.InnerException ?? ec).Message); }
                            }
                }
                foreach (var a in tries)
                {
                    try { var r = m.Invoke(null, a); if (Alive(r)) { Note("texture via " + Sig(m)); return r; } else Note("path route gave an invalid texture"); } catch (Exception e) { Note("try failed: " + (e.InnerException ?? e).Message); }
                }
            }
            // fallback: decode the PNG ourselves and hand raw pixels to the engine
            try
            {
                System.Reflection.Assembly drawing = null; try { drawing = System.Reflection.Assembly.Load("System.Drawing, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b03f5f7f11d50a3a"); } catch { }
                var bmpT = drawing == null ? null : drawing.GetType("System.Drawing.Bitmap"); var rectT = drawing == null ? null : drawing.GetType("System.Drawing.Rectangle");
                if (bmpT == null || rectT == null) { Note("System.Drawing missing"); return null; }
                var bmp = Activator.CreateInstance(bmpT, new object[] { full });
                int w = (int)Get(bmp, "Width"), h = (int)Get(bmp, "Height");
                var rect = Activator.CreateInstance(rectT, new object[] { 0, 0, w, h });
                var lb = bmpT.GetMethods().First(x => x.Name == "LockBits" && x.GetParameters().Length == 3 && x.GetParameters()[1].ParameterType.IsEnum && x.GetParameters()[2].ParameterType.IsEnum);
                var bd = lb.Invoke(bmp, new object[] { rect, Enum.ToObject(lb.GetParameters()[1].ParameterType, 1), Enum.ToObject(lb.GetParameters()[2].ParameterType, 2498570) });
                var scan0 = (IntPtr)Get(bd, "Scan0"); int stride = (int)Get(bd, "Stride");
                var buf = new byte[w * h * 4];
                for (int y = 0; y < h; y++) System.Runtime.InteropServices.Marshal.Copy(new IntPtr(scan0.ToInt64() + (long)y * stride), buf, y * w * 4, w * 4);
                bmpT.GetMethod("UnlockBits").Invoke(bmp, new object[] { bd });
                for (int i = 0; i < buf.Length; i += 4) { var b0 = buf[i]; buf[i] = buf[i + 2]; buf[i + 2] = b0; }   // BGRA -> RGBA
                foreach (var m in tt.GetMethods(All))
                {
                    if (!m.IsStatic || m.Name != "CreateFromByteArray") continue;
                    var ps = m.GetParameters();
                    if (ps.Length < 3 || ps[0].ParameterType != typeof(byte[])) continue;
                    var args = new object[ps.Length]; args[0] = buf; args[1] = w; args[2] = h;
                    for (int i = 3; i < ps.Length; i++) args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : (ps[i].ParameterType.IsValueType ? Activator.CreateInstance(ps[i].ParameterType) : null);
                    try { var r = m.Invoke(null, args); if (Alive(r)) { Note("texture via raw pixels " + Sig(m)); return r; } } catch (Exception e) { Note("raw try failed: " + (e.InnerException ?? e).Message); }
                }
            }
            catch (Exception e) { Note("raw fallback failed: " + (e.InnerException ?? e).Message); }
            return null;
        }

        public static bool EnsureSprite(string category, string pngFile)
        {
            int failed; if (fails.TryGetValue(category, out failed) && failed >= 3) return false;
            try
            {
                var uiRes = T("TaleWorlds.Engine.GauntletUI.UIResourceManager");
                if (uiRes == null) { Fail(category); Note("UIResourceManager missing"); return false; }
                var sd = Static(uiRes, "SpriteData");
                if (sd == null) { Fail(category); Note("SpriteData null"); return false; }
                var cats = Get(sd, "SpriteCategories") as IDictionary;
                if (cats == null) { Fail(category); Note("categories null"); return false; }

                // if the game did not pick up our sprite xml by itself, load it ourselves and copy it in
                if (!cats.Contains(category))
                {
                    var sdType = sd.GetType();
                    var mine = Activator.CreateInstance(sdType, new object[] { "AurelionSpriteData" });
                    var depot = Static(uiRes, "UIResourceDepot");
                    var lm = sdType.GetMethod("LoadFromDepot", All);
                    if (lm == null || depot == null) { Fail(category); Note("cannot load sprite xml"); return false; }
                    lm.Invoke(mine, new object[] { depot });
                    foreach (var prop in new[] { "SpriteCategories", "SpriteParts", "Sprites" })
                    {
                        var src = Get(mine, prop) as IDictionary; var dst = Get(sd, prop) as IDictionary;
                        if (src == null || dst == null) continue;
                        foreach (DictionaryEntry de in src) dst[de.Key] = de.Value;
                    }
                    cats = Get(sd, "SpriteCategories") as IDictionary;
                    if (!cats.Contains(category)) { Fail(category); Note("category not found in xml"); return false; }
                }

                var cat = cats[category];
                var sheets = Get(cat, "SpriteSheets") as IList;
                if (sheets == null) { Fail(category); Note("no sheets list"); return false; }
                if (sheets.Count > 0)
                {   // already injected: make sure the texture is still alive
                    try { var tex0 = sheets[0]; var valid = Get(tex0, "IsValid"); if (valid is bool && (bool)valid) return true; } catch { }
                    sheets.Clear();
                }

                var asmPath = typeof(AurelionSkin).Assembly.Location;
                var module = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(asmPath), "..", ".."));
                var dir = Path.Combine(module, "GUI", "SpriteSheets");
                if (Path.IsPathRooted(pngFile)) { dir = Path.GetDirectoryName(pngFile); pngFile = Path.GetFileName(pngFile); }   // a picture saved on this computer (the hero card)
                if (!File.Exists(Path.Combine(dir, pngFile))) { Fail(category); Note("image missing: " + pngFile); return false; }

                var eng = MakeEngineTexture(dir, pngFile, Path.GetFileName(module));
                if (eng == null) { Fail(category); Note("texture could not be created"); return false; }

                try { var keep = eng.GetType().GetMethod("SetTextureAsAlwaysValid", All); if (keep != null) keep.Invoke(eng, null); } catch { }
                // every texture needs its own name: the engine keeps one image material per texture name, so nameless textures end up drawing each other
                try { var np = eng.GetType().GetProperty("Name", All); if (np != null && np.CanWrite) np.SetValue(eng, "aurelion_" + category, null); Note("name " + (np == null ? "?" : Convert.ToString(np.GetValue(eng, null)))); } catch (Exception en) { Note("name failed: " + (en.InnerException ?? en).Message); }
                var wrapType = T("TaleWorlds.Engine.GauntletUI.EngineTexture");
                var twoDType = T("TaleWorlds.TwoDimension.Texture");
                if (wrapType == null || twoDType == null) { Fail(category); Note("texture types missing"); return false; }
                var wrap = Activator.CreateInstance(wrapType, new object[] { eng });
                var tex = Activator.CreateInstance(twoDType, new object[] { wrap });
                sheets.Add(tex);
                var isLoaded = cat.GetType().GetProperty("IsLoaded", All);
                if (isLoaded != null) isLoaded.SetValue(cat, true, null);
                Note("ok " + category);
                return true;
            }
            catch (Exception e) { Fail(category); Note("failed: " + (e.InnerException != null ? e.InnerException.Message : e.Message)); return false; }
        }
    }

    // ---------------------------------------------------------------- the window (same way Coop opens its chat)
    // ScreenManager.RemoveGlobalLayer has a different signature between game builds: find it at run time, so closing never breaks.
    public static class AurLayers
    {
        public static void Remove(GlobalLayer g)
        {
            foreach (var m in typeof(ScreenManager).GetMethods(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static))
            {
                if (m.Name != "RemoveGlobalLayer") continue;
                var ps = m.GetParameters();
                if (ps.Length == 0 || !ps[0].ParameterType.IsAssignableFrom(g.GetType())) continue;
                var args = new object[ps.Length]; args[0] = g;
                for (int i = 1; i < ps.Length; i++)
                    args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : (ps[i].ParameterType == typeof(bool) ? (object)true : (ps[i].ParameterType.IsValueType ? Activator.CreateInstance(ps[i].ParameterType) : null));
                m.Invoke(null, args); return;
            }
            throw new MissingMethodException("ScreenManager.RemoveGlobalLayer");
        }
    }

    public class AdminMenu : GlobalLayer
    {
        readonly AdminMenuVM vm; GauntletLayer layer; object movie;
        public AdminMenu(AdminMenuVM vm) { this.vm = vm; }

        AurAnim anim;
        public void Open()
        {
            try { vm.HasBg = AurelionSkin.EnsureSprite("aur_throne", "aur_throne_1.png"); } catch { vm.HasBg = false; }
            try { vm.HasUi = AurelionSkin.EnsureSprite("aur_ui", "aur_ui_1.png"); } catch { vm.HasUi = false; }
            try { AurFont.Ensure(); } catch (Exception e) { Log.W("Font: " + (e.InnerException ?? e).Message); }
            layer = new GauntletLayer("AurelionAdmin", 4100, false);
            movie = layer.LoadMovie("AurelionAdmin", vm);
            layer.InputRestrictions.SetInputRestrictions(true);
            Layer = layer;
            ScreenManager.AddGlobalLayer(this, true);
            layer.IsFocusLayer = true;
            ScreenManager.TrySetFocus(layer);
            try { anim = new AurAnim(layer, movie, vm); } catch (Exception e) { anim = null; Log.W("Anim off: " + (e.InnerException ?? e).Message); }
        }

        public void TickMenu()
        {
            if (layer == null) return;
            if (anim != null) { try { anim.Tick(); } catch (Exception e) { anim = null; Log.W("Anim off: " + (e.InnerException ?? e).Message); } }
            if (vm.Frame14()) { AdminClient.Close(); return; }
            if (!layer.IsFocusLayer && !vm.HasConfirm) { layer.IsFocusLayer = true; ScreenManager.TrySetFocus(layer); }
        }

        public void CloseMenu()
        {
            if (layer == null) return;
            try { layer.InputRestrictions.ResetInputRestrictions(); } catch { }
            try { layer.IsFocusLayer = false; ScreenManager.TryLoseFocus(layer); } catch { }
            try { var rm = layer.GetType().GetMethod("ReleaseMovie"); if (rm != null && movie != null) rm.Invoke(layer, new[] { movie }); } catch { }
            try { AurLayers.Remove(this); } catch (Exception e) { Log.W("AdminMenu.Close layer: " + (e.InnerException ?? e).Message); }
            try { vm.OnFinalize(); } catch { }
            layer = null;
        }
    }

    // ---------------------------------------------------------------- Aurelion's own font (Cairo): atlases in GUI\SpriteSheets, metrics in GUI\AurelionFont
    // Registered the same way the Arabic mod registers its font (sprite named like the font + FontFactory.TryAddFontDefinition),
    // then every Aur.* brush is pointed at it. Runs before each time the menu opens (cheap when everything is already in place).
    public static class AurFont
    {
        static int tries;
        static readonly string[] Names = { "Aurelion-Regular", "Aurelion-SemiBold", "Aurelion-Bold" };
        static readonly string[] Cats = { "aur_font_regular", "aur_font_semibold", "aur_font_bold" };
        static readonly string[] SemiBrushes = { "Aur.Blue", "Aur.Accent", "Aur.Red", "Aur.BrandSmall", "Aur.BtnText", "Aur.TabText", "Aur.Chip", "Aur.PinError", "Aur.RowTitle" };
        static readonly string[] BoldBrushes = { "Aur.Gold", "Aur.Brand", "Aur.BrandC", "Aur.Caption", "Aur.PinTitle", "Aur.DialogTitle", "Aur.PinInput" };
        public static bool Ready;

        public static void Ensure()
        {
            Ready = false;
            if (tries >= 3) return;
            for (int i = 0; i < Cats.Length; i++)
                if (!AurelionSkin.EnsureSprite(Cats[i], Cats[i] + "_1.png")) { tries++; Log.W("Font: atlas not loaded: " + Cats[i]); return; }
            var ff = TaleWorlds.Engine.GauntletUI.UIResourceManager.FontFactory; var sd = TaleWorlds.Engine.GauntletUI.UIResourceManager.SpriteData;
            var bf = TaleWorlds.Engine.GauntletUI.UIResourceManager.BrushFactory;
            if (ff == null || sd == null || bf == null) { tries++; Log.W("Font: factory missing"); return; }
            var module = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(AurFont).Assembly.Location), "..", ".."));
            var dir = Path.Combine(module, "GUI", "AurelionFont");
            var fonts = new TaleWorlds.TwoDimension.Font[Names.Length];
            for (int i = 0; i < Names.Length; i++)
            {
                fonts[i] = Add(ff, sd, dir, Names[i]);
                if (fonts[i] == null) { tries++; Log.W("Font: could not register " + Names[i]); return; }
            }
            int n = 0;
            foreach (var br in bf.Brushes)
            {
                if (br == null || br.Name == null || !br.Name.StartsWith("Aur.", StringComparison.Ordinal)) continue;
                // v14 brushes say their weight in the name: ".B" = Bold, ".S" = SemiBold
                var f = fonts[2];   // every Aurelion line in the bold cut: the thinner cuts looked faint in the game (sizes and colours keep the hierarchy)
                if (br.Font == f) { n++; continue; }
                br.Font = f;
                foreach (var st in br.Styles) st.Font = f;
                n++;
            }
            Ready = true;
            if (!logged) { logged = true; Log.W("Font: Aurelion fonts ready (" + n + " brushes, sprite=" + (fonts[0].FontSprite != null) + ", chars=" + fonts[0].CharacterCount + ")"); }
        }
        static bool logged;

        static TaleWorlds.TwoDimension.Font Find(TaleWorlds.GauntletUI.FontFactory ff, string name)
        {
            foreach (var f in ff.GetFonts()) if (f != null && f.Name == name) return f;
            return null;
        }

        static TaleWorlds.TwoDimension.Font Add(TaleWorlds.GauntletUI.FontFactory ff, TaleWorlds.TwoDimension.SpriteData sd, string dir, string name)
        {
            var have = Find(ff, name);
            if (have != null) return have;
            if (!File.Exists(Path.Combine(dir, name + ".fnt"))) { Log.W("Font: file missing " + name + ".fnt"); return null; }
            foreach (var p in new[] { dir.Replace('\\', '/') + "/", dir + Path.DirectorySeparatorChar })
            {
                try { var ok = ff.TryAddFontDefinition(p, name, sd); Log.W("Font: TryAddFontDefinition(" + name + ") = " + ok); } catch (Exception e) { Log.W("Font: add failed: " + (e.InnerException ?? e).Message); }
                have = Find(ff, name);
                if (have != null) return have;
            }
            return null;
        }
    }

    // ---------------------------------------------------------------- motion (same numbers as the launcher): fade + slide in, slow zoom on the picture, breathing glows
    public class AurAnim
    {
        class Tw { public TaleWorlds.GauntletUI.BaseTypes.Widget W; public double Start, Dur; public float Dy; public bool Fade; public List<TaleWorlds.GauntletUI.BaseTypes.Widget> All; }
        const float BgW = 1422f, BgH = 800f;
        readonly TaleWorlds.GauntletUI.BaseTypes.Widget root; readonly AdminMenuVM vm;
        readonly TaleWorlds.GauntletUI.BaseTypes.Widget bg;
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> halos = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> pulses = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> dots = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<Tw> tweens = new List<Tw>();
        DateTime last = DateTime.UtcNow; double t;
        string lastTab = null; bool lastConfirm, lastPin; int lastSerial; bool fadeOk = true; int lastCat; bool lastPalette, lastToast;

        static bool Live(string id) { return id == "AurGlow" || id == "AurLogoGlow" || id == "AurDotGlow"; }

        public AurAnim(GauntletLayer layer, object movie, AdminMenuVM vm)
        {
            this.vm = vm;
            TaleWorlds.GauntletUI.BaseTypes.Widget r = null;
            try
            {
                var mp = movie.GetType().GetProperty("Movie"); var mv = mp == null ? movie : mp.GetValue(movie, null);
                var rp = mv == null ? null : mv.GetType().GetProperty("RootWidget");
                if (rp != null) r = rp.GetValue(mv, null) as TaleWorlds.GauntletUI.BaseTypes.Widget;
            }
            catch { }
            if (r == null) r = layer.UIContext.Root;
            root = r;
            bg = Find("AurHero");
            foreach (var w in root.GetAllChildrenAndThisRecursive())
            {
                if (w.Id == "AurGlow") pulses.Add(w);
                else if (w.Id == "AurLogoGlow") halos.Add(w);
                else if (w.Id == "AurDotGlow") dots.Add(w);
            }
            lastTab = vm.CurTab; lastConfirm = vm.HasConfirm; lastPin = vm.IsPinScreen; lastSerial = vm.ResultSerial;
            Enter(Find("AurWin"), 0, 12f, true, 0.30);
            Log.W("Anim: ready (bg=" + (bg != null) + " halos=" + halos.Count + " pulses=" + pulses.Count + ")");
        }

        TaleWorlds.GauntletUI.BaseTypes.Widget Find(string id) { return root.FindChild(id, true); }

        void Enter(TaleWorlds.GauntletUI.BaseTypes.Widget w, double delay, float dy, bool fade, double dur)
        {
            if (w == null) return;
            tweens.RemoveAll(x => x.W == w);
            var tw = new Tw { W = w, Start = t + delay, Dur = dur, Dy = dy, Fade = fade && fadeOk };
            if (tw.Fade) tw.All = w.GetAllChildrenAndThisRecursive();
            tweens.Add(tw);
            Apply(tw, 0f);
        }

        void Apply(Tw tw, float e)
        {
            tw.W.PositionYOffset = tw.Dy * (1f - e);
            if (!tw.Fade || tw.All == null) return;
            try
            {
                for (int i = 0; i < tw.All.Count; i++)
                {
                    var w = tw.All[i];
                    if (Live(w.Id)) continue;
                    w.AlphaFactor = e;
                    var bw = w as TaleWorlds.GauntletUI.BaseTypes.BrushWidget;
                    if (bw != null) bw.Brush.GlobalAlphaFactor = e;
                }
            }
            catch (Exception ex) { fadeOk = false; tw.Fade = false; Log.W("Anim: fade off: " + ex.Message); }
        }

        static float Wave(double t, double period, double lo, double hi) { return (float)(lo + (hi - lo) * (0.5 - 0.5 * Math.Cos(2 * Math.PI * t / period))); }

        public void Tick()
        {
            var now = DateTime.UtcNow; var dt = (now - last).TotalSeconds; last = now;
            if (dt < 0) dt = 0; if (dt > 0.1) dt = 0.1;
            t += dt;

            // what changed since the last frame
            if (vm.CurTab != lastTab)
            {
                lastTab = vm.CurTab; Enter(Find("AurPage_" + lastTab), 0, 14f, false, 0.40);
                for (int i = 1; i <= 6; i++) Enter(Find("AurPage_" + lastTab + "_" + i), 0.05 * (i - 1), 14f, true, 0.42);   // cards come in one after the other
            }
            if (vm.CatSerial != lastCat) { lastCat = vm.CatSerial; Enter(Find("AurActs"), 0, 10f, true, 0.30); }
            if (vm.HasPalette != lastPalette) { lastPalette = vm.HasPalette; if (lastPalette) Enter(Find("AurPaletteCard"), 0, 10f, true, 0.24); }
            if (vm.HasToast != lastToast) { lastToast = vm.HasToast; if (lastToast) Enter(Find("AurToast"), 0, 16f, true, 0.32); }
            if (vm.HasConfirm != lastConfirm) { lastConfirm = vm.HasConfirm; if (lastConfirm) Enter(Find("AurConfirmCard"), 0, 10f, true, 0.24); }
            if (vm.IsPinScreen != lastPin)
            {
                lastPin = vm.IsPinScreen;
                if (lastPin) Enter(Find("AurPin"), 0, 14f, true, 0.40);
                else { Enter(Find("AurPage"), 0, 14f, true, 0.40); Enter(Find("AurHeader"), 0.04, -8f, true, 0.36); }
            }
            if (vm.ResultSerial != lastSerial) { lastSerial = vm.ResultSerial; Enter(Find("AurToast"), 0, 16f, true, 0.32); Enter(Find("AurBar"), 0, 0f, true, 1.2); }

            for (int i = tweens.Count - 1; i >= 0; i--)
            {
                var tw = tweens[i];
                var p = (t - tw.Start) / tw.Dur;
                if (p < 0) continue;
                if (p >= 1) { Apply(tw, 1f); tweens.RemoveAt(i); continue; }
                var q = 1.0 - p; Apply(tw, (float)(1.0 - q * q * q));
            }

            if (bg != null)
            {   // slow zoom in and out: 1.0 -> 1.07 in 28 seconds, like the launcher's main picture
                var s = 1.0 + 0.07 * (0.5 - 0.5 * Math.Cos(2 * Math.PI * t / 56.0));
                bg.SuggestedWidth = (float)(BgW * s); bg.SuggestedHeight = (float)(BgH * s);
            }
            var ha = Wave(t, 5.2, 0.15, 0.60); for (int i = 0; i < halos.Count; i++) halos[i].AlphaFactor = ha;      // logo glow: 2.6 s each way
            var pa = Wave(t, 3.2, 0.35, 0.95); for (int i = 0; i < pulses.Count; i++) pulses[i].AlphaFactor = pa;   // primary button glow: 1.6 s each way
            var da = Wave(t, 2.2, 0.25, 0.90); for (int i = 0; i < dots.Count; i++) dots[i].AlphaFactor = da;       // online dot
        }
    }

