        // ---------------------------------------------------------------- performance probes (server and players)
        //  Measures the campaign's periodic ticks and any frame that takes over 0.75 s, and writes them to aurelion.log
        //  ("Perf: ..."). Used to find the short freezes players see every minute or so.
        static readonly System.Diagnostics.Stopwatch perfFrameSw = new System.Diagnostics.Stopwatch();
        static int perfLogged; static DateTime perfWindow = DateTime.UtcNow;
        static void PerfSetup()
        {
            try
            {
                var t = AccessTools.TypeByName("TaleWorlds.CampaignSystem.CampaignPeriodicEventManager");
                var pre = new HarmonyMethod(typeof(AdminHost).GetMethod("PerfPrefix", BindingFlags.Static | BindingFlags.Public));
                var post = new HarmonyMethod(typeof(AdminHost).GetMethod("PerfPostfix", BindingFlags.Static | BindingFlags.Public));
                int n = 0;
                if (t != null)
                    foreach (var name in new[] { "PeriodicDailyTick", "PeriodicHourlyTick", "PeriodicQuarterDailyTick", "TickPeriodicEvents" })
                    {
                        var m = AccessTools.Method(t, name);
                        if (m != null) { harmony.Patch(m, pre, post); n++; }
                    }
                Log.W("Perf: probes on " + n + " campaign tick methods (logs ticks > 0.25 s and frames > 0.75 s)");
            }
            catch (Exception e) { Log.W("Perf setup: " + (e.InnerException ?? e).Message); }
        }
        public static void PerfPrefix(out long __state) { __state = System.Diagnostics.Stopwatch.GetTimestamp(); }
        public static void PerfPostfix(long __state, MethodBase __originalMethod)
        {
            try
            {
                var ms = (System.Diagnostics.Stopwatch.GetTimestamp() - __state) * 1000.0 / System.Diagnostics.Stopwatch.Frequency;
                if (ms >= 250) PerfLog(__originalMethod.Name + " took " + ms.ToString("0") + " ms");
            }
            catch { }
        }
        static void PerfFrame()
        {
            try
            {
                if (perfFrameSw.IsRunning)
                {
                    var ms = perfFrameSw.Elapsed.TotalMilliseconds;
                    if (ms >= 750) PerfLog("frame stall " + ms.ToString("0") + " ms");
                    frameAvg = frameAvg <= 0 ? ms : frameAvg * 0.98 + Math.Min(ms, 2000) * 0.02;
                }
                perfFrameSw.Reset(); perfFrameSw.Start();
            }
            catch { }
        }
        static void PerfLog(string what)
        {
            if ((DateTime.UtcNow - perfWindow).TotalMinutes >= 10) { perfWindow = DateTime.UtcNow; perfLogged = 0; }
            if (++perfLogged > 200) return;
            string date = "";
            try { var ct = AccessTools.TypeByName("TaleWorlds.CampaignSystem.CampaignTime"); date = Str(Get(ct, "Now")); } catch { }
            Log.W("Perf: " + what + (date.Length > 0 ? "  @ " + date : "") + (isServer ? "  [server]" : "  [player]"));
        }

        // ---------------------------------------------------------------- time: always running at normal speed
        //  Coop (v0.1.7) lets every player pause / fast-forward, pauses when nobody is connected and when all players sit in towns.
        //  Owner's rule (2026-11-07): the campaign clock never stops and runs at 1x, with or without players.
        //   - TimeHandler.Handle_NetworkRequestTimeSpeedChange  → ignored (players can't change time)
        //   - DisconnectedPlayersServerHandler.PlayersConnectedPolicy → always "allowed"; PauseWhenNoPlayersConnected → skipped
        //   - every 4 s: if the campaign isn't playing, ask Coop for Play_1x (Coop's own catch-up protection still applies)
        //  Switch off: admin-config.json  "time": { "always": false }
        static bool timePatched; static int timeBlocked, timeFixes; static string lastTimeMode = ""; static DateTime timeQuietUntil = DateTime.MinValue;
        public static bool TimeRequestPrefix() { if (!cfg.AlwaysTime) return true; timeBlocked++; return false; }
        public static void TimeAllowPostfix(ref bool __result) { if (cfg.AlwaysTime) __result = true; }
        public static bool TimeSkipPrefix() { return !cfg.AlwaysTime; }
        // Coop pauses the clock by itself while a joining player catches up (OverloadedPeerManager.PauseTime/ResumeTime).
        // Our 4-second "keep it playing" loop must not undo that pause, otherwise the joiner's replay queue fills up (100000) and the join is aborted.
        static DateTime catchUpPauseSince = DateTime.MinValue;
        public static void CatchUpPausePrefix() { catchUpPauseSince = DateTime.UtcNow; }
        public static void CatchUpResumePrefix() { catchUpPauseSince = DateTime.MinValue; }
        static bool CatchUpPaused() { return joinLease != null || (catchUpPauseSince != DateTime.MinValue && (DateTime.UtcNow - catchUpPauseSince).TotalMinutes < 20); }

        // Join hold (v10, 2026-11-13). Root cause of "JoinReplayQueueLimit":
        //   Coop only pauses for peers that already finished loading (OverloadedPeerManager.GetLivePeersAboveThreshold skips IsLoading).
        //   A joiner is "loading" from the save transfer until its replay is applied (~1.5 min with our campaign), so the clock kept running,
        //   MoreNations produced ~1000 sync packets/s, and the joiner's catch-up queue passed 100000 before it could enter → join aborted.
        //   Fix: while ANY peer is in TransferSave/Loading we hold a Coop automatic-pause lease (same mechanism Coop uses itself),
        //   and release it the moment nobody is loading. Safety: never hold longer than 12 minutes in one go.
        static object joinLease; static DateTime joinHoldSince = DateTime.MinValue, joinNextCheck = DateTime.MinValue, joinLogQuiet = DateTime.MinValue;
        static FieldInfo opmConns, opmTime; static int joinHolds, joinLoading; static bool joinCapped;
        public static void JoinHoldPostfix(object __instance)
        {
            var now = DateTime.UtcNow;
            if (now < joinNextCheck) return;
            joinNextCheck = now.AddMilliseconds(250);
            try
            {
                if (opmConns == null) { opmConns = AccessTools.Field(__instance.GetType(), "connectionCollection"); opmTime = AccessTools.Field(__instance.GetType(), "timeControlInterface"); }
                var conns = opmConns == null ? null : opmConns.GetValue(__instance) as IEnumerable;
                int loading = 0;
                if (conns != null)
                    foreach (var c in conns)
                    {
                        var st = Get(c, "State");
                        var il = st == null ? null : Get(st, "IsLoading");
                        if (il is bool && (bool)il) loading++;
                    }
                joinLoading = loading;
                if (JoinSync.HoldOff) { JoinRelease(now, "hold switched off (joinhold-never.txt)"); return; }
                // v12: the world keeps running while a player joins (JoinSync replays the queue fast);
                // time is held only as a last resort, at most 10 s per joining player (JoinSync.WantHold)
                if (loading == 0) joinCapped = false;
                if (!JoinSync.WantHold) { JoinRelease(now, loading == 0 ? "all players finished loading" : "replay caught up / hold budget used"); return; }
                if (joinLease != null)
                {
                    if ((now - joinHoldSince).TotalMinutes >= 12) { joinCapped = true; JoinRelease(now, "safety limit 12 min (a player is stuck loading)"); }
                    return;
                }
                if (joinCapped) return;   // same stuck join: don't freeze the world again until loading clears
                var tci = opmTime == null ? null : opmTime.GetValue(__instance);
                var acq = tci == null ? null : tci.GetType().GetMethod("ServerAcquireAutomaticPause", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (acq == null) { if (now >= joinLogQuiet) { Log.W("AdminTime: join hold NOT AVAILABLE (ServerAcquireAutomaticPause missing)"); joinLogQuiet = now.AddMinutes(10); } return; }
                joinLease = acq.Invoke(tci, null);
                if (joinLease == null) return;
                joinHoldSince = now; joinHolds++;
                Log.W("AdminTime: campaign time held while " + loading + " player(s) load into the campaign (join #" + joinHolds + ")");
            }
            catch (Exception e) { if (now >= joinLogQuiet) { Log.W("AdminTime join hold: " + (e.InnerException ?? e).Message); joinLogQuiet = now.AddMinutes(10); } }
        }
        static void JoinRelease(DateTime now, string why)
        {
            if (joinLease == null) return;
            var lease = joinLease; bool ok = false;
            try
            {
                MethodInfo rel = null;
                foreach (var it in lease.GetType().GetInterfaces()) { rel = it.GetMethod("TryRelease"); if (rel != null) break; }
                if (rel == null) rel = lease.GetType().GetMethod("TryRelease", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                var r = rel == null ? null : rel.Invoke(lease, null);
                ok = r is bool && (bool)r;
            }
            catch (Exception e) { Log.W("AdminTime join release: " + (e.InnerException ?? e).Message); }
            if (!ok) return;   // try again on the next check
            joinLease = null;
            Log.W("AdminTime: campaign time released after " + (now - joinHoldSince).TotalSeconds.ToString("0.0", CultureInfo.InvariantCulture) + "s join hold (" + why + ")");
        }

        static void TimeSetup()
        {
            if (timePatched || harmony == null) return;
            timePatched = true;
            var st = BindingFlags.Static | BindingFlags.Public;
            try
            {
                var th = AccessTools.TypeByName("Coop.Core.Server.Services.Time.Handlers.TimeHandler");
                var req = th == null ? null : AccessTools.Method(th, "Handle_NetworkRequestTimeSpeedChange");
                if (req != null) harmony.Patch(req, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeRequestPrefix", st)));
                var dh = AccessTools.TypeByName("Coop.Core.Server.Services.Players.Handlers.DisconnectedPlayersServerHandler");
                var pol = dh == null ? null : AccessTools.Method(dh, "PlayersConnectedPolicy");
                if (pol != null && pol.ReturnType == typeof(bool)) harmony.Patch(pol, null, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeAllowPostfix", st)));
                var pw = dh == null ? null : AccessTools.Method(dh, "PauseWhenNoPlayersConnected");
                if (pw != null) harmony.Patch(pw, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeSkipPrefix", st)));
                var opm = AccessTools.TypeByName("Coop.Core.Server.Services.Time.OverloadedPeerManager");
                var opPause = opm == null ? null : AccessTools.Method(opm, "PauseTime");
                var opResume = opm == null ? null : AccessTools.Method(opm, "ResumeTime");
                if (opPause != null) harmony.Patch(opPause, new HarmonyMethod(typeof(AdminHost).GetMethod("CatchUpPausePrefix", st)));
                if (opResume != null) harmony.Patch(opResume, new HarmonyMethod(typeof(AdminHost).GetMethod("CatchUpResumePrefix", st)));
                Log.W("AdminTime: join catch-up pause is " + (opPause != null && opResume != null ? "respected" : "NOT FOUND"));
                MethodInfo opCheck = null;
                if (opm != null) foreach (var m in opm.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
                    if (m.Name == "CheckForOverloadedPeers" && m.GetParameters().Length == 1) opCheck = m;
                if (opCheck != null) harmony.Patch(opCheck, null, new HarmonyMethod(typeof(AdminHost).GetMethod("JoinHoldPostfix", st)));
                Log.W("AdminTime: join hold (pause while a player loads) is " + (opCheck != null ? "ON" : "NOT FOUND"));
                JoinSync.Setup(harmony);
                Log.W("AdminTime: player time requests " + (req != null ? "blocked" : "NOT FOUND") + ", no-players pause " + (pol != null && pw != null ? "off" : "NOT FOUND") + " (always=" + cfg.AlwaysTime + ")");
            }
            catch (Exception e) { Log.W("AdminTime setup: " + (e.InnerException ?? e).Message); }
        }

