// =====================================================================================
//  system/HeroCard.cs — «كارت البطل» اللي بيظهر في مجلس النسب
//  وإنت جوه العالم: كل دقيقة بنكتب بيانات بطلك (الاسم، العشيرة، الجيش، أعلى المهارات، آخر مكان...)
//  في Modules\Coop\aurelion\hero-<الخانة>.json، ولما شاشة فيها بطلك كامل (الشنطة / الفرقة) تفتح بناخد صورته
//  من نفس الرسمة اللي اللعبة رسمتها ونحفظها hero-<الخانة>.png.
//  مجلس النسب بيقرا الملفين دول: بطلك الحقيقي بعدّته وحصانه، وأرقامه. لو مفيش صورة لسه، صورة شعبه هي اللي بتظهر.
//  كله على جهاز اللاعب بس، ومفيش أي حاجة بتتبعت للسيرفر.
// =====================================================================================
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using HarmonyLib;
using TaleWorlds.CampaignSystem;
using TaleWorlds.CampaignSystem.Party;
using TaleWorlds.Core;

namespace Aurelion.Core
{
    public static class HeroCard
    {
        static bool hooked; static int errors;
        static DateTime nextWrite = DateTime.MinValue;
        static readonly List<WeakReference> tableaus = new List<WeakReference>();
        static System.Reflection.FieldInfo fChar, fMount, fEquip, fFinal;
        static System.Reflection.PropertyInfo pTex;
        static string savedKey; static DateTime seenSince = DateTime.MinValue; static object seenTab;

        public static readonly string[] SkillIds = { "OneHanded", "TwoHanded", "Polearm", "Bow", "Crossbow", "Throwing", "Riding", "Athletics", "Crafting", "Scouting", "Tactics", "Roguery", "Charm", "Leadership", "Trade", "Steward", "Medicine", "Engineering" };

        public static string Dir
        {
            get { return Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(HeroCard).Assembly.Location), "..", "..", "aurelion")); }
        }
        public static string JsonPath(int slot) { return Path.Combine(Dir, "hero-" + slot + ".json"); }
        public static string PicPath(int slot) { return Path.Combine(Dir, "hero-" + slot + ".png"); }
        // which card this world feeds: the slot chosen in the hall. A world joined some other way (or a local campaign) feeds none;
        // on team machines (dev-tools marker) a local campaign writes card 9, which the hall never shows.
        static int Slot { get { return Slots.Chosen > 0 ? Slots.Chosen : (UiHerald.Dev ? 9 : 0); } }

        static void Hook()
        {
            hooked = true;
            try
            {
                var t = AccessTools.TypeByName("TaleWorlds.MountAndBlade.View.Tableaus.CharacterTableau");
                var m = t == null ? null : AccessTools.Method(t, "FirstTimeInit");
                if (m == null || SubModule.H == null) { Log.W("HeroCard: hero picture not found, the choice shows the culture art"); return; }
                fChar = AccessTools.Field(t, "_charStringId"); fMount = AccessTools.Field(t, "_mountCreationKey");
                fEquip = AccessTools.Field(t, "_equipmentCode"); fFinal = AccessTools.Field(t, "_isFinalized");
                pTex = AccessTools.Property(t, "Texture");
                SubModule.H.Patch(m, postfix: new HarmonyMethod(typeof(HeroCard), "Seen"));
                Log.W("HeroCard: ready");
            }
            catch (Exception e) { Log.W("HeroCard: hook failed: " + e.Message); }
        }

        public static void Seen(object __instance)
        {
            try { lock (tableaus) { tableaus.RemoveAll(w => !w.IsAlive); tableaus.Add(new WeakReference(__instance)); } } catch { }
        }

        // every frame (cheap: real work once a second at most)
        static string fixPath; static DateTime fixAfter, fixSince; static int fixTries; static long fixLen;
        static void FixPicture()
        {
            if (fixPath == null || DateTime.UtcNow < fixAfter) return;
            fixAfter = DateTime.UtcNow.AddSeconds(1);
            var fi = new FileInfo(fixPath);
            if (!fi.Exists || fi.LastWriteTimeUtc < fixSince.AddSeconds(-1)) { if (++fixTries > 20) { Log.W("HeroCard: the engine never wrote the picture"); fixPath = null; } return; }
            if (fi.Length != fixLen) { fixLen = fi.Length; return; }   // still being written
            var p = fixPath; fixPath = null;
            try { Png.SwapRedBlue(p); Log.W("HeroCard: picture colours fixed and cropped"); }
            catch (Exception e) { Log.W("HeroCard: colour fix failed: " + e.Message); }
        }
        public static void Tick()
        {
            if (!hooked) Hook();
            var c = Campaign.Current; var h = Hero.MainHero;
            if (c == null || h == null || Slot == 0) return;
            try
            {
                if (DateTime.UtcNow >= nextWrite) { nextWrite = DateTime.UtcNow.AddSeconds(60); Write(h); }
                Capture(h);
                FixPicture();
            }
            catch (Exception e) { if (++errors <= 3) Log.W("HeroCard: " + e.Message); }
        }

        // the hero as the game drew him in a screen of his own (inventory / party): full body, his gear, his horse
        static void Capture(Hero h)
        {
            if (fChar == null || pTex == null) return;
            object best = null;
            var id = h.CharacterObject != null ? h.CharacterObject.StringId : null;
            lock (tableaus)
                foreach (var w in tableaus)
                {
                    var t = w.Target; if (t == null) continue;
                    if (fFinal != null && (bool)fFinal.GetValue(t)) continue;
                    if (!string.Equals(fChar.GetValue(t) as string, id, StringComparison.Ordinal)) continue;
                    best = t;
                }
            if (best == null) { seenTab = null; return; }
            if (!ReferenceEquals(best, seenTab)) { seenTab = best; seenSince = DateTime.UtcNow; return; }
            if ((DateTime.UtcNow - seenSince).TotalSeconds < 2.5) return;   // let the gear and the horse finish loading
            var key = (fEquip.GetValue(best) as string ?? "") + "|" + (fMount.GetValue(best) as string ?? "") + "|" + Slot;
            if (key == savedKey) return;
            savedKey = key;
            var tex = pTex.GetValue(best, null);   // TaleWorlds.Engine.Texture, used by reflection (its base types live in an assembly the build does not reference)
            if (tex == null) return;
            Directory.CreateDirectory(Dir);
            var path = PicPath(Slot);
            var save = tex.GetType().GetMethod("SaveToFile", new[] { typeof(string), typeof(bool) });
            if (save == null) { Log.W("HeroCard: picture can not be saved in this game build"); return; }
            save.Invoke(tex, new object[] { path, false });
            // the engine writes the file later, on its own thread, and in BGRA: fix it once it is there and no longer changing
            fixPath = path; fixAfter = DateTime.UtcNow.AddSeconds(1.5); fixSince = DateTime.UtcNow; fixTries = 0; fixLen = -1;
            Log.W("HeroCard: picture saved for card " + Slot + " (" + Traverse.Create(tex).Property("Width").GetValue() + "x" + Traverse.Create(tex).Property("Height").GetValue() + ")");
            Write(h);
        }

        static void Write(Hero h)
        {
            var sb = new StringBuilder("{");
            Action<string, string> s = (k, v) => { if (sb.Length > 1) sb.Append(','); sb.Append('"').Append(k).Append("\":\"").Append(Esc(v)).Append('"'); };
            Action<string, double> n = (k, v) => { if (sb.Length > 1) sb.Append(','); sb.Append('"').Append(k).Append("\":").Append(v.ToString("0.##", CultureInfo.InvariantCulture)); };
            var ch = h.CharacterObject;
            s("name", h.Name != null ? h.Name.ToString() : "");
            s("culture", ch != null && ch.Culture != null ? ch.Culture.StringId : "");
            s("cultureName", ch != null && ch.Culture != null && ch.Culture.Name != null ? ch.Culture.Name.ToString() : "");
            s("clan", h.Clan != null && h.Clan.Name != null ? h.Clan.Name.ToString() : "");
            s("kingdom", h.Clan != null && h.Clan.Kingdom != null && h.Clan.Kingdom.Name != null ? h.Clan.Kingdom.Name.ToString() : "");
            n("tier", h.Clan != null ? h.Clan.Tier : 0);
            n("renown", h.Clan != null ? Math.Round(h.Clan.Renown) : 0);
            n("level", ch != null ? ch.Level : 0);
            n("age", Math.Floor(h.Age));
            n("gold", h.Gold);
            var mp = MobileParty.MainParty;
            if (mp != null)
            {
                try { n("troops", mp.MemberRoster.TotalManCount); n("troopLimit", mp.Party.PartySizeLimit); } catch { }
                try
                {
                    var st = mp.CurrentSettlement ?? mp.LastVisitedSettlement;
                    if (st != null && st.Name != null) { s("place", st.Name.ToString()); n("inPlace", mp.CurrentSettlement != null ? 1 : 0); }
                }
                catch { }
            }
            // the three best skills, with their focus points
            var list = new List<KeyValuePair<int, int[]>>();
            var all = AllSkills();
            for (int i = 0; i < all.Length; i++)
            {
                if (all[i] == null) continue;
                int v = 0, f = 0;
                try { v = h.GetSkillValue(all[i]); f = h.HeroDeveloper != null ? h.HeroDeveloper.GetFocus(all[i]) : 0; } catch { }
                list.Add(new KeyValuePair<int, int[]>(i, new[] { v, f }));
            }
            list.Sort((a, b) => b.Value[0] != a.Value[0] ? b.Value[0].CompareTo(a.Value[0]) : b.Value[1].CompareTo(a.Value[1]));
            sb.Append(",\"skills\":[");
            for (int i = 0; i < Math.Min(3, list.Count); i++)
            {
                if (i > 0) sb.Append(',');
                sb.Append("{\"i\":").Append(list[i].Key).Append(",\"v\":").Append(list[i].Value[0]).Append(",\"f\":").Append(list[i].Value[1]).Append('}');
            }
            sb.Append(']');
            s("saved", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture));
            sb.Append('}');
            Directory.CreateDirectory(Dir);
            var tmp = JsonPath(Slot) + ".tmp";
            File.WriteAllText(tmp, sb.ToString(), new UTF8Encoding(false));
            if (File.Exists(JsonPath(Slot))) File.Replace(tmp, JsonPath(Slot), null); else File.Move(tmp, JsonPath(Slot));
        }

        static SkillObject[] skills;
        public static SkillObject[] AllSkills()
        {
            if (skills != null) return skills;
            var r = new SkillObject[18];
            try
            {
                r[0] = DefaultSkills.OneHanded; r[1] = DefaultSkills.TwoHanded; r[2] = DefaultSkills.Polearm; r[3] = DefaultSkills.Bow; r[4] = DefaultSkills.Crossbow; r[5] = DefaultSkills.Throwing;
                r[6] = DefaultSkills.Riding; r[7] = DefaultSkills.Athletics; r[8] = DefaultSkills.Crafting; r[9] = DefaultSkills.Scouting; r[10] = DefaultSkills.Tactics; r[11] = DefaultSkills.Roguery;
                r[12] = DefaultSkills.Charm; r[13] = DefaultSkills.Leadership; r[14] = DefaultSkills.Trade; r[15] = DefaultSkills.Steward; r[16] = DefaultSkills.Medicine; r[17] = DefaultSkills.Engineering;
            }
            catch { }
            skills = r; return r;
        }

        static string Esc(string v)
        {
            if (string.IsNullOrEmpty(v)) return "";
            var b = new StringBuilder();
            foreach (var ch in v)
            {
                if (ch == '"' || ch == '\\') b.Append('\\').Append(ch);
                else if (ch < ' ') b.Append(' ');
                else b.Append(ch);
            }
            return b.ToString();
        }

        // the chooser reads it back (null if this slot was never played on this computer)
        public static Dictionary<string, object> Read(int slot)
        {
            try
            {
                var p = JsonPath(slot);
                if (!File.Exists(p)) return null;
                return Mj.Parse(File.ReadAllText(p, Encoding.UTF8)) as Dictionary<string, object>;
            }
            catch { return null; }
        }
        public static readonly bool[] PicReady = new bool[3];
        // width / height straight from the PNG header (the picture is as big as the game drew it)
        public static void PicSize(int slot, out int w, out int h)
        {
            w = h = 0;
            try
            {
                using (var f = File.OpenRead(PicPath(slot)))
                {
                    var b = new byte[24]; if (f.Read(b, 0, 24) < 24) return;
                    if (b[1] != 'P' || b[2] != 'N' || b[3] != 'G') return;
                    w = (b[16] << 24) | (b[17] << 16) | (b[18] << 8) | b[19];
                    h = (b[20] << 24) | (b[21] << 16) | (b[22] << 8) | b[23];
                }
            }
            catch { }
        }
        public static bool HasPicture(int slot) { try { return File.Exists(PicPath(slot)); } catch { return false; } }
    }

    // a small PNG reader/writer (8-bit RGB/RGBA, as the engine writes it): swaps the red and blue channels in place
    static class Png
    {
        public static void SwapRedBlue(string path)
        {
            var data = File.ReadAllBytes(path);
            int w = 0, h = 0, bitDepth = 0, colorType = 0, interlace = 0;
            var idat = new MemoryStream();
            int pos = 8;
            while (pos + 8 <= data.Length)
            {
                int len = (data[pos] << 24) | (data[pos + 1] << 16) | (data[pos + 2] << 8) | data[pos + 3];
                string type = Encoding.ASCII.GetString(data, pos + 4, 4);
                int body = pos + 8;
                if (type == "IHDR")
                {
                    w = (data[body] << 24) | (data[body + 1] << 16) | (data[body + 2] << 8) | data[body + 3];
                    h = (data[body + 4] << 24) | (data[body + 5] << 16) | (data[body + 6] << 8) | data[body + 7];
                    bitDepth = data[body + 8]; colorType = data[body + 9]; interlace = data[body + 12];
                }
                else if (type == "IDAT") idat.Write(data, body, len);
                else if (type == "IEND") break;
                pos = body + len + 4;
            }
            if (w <= 0 || h <= 0 || bitDepth != 8 || interlace != 0 || (colorType != 6 && colorType != 2)) throw new Exception("png format " + colorType + "/" + bitDepth);
            int bpp = colorType == 6 ? 4 : 3, stride = w * bpp;
            var raw = new byte[(stride + 1) * h];
            idat.Position = 2;   // zlib header
            using (var z = new System.IO.Compression.DeflateStream(idat, System.IO.Compression.CompressionMode.Decompress))
            {
                int got = 0, n;
                while (got < raw.Length && (n = z.Read(raw, got, raw.Length - got)) > 0) got += n;
                if (got < raw.Length) throw new Exception("png data short");
            }
            var px = new byte[stride * h];
            for (int y = 0; y < h; y++)
            {
                int f = raw[y * (stride + 1)], src = y * (stride + 1) + 1, dst = y * stride, up = dst - stride;
                for (int x = 0; x < stride; x++)
                {
                    int a = x >= bpp ? px[dst + x - bpp] : 0, b = y > 0 ? px[up + x] : 0, c = (x >= bpp && y > 0) ? px[up + x - bpp] : 0, v = raw[src + x];
                    switch (f)
                    {
                        case 1: v += a; break;
                        case 2: v += b; break;
                        case 3: v += (a + b) >> 1; break;
                        case 4: { int p0 = a + b - c, pa = Math.Abs(p0 - a), pb = Math.Abs(p0 - b), pc = Math.Abs(p0 - c); v += (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c); break; }
                    }
                    px[dst + x] = (byte)v;
                }
            }
            for (int i = 0; i + 2 < px.Length; i += bpp) { var t = px[i]; px[i] = px[i + 2]; px[i + 2] = t; }
            // keep only the hero (and his horse and shadow): crop to what is drawn, with a small margin
            if (bpp == 4)
            {
                int x0 = w, y0 = h, x1 = -1, y1 = -1;
                for (int y = 0; y < h; y++)
                    for (int x = 0; x < w; x++)
                        if (px[y * stride + x * 4 + 3] > 12) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
                if (x1 > x0 && y1 > y0)
                {
                    int m = Math.Max(8, (y1 - y0) / 25);
                    x0 = Math.Max(0, x0 - m); y0 = Math.Max(0, y0 - m); x1 = Math.Min(w - 1, x1 + m); y1 = Math.Min(h - 1, y1 + m);
                    int nw = x1 - x0 + 1, nh = y1 - y0 + 1, ns = nw * 4;
                    var cut = new byte[ns * nh];
                    for (int y = 0; y < nh; y++) Buffer.BlockCopy(px, (y0 + y) * stride + x0 * 4, cut, y * ns, ns);
                    px = cut; w = nw; h = nh; stride = ns;
                }
            }
            // write: filter 0 rows, zlib (stored header + deflate + adler32)
            var rows = new byte[(stride + 1) * h];
            for (int y = 0; y < h; y++) Buffer.BlockCopy(px, y * stride, rows, y * (stride + 1) + 1, stride);
            var zs = new MemoryStream();
            zs.WriteByte(0x78); zs.WriteByte(0x9C);
            using (var d = new System.IO.Compression.DeflateStream(zs, System.IO.Compression.CompressionMode.Compress, true)) d.Write(rows, 0, rows.Length);
            uint s1 = 1, s2 = 0;
            foreach (var bt in rows) { s1 = (s1 + bt) % 65521; s2 = (s2 + s1) % 65521; }
            uint adler = (s2 << 16) | s1;
            zs.WriteByte((byte)(adler >> 24)); zs.WriteByte((byte)(adler >> 16)); zs.WriteByte((byte)(adler >> 8)); zs.WriteByte((byte)adler);
            var outp = new MemoryStream();
            outp.Write(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 }, 0, 8);
            var ihdr = new byte[13];
            ihdr[0] = (byte)(w >> 24); ihdr[1] = (byte)(w >> 16); ihdr[2] = (byte)(w >> 8); ihdr[3] = (byte)w;
            ihdr[4] = (byte)(h >> 24); ihdr[5] = (byte)(h >> 16); ihdr[6] = (byte)(h >> 8); ihdr[7] = (byte)h;
            ihdr[8] = 8; ihdr[9] = (byte)colorType;
            Chunk(outp, "IHDR", ihdr); Chunk(outp, "IDAT", zs.ToArray()); Chunk(outp, "IEND", new byte[0]);
            var tmp = path + ".tmp";
            File.WriteAllBytes(tmp, outp.ToArray());
            File.Delete(path); File.Move(tmp, path);
        }
        static uint[] crcTable;
        static void Chunk(Stream o, string type, byte[] body)
        {
            if (crcTable == null)
            {
                crcTable = new uint[256];
                for (uint n = 0; n < 256; n++) { uint c = n; for (int k = 0; k < 8; k++) c = (c & 1) != 0 ? 0xEDB88320u ^ (c >> 1) : c >> 1; crcTable[n] = c; }
            }
            var t = Encoding.ASCII.GetBytes(type);
            o.WriteByte((byte)(body.Length >> 24)); o.WriteByte((byte)(body.Length >> 16)); o.WriteByte((byte)(body.Length >> 8)); o.WriteByte((byte)body.Length);
            o.Write(t, 0, 4); o.Write(body, 0, body.Length);
            uint crc = 0xFFFFFFFFu;
            foreach (var b in t) crc = crcTable[(crc ^ b) & 0xFF] ^ (crc >> 8);
            foreach (var b in body) crc = crcTable[(crc ^ b) & 0xFF] ^ (crc >> 8);
            crc ^= 0xFFFFFFFFu;
            o.WriteByte((byte)(crc >> 24)); o.WriteByte((byte)(crc >> 16)); o.WriteByte((byte)(crc >> 8)); o.WriteByte((byte)crc);
        }
    }
