// =====================================================================================
//  system/JoinSync.cs — joining the campaign without stopping the world (server side only)
//
//  Measured 13/11 (JoinSync probe): the joiner's catch-up queue grows ~1100 packets/s from the moment
//  the save is taken; the save transfer + loading take ~80 s, then Coop replays the queue in batches of
//  at most 512 packets, each sent as its own reliable packet and each batch waiting for the client's ack.
//  That replay (~1000 packets/s) is no faster than the world produces new packets, so the queue only
//  grows until Coop's 100,000 limit ends the join. Stopping the clock for the whole join (v10) fixed it
//  but froze every player for ~3 minutes.
//
//  The fix (v12):
//   1. Replay batches are sent the way Coop sends live traffic: many messages packed into one
//      AggregateMessagePacket (same client handler, same order), and a batch may hold 8192 packets /
//      512 KB instead of 512 / 64 KB. The replay drains many times faster than the world fills it.
//   2. Safety: the queue limits are raised to 600,000 packets / 512 MB (memory ~20 MB at worst).
//   3. Last resort: if a replay has run 20 s, is still far behind and is NOT shrinking (less than 10 %
//      in the last 10 s), campaign time is held for at most 10 s in total for that player (AdminHost
//      takes the same automatic-pause lease Coop uses). Test 13/11 (v12): 84k queue replayed in ~40 s.
//
//  Switches (files in C:\ProgramData\Aurelion\Admin):
//    joinhold-never.txt    never hold campaign time for a join (not even the 10 s last resort)
//    joinreplay-plain.txt  send the replay the old way (one packet per message) — for comparison only
//  Reflection + Harmony only; never throws into Coop.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class JoinSync
    {
        const BindingFlags All = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
        static readonly string Dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Aurelion", "Admin");
        static bool ready;
        static DateTime nextTick = DateTime.MinValue, nextSwitch = DateTime.MinValue, nextDepth = DateTime.MinValue, nextHist = DateTime.MinValue, nextRate = DateTime.MinValue;
        static bool holdOff, replayPlain, wantHold;
        public const int QueuePacketLimit = 600000, QueueByteLimit = 536870912, BatchPackets = 8192, BatchBytes = 524288, AggregateBytes = 8192;
        static bool limitsSet;
        static readonly Dictionary<object, DateTime> replaySince = new Dictionary<object, DateTime>();
        static readonly Dictionary<object, double> holdUsed = new Dictionary<object, double>();
        static readonly Dictionary<object, Queue<KeyValuePair<DateTime, int>>> depthHistory = new Dictionary<object, Queue<KeyValuePair<DateTime, int>>>();
        static DateTime lastHoldTick = DateTime.MinValue;
        static FieldInfo fConns, fQueue, fChannels, fPending, fGate, fMsgType, fData;
        static MethodInfo mRemaining;
        static readonly Dictionary<object, string> lastState = new Dictionary<object, string>();
        static readonly Dictionary<object, DateTime> stateSince = new Dictionary<object, DateTime>();

        // broadcast statistics (all peers): type -> count, bytes
        static readonly object rateLock = new object();
        static Dictionary<string, long[]> rate = new Dictionary<string, long[]>();
        static DateTime rateSince = DateTime.UtcNow;

        public static bool HoldOff { get { return holdOff; } }
        public static bool WantHold { get { return wantHold && !holdOff; } }
        public static int LimitPackets() { return QueuePacketLimit; }
        public static int LimitBytes() { return QueueByteLimit; }
        public static int BatchPacketLimit() { return replayPlain ? 512 : BatchPackets; }
        public static int BatchByteLimit() { return replayPlain ? 65536 : BatchBytes; }

        public static void Setup(Harmony h)
        {
            if (ready || h == null) return;
            ready = true;
            try
            {
                var opm = AccessTools.TypeByName("Coop.Core.Server.Services.Time.OverloadedPeerManager");
                MethodInfo check = null;
                if (opm != null) foreach (var m in opm.GetMethods(All)) if (m.Name == "CheckForOverloadedPeers" && m.GetParameters().Length == 1) check = m;
                if (check != null) h.Patch(check, null, new HarmonyMethod(typeof(JoinSync).GetMethod("TickPostfix", BindingFlags.Static | BindingFlags.Public)));
                var cmq = AccessTools.TypeByName("Coop.Core.Server.Connections.ConnectionMessageQueue");
                var thb = cmq == null ? null : AccessTools.Method(cmq, "TryHandleBroadcast");
                if (thb != null) h.Patch(thb, new HarmonyMethod(typeof(JoinSync).GetMethod("BroadcastPrefix", BindingFlags.Static | BindingFlags.Public)));
                var mp = AccessTools.TypeByName("Common.PacketHandlers.MessagePacket");
                if (mp != null) { fMsgType = mp.GetField("MessageType", All); fData = mp.GetField("Data", All); }
                Log.W("JoinSync: probe " + (check != null && thb != null ? "ON" : "PARTIAL") + " (join timeline + broadcast types)");

                // 1+2: faster replay and higher limits
                aggType = AccessTools.TypeByName("Common.PacketHandlers.AggregateMessagePacket");
                var ipacket = AccessTools.TypeByName("Common.PacketHandlers.IPacket");
                var inet = AccessTools.TypeByName("Common.Network.INetwork");
                if (inet != null && ipacket != null) foreach (var m in inet.GetMethods()) { var ps = m.GetParameters(); if (m.Name == "SendImmediate" && ps.Length == 2 && ps[1].ParameterType == ipacket) sendImmediate = m; }
                aggCtor = aggType == null ? null : aggType.GetConstructor(new[] { typeof(byte[][]) });
                var drain = cmq == null ? null : AccessTools.Method(cmq, "DrainBatch");
                int patched = 0;
                if (drain != null && aggCtor != null && sendImmediate != null && fData != null)
                {
                    h.Patch(drain, null, new HarmonyMethod(typeof(JoinSync).GetMethod("DrainPostfix", BindingFlags.Static | BindingFlags.Public)), new HarmonyMethod(typeof(JoinSync).GetMethod("DrainTranspiler", BindingFlags.Static | BindingFlags.Public)));
                    patched++;
                }
                if (opm != null)
                    foreach (var name in new[] { "AbortStalledJoiners", "AbortStalledPreEntryJoiners" })
                    {
                        var m = AccessTools.Method(opm, name);
                        if (m != null) { h.Patch(m, null, null, new HarmonyMethod(typeof(JoinSync).GetMethod("LimitTranspiler", BindingFlags.Static | BindingFlags.Public))); patched++; }
                    }
                Log.W("JoinSync: fast replay " + (drain != null && aggCtor != null && sendImmediate != null ? "ON (aggregate, " + BatchPackets + " packets / " + (BatchBytes / 1024) + " KB per batch)" : "NOT AVAILABLE") + ", queue limit " + QueuePacketLimit + " (" + patched + " patches)");
            }
            catch (Exception e) { Log.W("JoinSync setup: " + (e.InnerException ?? e).Message); }
        }

        static string TypeKey(object packet, out int bytes)
        {
            bytes = 0;
            if (packet == null) return "null";
            var t = packet.GetType();
            if (fMsgType != null && t == fMsgType.DeclaringType)
            {
                var mt = fMsgType.GetValue(packet) as Type;
                var d = fData == null ? null : fData.GetValue(packet) as byte[];
                if (d != null) bytes = d.Length;
                return mt == null ? "Message?" : mt.Name;
            }
            return t.Name;
        }

        // counts every broadcast once (the first peer it is offered to in this frame is enough for a rate)
        static object lastPacketRef; static int lastPacketHash;
        public static void BroadcastPrefix(object peer, object packet)
        {
            try
            {
                int h = packet == null ? 0 : packet.GetHashCode();
                lock (rateLock)
                {
                    if (h == lastPacketHash && ReferenceEquals(packet, lastPacketRef)) return;
                    lastPacketHash = h; lastPacketRef = packet;
                    int b; var k = TypeKey(packet, out b);
                    long[] v; if (!rate.TryGetValue(k, out v)) { v = new long[2]; rate[k] = v; }
                    v[0]++; v[1] += b;
                }
            }
            catch { }
        }

        public static void TickPostfix(object __instance)
        {
            var now = DateTime.UtcNow;
            if (now < nextTick) return;
            nextTick = now.AddMilliseconds(250);
            try
            {
                if (now >= nextSwitch) { nextSwitch = now.AddSeconds(3); holdOff = File.Exists(Path.Combine(Dir, "joinhold-never.txt")); replayPlain = File.Exists(Path.Combine(Dir, "joinreplay-plain.txt")); }
                if (fConns == null) { fConns = AccessTools.Field(__instance.GetType(), "connectionCollection"); fQueue = AccessTools.Field(__instance.GetType(), "connectionMessageQueue"); }
                var conns = fConns == null ? null : fConns.GetValue(__instance) as IEnumerable;
                var queue = fQueue == null ? null : fQueue.GetValue(__instance);
                if (!limitsSet && queue != null)
                {
                    limitsSet = true;
                    try
                    {
                        var fp = AccessTools.Field(queue.GetType(), "maxPendingPackets"); var fb = AccessTools.Field(queue.GetType(), "maxPendingBytes");
                        if (fp != null) fp.SetValue(queue, QueuePacketLimit);
                        if (fb != null) fb.SetValue(queue, (long)QueueByteLimit);
                        Log.W("JoinSync: queue limits now " + (fp == null ? "?" : fp.GetValue(queue).ToString()) + " packets / " + (fb == null ? "?" : fb.GetValue(queue).ToString()) + " bytes");
                    }
                    catch (Exception e) { Log.W("JoinSync limits: " + (e.InnerException ?? e).Message); }
                }
                bool anyLoading = false; int peers = 0;
                var seen = new HashSet<object>();
                if (conns != null)
                    foreach (var c in conns)
                    {
                        peers++;
                        var peer = Get(c, "Peer"); if (peer == null) continue;
                        seen.Add(peer);
                        var st = Get(c, "State");
                        var name = st == null ? "none" : st.GetType().Name;
                        var il = st == null ? null : Get(st, "IsLoading");
                        if (il is bool && (bool)il) anyLoading = true;
                        var phase = st == null ? null : Get(st, "JoinPhaseName");
                        if (phase != null) name += "/" + phase;
                        string old;
                        if (!lastState.TryGetValue(peer, out old) || old != name)
                        {
                            DateTime since; double secs = stateSince.TryGetValue(peer, out since) ? (now - since).TotalSeconds : 0;
                            Log.W("JoinSync: peer " + PeerId(peer) + " " + (old ?? "connected") + " -> " + name + (old != null ? " (after " + secs.ToString("0.0", CultureInfo.InvariantCulture) + "s)" : "") + " depth=" + Depth(queue, peer));
                            lastState[peer] = name; stateSince[peer] = now;
                        }
                    }
                foreach (var k in lastState.Keys.ToList()) if (!seen.Contains(k)) { Log.W("JoinSync: peer " + PeerId(k) + " left (" + lastState[k] + ")"); lastState.Remove(k); stateSince.Remove(k); replaySince.Remove(k); holdUsed.Remove(k); depthHistory.Remove(k); }

                // last resort hold: a replay running >= 20 s that is still far behind, at most 10 s per player
                bool want = false; double dt = lastHoldTick == DateTime.MinValue ? 0 : Math.Min(1, (now - lastHoldTick).TotalSeconds); lastHoldTick = now;
                foreach (var p in seen)
                {
                    string st; lastState.TryGetValue(p, out st);
                    bool inReplay = st != null && st.IndexOf("Replay", StringComparison.OrdinalIgnoreCase) >= 0;
                    if (!inReplay) { replaySince.Remove(p); depthHistory.Remove(p); continue; }
                    DateTime rs; if (!replaySince.TryGetValue(p, out rs)) { rs = now; replaySince[p] = now; }
                    double used; holdUsed.TryGetValue(p, out used);
                    if (wantHold) { used += dt; holdUsed[p] = used; }
                    int depth = Depth(queue, p);
                    Queue<KeyValuePair<DateTime, int>> hist; if (!depthHistory.TryGetValue(p, out hist)) { hist = new Queue<KeyValuePair<DateTime, int>>(); depthHistory[p] = hist; }
                    hist.Enqueue(new KeyValuePair<DateTime, int>(now, depth));
                    while (hist.Count > 0 && (now - hist.Peek().Key).TotalSeconds > 10.5) hist.Dequeue();
                    bool shrinking = true;
                    if (hist.Count > 0 && (now - hist.Peek().Key).TotalSeconds >= 9.5) { int old = hist.Peek().Value; shrinking = old - depth >= old / 10; }
                    if ((now - rs).TotalSeconds >= 20 && used < 10 && depth > 2000 && !shrinking) want = true;
                }
                if (want != wantHold) Log.W("JoinSync: last-resort hold " + (want ? "ON (replay still far behind after 20 s)" : "OFF"));
                wantHold = want;

                if (anyLoading && now >= nextDepth)
                {
                    nextDepth = now.AddSeconds(3);
                    var sb = new StringBuilder();
                    foreach (var p in seen) { int d = Depth(queue, p); if (d >= 0) sb.Append(" " + PeerId(p) + "=" + d); }
                    if (sb.Length > 0) Log.W("JoinSync: queue" + sb + " mode=" + AdminHostMode());
                }
                if (anyLoading && now >= nextHist) { nextHist = now.AddSeconds(15); Histogram(queue, seen); }
                if (now >= nextRate) { nextRate = now.AddSeconds(peers > 0 ? 60 : 300); RateReport(now); }
            }
            catch (Exception e) { Log.W("JoinSync tick: " + (e.InnerException ?? e).Message); nextTick = now.AddSeconds(30); }
        }

        static string AdminHostMode() { try { return Convert.ToString(typeof(AdminHost).GetMethod("CampaignMode", BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public).Invoke(null, null)); } catch { return "?"; } }

        static void RateReport(DateTime now)
        {
            Dictionary<string, long[]> snap; DateTime since;
            lock (rateLock) { snap = rate; rate = new Dictionary<string, long[]>(); since = rateSince; rateSince = now; }
            double secs = Math.Max(1, (now - since).TotalSeconds);
            long total = 0, bytes = 0; foreach (var v in snap.Values) { total += v[0]; bytes += v[1]; }
            if (total == 0) return;
            var sb = new StringBuilder();
            sb.Append("JoinSync: broadcasts " + (total / secs).ToString("0", CultureInfo.InvariantCulture) + "/s, " + (bytes / secs / 1024).ToString("0.0", CultureInfo.InvariantCulture) + " KB/s over " + secs.ToString("0") + "s; top:");
            foreach (var kv in snap.OrderByDescending(x => x.Value[0]).Take(15))
                sb.Append(" " + kv.Key + "=" + (kv.Value[0] / secs).ToString("0.0", CultureInfo.InvariantCulture) + "/s(" + (kv.Value[0] == 0 ? 0 : kv.Value[1] / kv.Value[0]) + "B)");
            Log.W(sb.ToString());
        }

        static int Depth(object queue, object peer)
        {
            try
            {
                if (queue == null) return -1;
                if (mRemaining == null) mRemaining = queue.GetType().GetMethod("TryGetCatchUpPacketsRemaining", All);
                if (mRemaining == null) return -1;
                var args = new object[] { peer, 0 };
                var ok = mRemaining.Invoke(queue, args);
                return ok is bool && (bool)ok ? (int)args[1] : -1;
            }
            catch { return -1; }
        }

        static void Histogram(object queue, IEnumerable<object> peers)
        {
            try
            {
                if (queue == null) return;
                if (fChannels == null) fChannels = AccessTools.Field(queue.GetType(), "channels");
                var dict = fChannels == null ? null : fChannels.GetValue(queue) as IDictionary;
                if (dict == null) return;
                foreach (var p in peers)
                {
                    if (!dict.Contains(p)) continue;
                    var ch = dict[p]; if (ch == null) continue;
                    if (fPending == null) { fPending = AccessTools.Field(ch.GetType(), "Pending"); fGate = AccessTools.Field(ch.GetType(), "Gate"); }
                    var list = fPending == null ? null : fPending.GetValue(ch) as IEnumerable;
                    var gate = fGate == null ? null : fGate.GetValue(ch);
                    if (list == null || gate == null) continue;
                    var counts = new Dictionary<string, long[]>(); int n = 0;
                    bool taken = false;
                    try
                    {
                        Monitor.TryEnter(gate, 200, ref taken);
                        if (!taken) continue;
                        foreach (var pk in list)
                        {
                            n++; int b; var k = TypeKey(pk, out b);
                            long[] v; if (!counts.TryGetValue(k, out v)) { v = new long[2]; counts[k] = v; }
                            v[0]++; v[1] += b;
                        }
                    }
                    finally { if (taken) Monitor.Exit(gate); }
                    if (n == 0) continue;
                    var sb = new StringBuilder("JoinSync: pending for " + PeerId(p) + " = " + n + "; top:");
                    foreach (var kv in counts.OrderByDescending(x => x.Value[0]).Take(12)) sb.Append(" " + kv.Key + "=" + kv.Value[0] + "(" + (kv.Value[1] / Math.Max(1, kv.Value[0])) + "B)");
                    Log.W(sb.ToString());
                }
            }
            catch (Exception e) { Log.W("JoinSync histogram: " + (e.InnerException ?? e).Message); }
        }

        // ---------------- fast replay: pack the batch into AggregateMessagePackets ----------------
        static Type aggType; static ConstructorInfo aggCtor; static MethodInfo sendImmediate;
        static object bufNet, bufPeer; static readonly List<byte[]> buf = new List<byte[]>(); static readonly List<object> bufPk = new List<object>(); static int bufBytes;
        static long replayMsgs, replayAggs; static DateTime replayLog = DateTime.MinValue;

        public static IEnumerable<CodeInstruction> DrainTranspiler(IEnumerable<CodeInstruction> instructions)
        {
            var send = typeof(JoinSync).GetMethod("ReplaySend", BindingFlags.Static | BindingFlags.Public);
            var bp = typeof(JoinSync).GetMethod("BatchPacketLimit", BindingFlags.Static | BindingFlags.Public);
            var bb = typeof(JoinSync).GetMethod("BatchByteLimit", BindingFlags.Static | BindingFlags.Public);
            int a = 0, b = 0, c = 0;
            foreach (var ci in instructions)
            {
                var mi = ci.operand as MethodInfo;
                if ((ci.opcode == System.Reflection.Emit.OpCodes.Callvirt || ci.opcode == System.Reflection.Emit.OpCodes.Call) && mi != null && mi.Name == "SendImmediate" && mi.GetParameters().Length == 2 && mi.GetParameters()[1].ParameterType.Name == "IPacket")
                { ci.opcode = System.Reflection.Emit.OpCodes.Call; ci.operand = send; a++; }
                else if (ci.opcode == System.Reflection.Emit.OpCodes.Ldc_I4 && ci.operand is int && (int)ci.operand == 512) { ci.opcode = System.Reflection.Emit.OpCodes.Call; ci.operand = bp; b++; }
                else if (ci.opcode == System.Reflection.Emit.OpCodes.Ldc_I4 && ci.operand is int && (int)ci.operand == 65536) { ci.opcode = System.Reflection.Emit.OpCodes.Call; ci.operand = bb; c++; }
                yield return ci;
            }
            Log.W("JoinSync: replay batch patch sends=" + a + " packetLimit=" + b + " byteLimit=" + c);
        }

        public static IEnumerable<CodeInstruction> LimitTranspiler(IEnumerable<CodeInstruction> instructions)
        {
            var lp = typeof(JoinSync).GetMethod("LimitPackets", BindingFlags.Static | BindingFlags.Public);
            var lb = typeof(JoinSync).GetMethod("LimitBytes", BindingFlags.Static | BindingFlags.Public);
            int a = 0, b = 0;
            foreach (var ci in instructions)
            {
                if (ci.opcode == System.Reflection.Emit.OpCodes.Ldc_I4 && ci.operand is int && (int)ci.operand == 100000) { ci.opcode = System.Reflection.Emit.OpCodes.Call; ci.operand = lp; a++; }
                else if (ci.opcode == System.Reflection.Emit.OpCodes.Ldc_I4 && ci.operand is int && (int)ci.operand == 134217728) { ci.opcode = System.Reflection.Emit.OpCodes.Call; ci.operand = lb; b++; }
                yield return ci;
            }
            Log.W("JoinSync: queue limit patch packets=" + a + " bytes=" + b);
        }

        // replaces INetwork.SendImmediate(peer, packet) inside DrainBatch; order is kept exactly
        public static void ReplaySend(object net, object peer, object packet)
        {
            try
            {
                if (!replayPlain && packet != null && fMsgType != null && packet.GetType() == fMsgType.DeclaringType)
                {
                    var d = fData.GetValue(packet) as byte[];
                    if (d != null)
                    {
                        if (bufNet != null && (!ReferenceEquals(bufNet, net) || !ReferenceEquals(bufPeer, peer))) Flush();
                        bufNet = net; bufPeer = peer; buf.Add(d); bufPk.Add(packet); bufBytes += d.Length + 4;
                        if (bufBytes >= AggregateBytes) Flush();
                        return;
                    }
                }
                Flush();
                sendImmediate.Invoke(net, new[] { peer, packet });
            }
            catch (Exception e)
            {
                Log.W("JoinSync replay send: " + (e.InnerException ?? e).Message);
                try { sendImmediate.Invoke(net, new[] { peer, packet }); } catch { }
            }
        }

        public static void DrainPostfix() { Flush(); }

        static void Flush()
        {
            if (buf.Count == 0 || bufNet == null) { buf.Clear(); bufPk.Clear(); bufBytes = 0; return; }
            var arr = buf.ToArray(); var pks = bufPk.ToArray(); var net = bufNet; var peer = bufPeer;
            buf.Clear(); bufPk.Clear(); bufBytes = 0;
            try
            {
                var agg = aggCtor.Invoke(new object[] { arr });
                sendImmediate.Invoke(net, new[] { peer, agg });
                replayMsgs += arr.Length; replayAggs++;
            }
            catch (Exception e)
            {
                Log.W("JoinSync aggregate send failed, sending one by one: " + (e.InnerException ?? e).Message);
                // never lose a message: fall back to the original packets
                foreach (var pk in pks)
                    try { sendImmediate.Invoke(net, new[] { peer, pk }); } catch { }
            }
            var now = DateTime.UtcNow;
            if (now >= replayLog) { replayLog = now.AddSeconds(5); Log.W("JoinSync: replay sent " + replayMsgs + " messages in " + replayAggs + " aggregate packets"); }
        }

        static string PeerId(object peer) { var id = Get(peer, "Id"); return "#" + (id == null ? "?" : id.ToString()); }

        static object Get(object o, string name)
        {
            if (o == null) return null;
            for (var t = o.GetType(); t != null; t = t.BaseType)
            {
                var p = t.GetProperty(name, All | BindingFlags.DeclaredOnly);
                if (p != null && p.GetIndexParameters().Length == 0) { try { return p.GetValue(o, null); } catch { return null; } }
                var f = t.GetField(name, All | BindingFlags.DeclaredOnly);
                if (f != null) { try { return f.GetValue(o); } catch { return null; } }
            }
            return null;
        }
    }
}

