// =====================================================================================
//  system/RulesGate.cs — مفتاح تشغيل قواعد اللعب كلها
//  ملف نظام: الاستوديو بيكتبه من جديد مع كل بناء. متعدّلش فيه.
//  قواعد اللعب (حد المهارات، سرعة الخبرة والشهرة، أسعار السوق) مش بتشتغل غير لما
//  "شغّل قواعد اللعب" يبقى متعلّم في صفحة قواعد اللعب في الاستوديو.
// =====================================================================================
using System;
using System.IO;
using System.Reflection;
using System.Text;

namespace Aurelion.Core
{
    public static class RulesGate
    {
        public static bool Enabled
        {
            get
            {
                try
                {
                    var dir = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "..", "..", "aurelion"));
                    var f = Path.Combine(dir, "rules.json");
                    if (!File.Exists(f)) return false;
                    var d = Mj.Parse(File.ReadAllText(f, Encoding.UTF8)) as System.Collections.Generic.Dictionary<string, object>;
                    return Mj.B(d, "enabled", false);
                }
                catch { return false; }
            }
        }
    }
}

src.system/Slots.cs:
// =====================================================================================
//  system/Slots.cs — شخصيتين لكل لاعب
//  الخانة 1 = رقم Steam بتاع اللاعب (زي ما هو، أبطال اللاعيبة الحاليين ما يتأثروش).
//  الخانة 2 = نفس الرقم + "~2"، فـCoop بيشوفها لاعب منفصل وبيفتح لها إنشاء شخصية جديدة (شاشة الثقافات بتاعتنا).
//  السيرفر:  الحظر والإدارة والتجربة بيشوفوا الخانتين لاعب واحد (ShortId)،
//            ومستحيل الخانتين يبقوا أونلاين مع بعض (فمفيش تبادل ولا هدايا ولا تجارة بينهم)،
//            وبوابة 4201 بتجاوب /slots?steam64= بملخص الخانتين.
//  اللاعب:   زرار Join بيفتح شاشة «اختار شخصيتك» (GUI\Prefabs\AurSlots.xml)، وبعد الاختيار بيدخل بالخانة دي.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Reflection;
using System.Threading;
using HarmonyLib;
using TaleWorlds.Engine.GauntletUI;
using TaleWorlds.Library;
using TaleWorlds.ScreenSystem;

namespace Aurelion.Core
{
    public static class Slots
    {
        public const string Suffix2 = "~2";
        public static int Max = 2;   // admin-config.json "slots": { "max": 2 } (1 = feature off)

        public static string ShortId(string cid)
        {
            if (cid == null) return null;
            return cid.EndsWith(Suffix2, StringComparison.Ordinal) ? cid.Substring(0, cid.Length - Suffix2.Length) : cid;
        }
        public static int SlotOf(string cid) { return cid != null && cid.EndsWith(Suffix2, StringComparison.Ordinal) ? 2 : 1; }

        // a dictionary keyed by this treats both slots of one player as the same key (admins, testers)
        public class SameIdComparer : IEqualityComparer<string>
        {
            public bool Equals(string a, string b) { return string.Equals(ShortId(a), ShortId(b), StringComparison.Ordinal); }
            public int GetHashCode(string s) { var k = ShortId(s); return k == null ? 0 : k.GetHashCode(); }
        }

        // ================================================================ server
        static Func<IEnumerable<string>> onlineIds;
        public static void InstallServer(Harmony h, Func<IEnumerable<string>> online)
        {
            onlineIds = online;
            try
            {
                var t = AccessTools.TypeByName("Coop.Core.Server.Connections.SteamBanList");
                var m = t == null ? null : AccessTools.Method(t, "IsBanned", new[] { typeof(string) });
                if (m == null) { Log.W("Slots: Coop join check not found, a second character can not be refused while the first is online"); return; }
                h.Patch(m, prefix: new HarmonyMethod(typeof(Slots), "JoinPrefix"));
                Log.W("Slots: ready (max " + Max + " characters per player)");
            }
            catch (Exception e) { Log.W("Slots: join check failed: " + (e.InnerException ?? e).Message); }
        }

        // Coop asks "is this player banned?" for every joiner, before it loads or creates the character.
        // Here: a ban on the Steam id covers both slots, slot 2 needs the feature on, and a slot is refused while the other is online.
        public static bool JoinPrefix(ref string controllerId, ref bool __result)
        {
            try
            {
                var full = controllerId;
                if (string.IsNullOrEmpty(full)) return true;
                var sid = ShortId(full);
                var tilde = sid.IndexOf('~');
                if (tilde >= 0) { __result = true; Log.W("Slots: refused unknown character slot " + full); return false; }
                if (full != sid && Max < 2) { __result = true; Log.W("Slots: refused " + full + " (second character is off)"); return false; }
                if (onlineIds != null)
                    foreach (var c in onlineIds())
                        if (c != null && c != full && ShortId(c) == sid)
                        {
                            __result = true;
                            Log.W("Slots: refused " + full + " because " + c + " (the same player) is online");
                            return false;
                        }
                controllerId = sid;   // the ban list itself is checked on the Steam id
                return true;
            }
            catch (Exception e) { Log.W("Slots: join check error: " + e.Message); return true; }
        }

        // /slots?steam64=… on the gateway: what each slot holds (from the server's own record of players)
        public static object Gateway(string steam64, Func<string, Dictionary<string, object>> knownOf, Func<string, bool> isOnline)
        {
            var r = new Dictionary<string, object>();
            r["max"] = Max;
            var list = new List<object>();
            if (!string.IsNullOrEmpty(steam64) && steam64.IndexOf('~') < 0)
                for (int s = 1; s <= Math.Max(1, Max); s++)
                {
                    var cid = s == 1 ? steam64 : steam64 + Suffix2;
                    var k = knownOf(cid);
                    var e = new Dictionary<string, object>();
                    e["slot"] = s; e["online"] = isOnline(cid);
                    e["exists"] = k != null && Str(k, "heroName").Length > 0;
                    if (k != null)
                        foreach (var f in new[] { "heroName", "culture", "cultureName", "level", "clan", "kingdom", "gold", "tier", "lastSeen" })
                        { object v; if (k.TryGetValue(f, out v) && v != null) e[f] = v; }
                    list.Add(e);
                }
            r["slots"] = list;
            return r;
        }
        static string Str(Dictionary<string, object> d, string k) { object v; return d != null && d.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : ""; }

        // ================================================================ player (client)
        static object provider;          // Coop's ControllerIdProvider (the id this game joins with)
        static string platformId;        // the Steam id as Coop read it
        static int chosen;               // 0 = not chosen yet, 1 / 2 = the slot for the next Join
        static bool joining;             // ActionConnect called by us after the choice
        static object connectVm;
        static object autoMod;           // Coop's mod when the launcher asked for an automatic join
        static bool autoAllow, autoAsked;
        public static string LastHost = "";
        public static int Chosen { get { return chosen; } }

        public static void InstallClient(Harmony h)
        {
            try
            {
                var pt = AccessTools.TypeByName("GameInterface.Services.Entity.ControllerIdProvider");
                var pm = pt == null ? null : AccessTools.Method(pt, "SetControllerAsPlatformId");
                var vt = AccessTools.TypeByName("GameInterface.Services.UI.CoopConnectMenuVM");
                var vm = vt == null ? null : AccessTools.Method(vt, "ActionConnect");
                if (pm == null || vm == null) { Log.W("Slots: Coop join not found, players join with one character"); return; }
                h.Patch(pm, postfix: new HarmonyMethod(typeof(Slots), "PlatformIdPostfix"));
                h.Patch(vm, prefix: new HarmonyMethod(typeof(Slots), "ConnectPrefix"));
                // "Play" in the launcher starts the game with /autoconnect: Coop joins by itself from the main menu,
                // so the choice is shown there first and Coop's own join waits for it
                var cm = AccessTools.TypeByName("Coop.CoopMod");
                var am = cm == null ? null : AccessTools.Method(cm, "TryAutoConnect");
                if (am != null) h.Patch(am, prefix: new HarmonyMethod(typeof(Slots), "AutoPrefix"));
                else Log.W("Slots: launcher auto-join not found, the choice shows only on the Join button");
                Log.W("Slots: character choice ready");
            }
            catch (Exception e) { Log.W("Slots: client hook failed: " + (e.InnerException ?? e).Message); }
        }

        public static void PlatformIdPostfix(object __instance)
        {
            try
            {
                provider = __instance;
                var id = Convert.ToString(Traverse.Create(__instance).Property("ControllerId").GetValue());
                platformId = ShortId(id);
                Apply();
            }
            catch (Exception e) { Log.W("Slots: id read failed: " + e.Message); }
        }

        static void Apply()
        {
            if (provider == null || string.IsNullOrEmpty(platformId)) return;
            var id = chosen == 2 ? platformId + Suffix2 : platformId;
            var m = AccessTools.Method(provider.GetType(), "SetControllerId", new[] { typeof(string) });
            if (m != null) m.Invoke(provider, new object[] { id });
            else Traverse.Create(provider).Property("ControllerId").SetValue(id);
        }

        // Join pressed: first the character choice, then the real join with that slot
        public static bool ConnectPrefix(object __instance)
        {
            if (joining) return true;
            try
            {
                // Coop reads the Steam id again when the join starts (ValidateModuleState -> SetControllerAsPlatformId, patched above),
                // so here it is read from the same place only to ask the server what the two slots hold
                if (string.IsNullOrEmpty(platformId)) platformId = ShortId(SteamId());
                if (string.IsNullOrEmpty(platformId) || Slots.Max < 2) return true;   // no Steam id: plain join
                connectVm = __instance;
                var ip = Convert.ToString(Traverse.Create(__instance).Field("connectIP").GetValue()) ?? "";
                SlotsScreen.Open(platformId, HostOf(ip));
                return false;
            }
            catch (Exception e) { Log.W("Slots: choice screen failed, joining with the first character: " + e.Message); return true; }
        }

        static string SteamId()
        {
            try
            {
                var t = AccessTools.TypeByName("TaleWorlds.PlatformService.PlatformServices");
                var p = t == null ? null : t.GetProperty("UserId", BindingFlags.Public | BindingFlags.Static);
                return p == null ? null : Convert.ToString(p.GetValue(null, null));
            }
            catch { return null; }
        }

        static string HostOf(string address)
        {
            var a = (address ?? "").Trim();
            if (a.StartsWith("[")) { var e = a.IndexOf(']'); return e > 0 ? a.Substring(1, e - 1) : a; }
            var c = a.LastIndexOf(':');
            return c > 0 && a.IndexOf(':') == c ? a.Substring(0, c) : a;
        }

        public static bool AutoPrefix(object __instance)
        {
            try
            {
                if (autoAllow) return true;
                var tr = Traverse.Create(__instance);
                if (!tr.Field("isAutoConnect").GetValue<bool>() || tr.Field("_autoStarted").GetValue<bool>() || tr.Field("isServer").GetValue<bool>()) return true;
                var gsm = TaleWorlds.Core.GameStateManager.Current;
                if (gsm == null || !(gsm.ActiveState is TaleWorlds.MountAndBlade.InitialState)) return true;
                if (autoAsked) return false;   // the choice is on screen: Coop waits
                if (string.IsNullOrEmpty(platformId)) platformId = ShortId(SteamId());
                if (string.IsNullOrEmpty(platformId)) return true;
                var host = Convert.ToString(tr.Field("autoConnectConfiguration").Property("Address").GetValue());
                autoAsked = true; autoMod = __instance; connectVm = null;
                SlotsScreen.Open(platformId, HostOf(host));
                return false;
            }
            catch (Exception e) { Log.W("Slots: launcher join choice failed, joining with the first character: " + e.Message); return true; }
        }

        // ---- the game's main menu must not flash on the way in from the launcher's Play:
        // from the first frame of the main menu until the world loads, its buttons stay hidden (the choice / our loading cover the screen).
        // Shown again only when the player backs out of the choice, or a join fails and he is left on the menu.
        static int autoLaunch = -1; static bool menuReleased; static bool wasJoining; static DateTime menuSeen = DateTime.MinValue;
        static readonly List<TaleWorlds.Engine.GauntletUI.GauntletLayer> hiddenMenu = new List<TaleWorlds.Engine.GauntletUI.GauntletLayer>();
        public static bool AutoLaunch
        {
            get
            {
                if (autoLaunch < 0)
                {
                    autoLaunch = 0;
                    try { foreach (var a in Environment.GetCommandLineArgs()) if (string.Equals((a ?? "").Trim(), "/autoconnect", StringComparison.OrdinalIgnoreCase)) autoLaunch = 1; } catch { }
                }
                return autoLaunch == 1;
            }
        }
        // from the launcher's Play until the player is free on the main menu: our cover / loading screen stand in for the game's
        // the choice's hall was already on screen while the game finished loading: the choice opens without its entrance
        public static bool BootWaitShown;
        public static bool LaunchCover { get { return AutoLaunch && !menuReleased; } }
        public static void MenuGuard()
        {
            try
            {
                var top = ScreenManager.TopScreen;
                bool onMenu = top != null && top.GetType().Name == "GauntletInitialScreen" && TaleWorlds.CampaignSystem.Campaign.Current == null;
                if (wasJoining && !Joining && onMenu && !SlotsScreen.IsOpen) menuReleased = true;   // the join ended on the menu: let him use it
                wasJoining = Joining;
                if (onMenu && AutoLaunch && !menuReleased && !SlotsScreen.IsOpen && !Joining)
                {   // launcher start but nothing asked for the choice yet (Coop joins on its own): give it a moment, then show the menu
                    if (menuSeen == DateTime.MinValue) menuSeen = DateTime.UtcNow;
                    else if ((DateTime.UtcNow - menuSeen).TotalSeconds > 20) menuReleased = true;
                }
                else menuSeen = DateTime.MinValue;
                bool hide = onMenu && ((AutoLaunch && !menuReleased) || SlotsScreen.IsOpen || Joining);
                if (hide)
                {
                    foreach (var l in top.Layers)
                    {
                        var g = l as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                        if (g == null || g.UIContext == null || g.UIContext.Root == null || !g.UIContext.Root.IsVisible) continue;
                        g.UIContext.Root.IsVisible = false; hiddenMenu.Add(g);
                    }
                }
                else if (hiddenMenu.Count > 0)
                {
                    foreach (var g in hiddenMenu) { try { if (g.UIContext != null && g.UIContext.Root != null) g.UIContext.Root.IsVisible = true; } catch { } }
                    hiddenMenu.Clear();
                }
            }
            catch (Exception e) { if (++guardErrors <= 2) Log.W("Slots: menu guard: " + e.Message); }
        }
        static int guardErrors;

        // the player closed the choice without picking: a launcher join is cancelled (he stays in the main menu)
        public static void Cancelled()
        {
            menuReleased = true;
            if (autoMod != null && !autoAllow)
            {
                try { Traverse.Create(autoMod).Field("_autoStarted").SetValue(true); } catch { }
                autoMod = null;
            }
        }

        // true from the moment a character is chosen until the player is back on the game's main menu: the loading screen
        // between them is ours; the one right after the TaleWorlds logo stays the game's
        public static bool Joining;
        public static bool ChooserOpen { get { return SlotsScreen.IsOpen; } }
        public static void Join(int slot)
        {
            Joining = true;
            try { UiLoading.ResetProgress(); } catch { }
            chosen = slot == 2 ? 2 : 1;
            Apply();
            Log.W("Slots: joining with character " + chosen);
            if (autoMod != null && connectVm == null) { autoAllow = true; autoMod = null; return; }   // Coop's own launcher join goes on next frame
            var vm = connectVm; if (vm == null) return;
            joining = true;
            try { var m = AccessTools.Method(vm.GetType(), "ActionConnect"); if (m != null) m.Invoke(vm, null); }
            catch (Exception e) { Log.W("Slots: join failed: " + (e.InnerException ?? e).Message); }
            finally { joining = false; }
        }
    }

    // ================================================================ the choice screen
    public class SlotsScreen : GlobalLayer
    {
        static SlotsScreen open;
        public static bool IsOpen { get { return open != null; } }
        readonly SlotsVM vm; GauntletLayer layer; object movie;
        SlotsScreen(SlotsVM vm) { this.vm = vm; }

        public static void Open(string steam64, string host)
        {
            if (open != null) return;
            AurelionSkin.EnsureSprite("aur_cult", "aur_cult_1.png");
            AurelionSkin.EnsureSprite("aur_cult_art", "aur_cult_art_1.png");
            AurelionSkin.EnsureSprite("aur_skin2", "aur_skin2_1.png");
            AurelionSkin.EnsureSprite("aur_bg_hall_dim", "aur_bg_hall_dim_1.png");
            AurelionSkin.EnsureSprite("aur_slot", "aur_slot_1.png");
            AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png");
            AurelionSkin.EnsureSprite("aur_cult5", "aur_cult5_1.png");
            for (int k = 1; k <= 2; k++) if (HeroCard.HasPicture(k)) HeroCard.PicReady[k] = AurelionSkin.EnsureSprite("aur_hero" + k, HeroCard.PicPath(k));
            var vm = new SlotsVM();
            var s = new SlotsScreen(vm);
            s.layer = new GauntletLayer("AurelionSlots", 4000, false);
            s.movie = s.layer.LoadMovie(UiMotion.Movie("AurSlots"), vm);
            s.layer.InputRestrictions.SetInputRestrictions(true);
            s.Layer = s.layer;
            ScreenManager.AddGlobalLayer(s, true);
            s.layer.IsFocusLayer = true; ScreenManager.TrySetFocus(s.layer);
            open = s;
            Slots.LastHost = host ?? "";
            vm.Load(steam64, host);
        }

        DateTime leavingAt = DateTime.MinValue;
        public static void Tick()
        {
            Slots.MenuGuard();
            if (open == null) return;
            try
            {
                open.vm.Tick();
                if (open.leavingAt != DateTime.MinValue)
                {   // the join is on its way: this screen stays until the loading screen (or the world) is up, so the menu never shows between them
                    bool loading = false; try { loading = TaleWorlds.Engine.LoadingWindow.IsLoadingWindowActive; } catch { }
                    if (loading || TaleWorlds.CampaignSystem.Campaign.Current != null || (DateTime.UtcNow - open.leavingAt).TotalSeconds > 12) Close();
                    return;
                }
                if (open.vm.Done != 0)
                {
                    var d = open.vm.Done;
                    if (d > 0) { open.leavingAt = DateTime.UtcNow; open.vm.Entering = true; Slots.Join(d); }
                    else { Close(); Slots.Cancelled(); }
                }
                else if (TaleWorlds.InputSystem.Input.IsKeyReleased(TaleWorlds.InputSystem.InputKey.Escape)) { Close(); Slots.Cancelled(); }
            }
            catch (Exception e) { Log.W("Slots screen: " + e.Message + " (joining with the first character)"); Close(); Slots.Join(1); }   // never leave a launcher join waiting
        }

        static void Close()
        {
            var s = open; open = null; if (s == null || s.layer == null) return;
            try { s.layer.InputRestrictions.ResetInputRestrictions(); } catch { }
            try { s.layer.IsFocusLayer = false; ScreenManager.TryLoseFocus(s.layer); } catch { }
            try { if (s.movie != null) s.layer.ReleaseMovie((GauntletMovieIdentifier)s.movie); } catch { }
            try { AurLayers.Remove(s); } catch (Exception e) { Log.W("Slots screen close: " + e.Message); }
            try { s.vm.OnFinalize(); } catch { }
        }
    }

    // one ember of the screen's slow rising sparks
    public class EmberVM : ViewModel
    {
        float x, y, a, sz;
        public float BaseX, Speed, Drift, Phase, MaxA;
        [DataSourceProperty] public float X { get { return x; } set { if (value != x) { x = value; OnPropertyChangedWithValue(value, "X"); } } }
        [DataSourceProperty] public float Y { get { return y; } set { if (value != y) { y = value; OnPropertyChangedWithValue(value, "Y"); } } }
        [DataSourceProperty] public float A { get { return a; } set { if (value != a) { a = value; OnPropertyChangedWithValue(value, "A"); } } }
        [DataSourceProperty] public float S { get { return sz; } set { if (value != sz) { sz = value; OnPropertyChangedWithValue(value, "S"); } } }
    }

    public class PipVM : ViewModel
    {
        bool on; public PipVM(bool v) { on = v; }
        [DataSourceProperty] public bool On { get { return on; } set { if (value != on) { on = value; OnPropertyChangedWithValue(value, "On"); } } }
        [DataSourceProperty] public bool Off { get { return !on; } }
    }
    // one of the hero's best skills, drawn like the game's own skill card (icon strip offset picks the icon)
    public class SkillTileVM : ViewModel
    {
        public string Name { get; set; }
        [DataSourceProperty] public string SkillName { get { return Name; } }
        [DataSourceProperty] public string Value { get; set; }
        [DataSourceProperty] public float IconX { get; set; }
        [DataSourceProperty] public float IconX52 { get { return IconX / 44f * 52f; } }
        [DataSourceProperty] public bool F1 { get; set; }
        [DataSourceProperty] public bool F2 { get; set; }
        [DataSourceProperty] public bool F3 { get; set; }
        [DataSourceProperty] public bool F4 { get; set; }
        [DataSourceProperty] public bool F5 { get; set; }
        [DataSourceProperty] public bool N1 { get { return !F1; } }
        [DataSourceProperty] public bool N2 { get { return !F2; } }
        [DataSourceProperty] public bool N3 { get { return !F3; } }
        [DataSourceProperty] public bool N4 { get { return !F4; } }
        [DataSourceProperty] public bool N5 { get { return !F5; } }
    }

    public class SlotCardVM : ViewModel
    {
        string name = "", line = "", kingdom = "", rank = "", gold = "", seen = "", art = "", empty = "", emptySub = "", action = "", kingdomL = "", rankL = "", goldL = "", seenL = "", badge = "", status = "", numeral = "", busyText = "";
        string troops = "", renown = "", place = "", troopsL = "", renownL = "", placeL = "", tierText = "", stageNote = "", skillsTitle = "", noSkills = "", smallAction = "";
        bool filled, isEmpty, canEnter = true, busy, knownArt, unknownArt, big, pic1, pic2, hasSkills, ar;
        float alpha, y = 46, shineX = -400, flash, blink = 1, picW = 680, picH = 740, w = 390;
        public int Slot, Index;
        public Action<SlotCardVM> OnPick, OnSelect;
        public SlotCardVM(int slot) { Slot = slot; ar = UiText.Arabic; }
        public void ExecutePick() { if (canEnter && OnPick != null) OnPick(this); }
        // the small card: an empty slot starts a new lineage, a filled one comes to the front
        public void ExecuteCard() { if (isEmpty) ExecutePick(); else if (OnSelect != null) OnSelect(this); }
        void S(ref string f, string v, string n) { v = v ?? ""; if (v != f) { f = v; OnPropertyChangedWithValue(v, n); } }
