            var list = new MBBindingList<EmberVM>();
            for (int i = 0; i < EmbL.Length; i++) { var e = new EmberVM(); e.S = 24f * EmbS[i] / 5f; e.A = 0; list.Add(e); }
            Embers = list;
            Get("http://" + host + ":4201/slots?steam64=" + Uri.EscapeDataString(steam64), r => { reply = r; replied = true; });
            Get("http://" + host + ":4201/status", r =>
            {
