        static void Get(string url, Action<string> done)
        {
            var th = new Thread(() =>
            {
                string r = null;
                try
                {
                    var req = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(url);
                    req.Timeout = 4000; req.ReadWriteTimeout = 4000;
                    using (var resp = req.GetResponse())
                    using (var sr = new System.IO.StreamReader(resp.GetResponseStream(), System.Text.Encoding.UTF8)) r = sr.ReadToEnd();
                }
                catch { r = null; }
                try { done(r); } catch { }
            });
            th.IsBackground = true; th.Start();
        }

        void Respawn(EmberVM e, bool anywhere)
        {
            e.BaseX = (float)(rnd.NextDouble() * 2000 - 40);
            e.Y = anywhere ? (float)(rnd.NextDouble() * 1100) : 1100 + (float)(rnd.NextDouble() * 120);
            e.Speed = 14 + (float)(rnd.NextDouble() * 30);
            e.Drift = 8 + (float)(rnd.NextDouble() * 26);
            e.Phase = (float)(rnd.NextDouble() * 6.28);
            e.MaxA = 0.18f + (float)(rnd.NextDouble() * 0.42);
            e.S = 5 + (float)(rnd.NextDouble() * 11);
        }

        static readonly float[] EmbL = { 863, 348, 1239, 343, 1358, 1381, 295, 495, 411, 399 }, EmbS = { 3, 3, 6, 3, 3, 4, 6, 4, 5, 3 };
        static readonly float[] EmbD = { 14.6f, 13.6f, 8.7f, 8.9f, 8.0f, 11.7f, 11.5f, 11.3f, 11.7f, 11.4f }, EmbW = { 5.9f, 1.4f, 1.3f, 8.3f, 3.3f, 0.7f, 2.0f, 8.6f, 9.6f, 0.9f };
        static float Ease(double v) { var p = Clamp01(v); return 1 - (float)Math.Pow(1 - p, 3.2); }   // cubic-bezier(.2,.8,.2,1)
        static float InOut(double x) { return (float)(x < 0.5 ? 2 * x * x : 1 - Math.Pow(-2 * x + 2, 2) / 2); }
        static float Clamp01(double v) { return (float)(v < 0 ? 0 : v > 1 ? 1 : v); }
        static float EaseOut(double v) { var p = Clamp01(v); return 1 - (1 - p) * (1 - p) * (1 - p); }

        public void Tick()
        {
            var t = clock.Elapsed.TotalSeconds; var dt = Math.Min(0.1, Math.Max(0, t - last)); last = t;

            // the board: Ken Burns on the hall (60 s each way), the seal spins in, the title and its line rise
            var th = t + head0;   // the header, already in place when the hall was shown at start-up
            var tw = (double)UiMotion.Now;   // one clock with the start-up hall: the background and the embers carry on
            HeadA = EaseOut(th / 0.7); HeadY = -16 * (1 - HeadA);
            // the hall stands still: resizing a full-screen picture every frame re-lays the whole screen and made the cards stutter
            if (BgW != 1960f * 1.04f) { BgW = 1960f * 1.04f; BgH = 1120f * 1.04f; BgX = 0; BgY = 0; }
            { var k = Ease(th / 1.4); SealA = k; SealS = 70f * (0.6f + 0.4f * k); }
            { var k = Ease((th - 0.22) / 0.7); TitleA = k; TitleY = 22 * (1 - k); }
            { var k = Ease((th - 0.29) / 0.7); SubA = k; SubY = 22 * (1 - k); }
            Pulse = (float)(0.34 + 0.22 * Math.Sin(t * 1.6));
            SpotA = (float)(0.82 + 0.18 * Math.Sin(t * 0.7));
            Blink = (float)(0.6 + 0.4 * Math.Sin(t * 3.4));
            for (int i = 0; i < embers.Count && i < EmbL.Length; i++)
            {   // rise 760 px drifting 40 px right, fade in over the first 12 %
                var e = embers[i]; var p = (float)(((tw + EmbW[i]) % EmbD[i]) / EmbD[i]); var sz = EmbS[i];
                e.X = EmbL[i] + sz / 2f - e.S / 2f + 40f * p; e.Y = 1060f + sz / 2f - e.S / 2f - 760f * p;
                e.A = p < 0.12f ? 0.9f * p / 0.12f : 0.9f * (1 - (p - 0.12f) / 0.88f);
            }
            var l = live; if (l != null) { LiveText = l; HasLive = true; }

            if (IsLoading) LoadingText = loadingBase + new string('.', 1 + (int)(t * 2.2) % 3);
            CometX = (float)(Math.Cos(t * 2.4) * 58); CometY = (float)(Math.Sin(t * 2.4) * 58);
            if (Entering)
            {
                if (enterAt < 0) { enterAt = t; EnterText = UiText.L("Entering the realm", "داخلين العالم"); }
                EnterA = EaseOut((t - enterAt) / 0.5);
            }
            if (replied)
            {
                replied = false; IsLoading = false;
                Dictionary<string, object> d = null;
                try { d = reply == null ? null : Mj.Parse(reply) as Dictionary<string, object>; } catch { d = null; }
                Build(d); cardsAt = t;
            }
            if (switchTo != null)
            {
                var k = EaseOut((t - switchAt) / 0.16);
                foreach (var c in cards) { c.Alpha = Math.Min(c.Alpha, 1 - k); c.Y = -6 * k; }
                if (t - switchAt >= 0.16)
                {
                    var to = switchTo; switchTo = null;
                    foreach (var x in cards) { x.IsBig = ReferenceEquals(x, to); x.W = x.IsBig ? 1140 : 390; x.Alpha = 0; }
                    cardsAt = t;   // the big card comes in at once, the small one 0.14 s later
                }
            }
            else if (cardsAt >= 0)
                foreach (var c in cards)
                {
                    var start = c.IsBig ? Math.Max(cardsAt, 0.36) : Math.Max(cardsAt + 0.14, 0.50);
                    var p = Ease((t - start) / 0.7);
                    c.Alpha = p; c.Y = 22 * (1 - p);
                    var ph = ((t + c.Index * 1.9) % 9.0) / (9.0 * 0.55);   // the light crosses the stage every 9 s
                    c.ShineX = ph <= 1 ? (float)(-300 + ph * (c.IsBig ? 1240 : 780)) : -400;
                    c.Blink = Blink;
                    var q = Math.Cos(t * Math.PI / 2.0);   // the + breathes every 4 s
                    c.PlusA = (float)(0.775 - 0.225 * q); c.PlusS = (float)(88 * (1.02 - 0.02 * q));
                }
            if (picked != null)
            {
                var k = t - pickAt;
                picked.Flash = (float)(0.55 * Math.Max(0, 1 - k / 0.42));
                if (k >= 0.4 && Done == 0) Done = picked.Slot;
            }
        }

        void Select(SlotCardVM c)
        {
            if (picked != null || Done != 0 || c == null || c.IsBig) return;
            if (switchTo != null) return;
            switchTo = c; switchAt = clock.Elapsed.TotalSeconds;   // Tick fades both out, swaps them, and brings them back
        }

        void Pick(SlotCardVM c)
        {
            if (picked != null || Done != 0) return;
            picked = c; pickAt = clock.Elapsed.TotalSeconds; c.Flash = 0.55f;
        }

        static readonly Dictionary<string, string[]> CultureNames = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
        {
            { "empire", new[] { "Empire", "الإمبراطورية" } }, { "vlandia", new[] { "Vlandia", "فلانديا" } }, { "sturgia", new[] { "Sturgia", "ستورجيا" } },
            { "battania", new[] { "Battania", "باتانيا" } }, { "khuzait", new[] { "Khuzait", "الخوزايت" } }, { "aserai", new[] { "Aserai", "الأسيراي" } },
        };

        void Build(Dictionary<string, object> d)
        {
            int max = 2; object mo;
            if (d != null && d.TryGetValue("max", out mo)) { try { max = Convert.ToInt32(mo, CultureInfo.InvariantCulture); } catch { } }
            var info = new Dictionary<int, Dictionary<string, object>>();
            object so;
            if (d != null && d.TryGetValue("slots", out so) && so is IEnumerable)
                foreach (var o in (IEnumerable)so)
                {
                    var e = o as Dictionary<string, object>; if (e == null) continue;
                    int s = 1; try { s = Convert.ToInt32(e["slot"], CultureInfo.InvariantCulture); } catch { }
                    info[s] = e;
                }
            bool known = d != null;
            if (max < 2 || !known) max = 1;   // no answer: only the character the player always had (the server could not confirm the other slot is free)
            var made = new List<SlotCardVM>();
            for (int s = 1; s <= max; s++)
            {
                var c = new SlotCardVM(s); c.OnPick = Pick; c.OnSelect = Select;
                Dictionary<string, object> e; info.TryGetValue(s, out e);
                bool exists = e != null && Mj.B(e, "exists", false);
                bool online = e != null && Mj.B(e, "online", false);
                if (!known && s == 1) exists = true;   // without an answer the first character is still offered
                c.IsFilled = exists; c.IsEmpty = !exists;
                c.KingdomL = UiText.L("KINGDOM", "المملكة"); c.RankL = UiText.L("CLAN TIER", "رتبة العشيرة");
                c.GoldL = UiText.L("DENARS", "الدينارات"); c.SeenL = UiText.L("LAST PLAYED", "آخر دخول");
                c.Badge = s == 1 ? UiText.L("FIRST LINEAGE", "النسب الأول") : UiText.L("SECOND LINEAGE", "النسب التاني");
                c.Numeral = s == 1 ? "I" : "II";
                if (exists)
                {
                    c.Name = e == null ? UiText.L("Your character", "شخصيتك") : Mj.S(e, "heroName", UiText.L("Your character", "شخصيتك"));
                    var cid = e == null ? "" : Mj.S(e, "culture", "");
                    string[] cn; var cul = CultureNames.TryGetValue(cid, out cn) ? UiText.L(cn[0], cn[1]) : (e == null ? "" : Mj.S(e, "cultureName", ""));
                    var clan = e == null ? "" : Mj.S(e, "clan", "");
                    var kn = e == null ? "" : Mj.S(e, "kingdom", "");
                    var clanPart = clan.Length > 0 ? UiText.L("Clan " + clan, "عشيرة " + clan) : cul;
                    c.Line = clanPart + "  ·  " + (kn.Length > 0 ? kn : UiText.L("no kingdom", "من غير مملكة"));
                    c.Away = e == null ? "" : Mj.S(e, "away", "");
                    bool knownCulture = CultureNames.ContainsKey(cid);
                    c.CultureId = knownCulture ? cid.ToLowerInvariant() : "default";   // the seal shows the Aurelion medallion for a modded people
                    c.KnownArt = knownCulture; c.UnknownArt = !knownCulture;
                    var k = e == null ? "" : Mj.S(e, "kingdom", "");
                    c.Kingdom = k.Length > 0 ? k : UiText.L("None", "من غير مملكة");
                    var tier = e == null ? "" : Mj.S(e, "tier", "");
                    c.Rank = tier.Length > 0 ? tier : "—";
                    double g = 0; try { g = e == null ? 0 : Convert.ToDouble(e.ContainsKey("gold") ? e["gold"] : 0, CultureInfo.InvariantCulture); } catch { }
                    c.Gold = e == null || !e.ContainsKey("gold") ? "—" : g.ToString("N0", CultureInfo.InvariantCulture);
                    c.Seen = e == null ? "—" : Ago(Mj.S(e, "lastSeen", ""));
                    c.ActionText = UiText.L("Enter the realm", "ادخل العالم");
                    c.SmallAction = UiText.L("Show this character", "اعرض الشخصية دي");
                    Fill(c, s, e);
                }
                else
                {
                    c.EmptyTitle = UiText.L("Begin a new lineage", "ابدأ نسب جديد");
                    c.EmptySub = UiText.L("Choose a people, shape your hero and ride out.\nYour first lineage stays untouched.", "اختار شعب، شكّل بطلك واطلع.\nنسبك الأول مش هيتلمس.");
                    c.ActionText = UiText.L("Create a character", "اعمل شخصية");
                    c.SmallAction = c.ActionText;
                }
                if (online) { c.CanEnter = false; c.IsBusy = true; c.BusyText = UiText.L("ONLINE NOW", "أونلاين دلوقتي"); c.Status = UiText.L("This character is in the world right now", "الشخصية دي جوه العالم دلوقتي"); }
                made.Add(c);
            }
            // a character can not join while the other one is online (the server refuses it too)
            bool anyOnline = made.Any(x => x.IsBusy);
            if (anyOnline) foreach (var c in made) if (!c.IsBusy) { c.CanEnter = false; c.Status = UiText.L("Your other character is online", "شخصيتك التانية أونلاين"); }
            if (!known) FootPlain = true;
            if (!known) Foot = UiText.L("The server did not answer: only your first character is shown", "السيرفر مردّش: ظاهرة شخصيتك الأولى بس");
            // reading order: the first lineage comes first (on the right in Arabic)
            // the big card: the first filled slot (the player can bring the other one forward)
            SlotCardVM front = made.FirstOrDefault(x => x.IsFilled);
            foreach (var x in made) { x.IsBig = ReferenceEquals(x, front); x.W = x.IsBig ? 1140 : 390; }
            if (UiText.Arabic) made.Reverse();
            var list = new MBBindingList<SlotCardVM>();
            for (int i = 0; i < made.Count; i++) { made[i].Index = UiText.Arabic ? made.Count - 1 - i : i; list.Add(made[i]); }
            Cards = list;
        }

        static readonly string[][] SkillNames = {
            new[] { "One Handed", "يد واحدة" }, new[] { "Two Handed", "يدين" }, new[] { "Polearm", "رماح" }, new[] { "Bow", "قوس" }, new[] { "Crossbow", "نشّاب" }, new[] { "Throwing", "رمي" },
            new[] { "Riding", "ركوب" }, new[] { "Athletics", "رياضة" }, new[] { "Smithing", "حدادة" }, new[] { "Scouting", "استطلاع" }, new[] { "Tactics", "تكتيك" }, new[] { "Roguery", "شقاوة" },
            new[] { "Charm", "جاذبية" }, new[] { "Leadership", "قيادة" }, new[] { "Trade", "تجارة" }, new[] { "Steward", "إدارة" }, new[] { "Medicine", "طب" }, new[] { "Engineering", "هندسة" } };
        static double Num(Dictionary<string, object> d, string k, double def)
        {
            object v; if (d == null || !d.TryGetValue(k, out v) || v == null) return def;
            try { return Convert.ToDouble(v, CultureInfo.InvariantCulture); } catch { return def; }
        }
        static string Txt(Dictionary<string, object> d, string k) { object v; return d != null && d.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : ""; }

        // the hero card this computer kept from the last time in the world (picture, army, best skills) + what the server knows
        static void Fill(SlotCardVM c, int slot, Dictionary<string, object> e)
        {
            var me = HeroCard.Read(slot);
            bool pic = HeroCard.PicReady[slot == 2 ? 2 : 1];
            if (pic)
            {
                int pw, ph; HeroCard.PicSize(slot, out pw, out ph);
                if (pw > 0 && ph > 0) { c.PicH = 740; c.PicW = (float)Math.Round(pw * 740.0 / ph); }
                if (slot == 2) c.Pic2 = true; else c.Pic1 = true;
            }
            c.StageNote = pic ? UiText.L("Your real hero, his gear and his horse", "بطلك الحقيقي بعدّته وحصانه")
                              : UiText.L("Open your inventory once in the world and your hero shows here", "افتح الشنطة مرة جوه العالم وبطلك هيظهر هنا");
            int tier = (int)Num(e, "tier", Num(me, "tier", 0));
            c.TierText = UiText.L("CLAN TIER", "رتبة العشيرة");
            for (int i = 0; i < 6; i++) c.pips.Add(new PipVM(i < tier));
            int lv = (int)Num(me, "level", Num(e, "level", 0)), age = (int)Num(me, "age", 0);
            c.TierNum = tier.ToString(CultureInfo.InvariantCulture);
            c.LvL = UiText.L("LEVEL", "المستوى"); c.AgeL = UiText.L("AGE", "السن");
            c.Lv = lv > 0 ? lv.ToString(CultureInfo.InvariantCulture) : ""; c.AgeV = age > 0 ? age.ToString(CultureInfo.InvariantCulture) : "";
            c.Rank = lv > 0 ? (age > 0 ? UiText.L("Level " + lv + "  ·  Age " + age, "المستوى " + lv + "  ·  السن " + age) : UiText.L("Level " + lv, "المستوى " + lv)) : "";
            double gold = Num(e, "gold", Num(me, "gold", -1));
            c.Gold = gold < 0 ? "—" : gold.ToString("N0", CultureInfo.InvariantCulture);
            int tr = (int)Num(me, "troops", -1), tl = (int)Num(me, "troopLimit", -1);
            c.Troops = tr < 0 ? "—" : tl > 0 ? UiText.L(tr + " / " + tl, tr + " من " + tl) : tr.ToString(CultureInfo.InvariantCulture);
            double rn = Num(me, "renown", -1);
            c.Renown = rn < 0 ? "—" : rn.ToString("N0", CultureInfo.InvariantCulture);
            var place = Txt(me, "place");
            c.Place = place.Length == 0 ? "—" : (Num(me, "inPlace", 0) > 0 ? UiText.L("In ", "في ") : UiText.L("Near ", "جنب ")) + place;
            c.TroopsL = UiText.L("ARMY", "الجيش"); c.RenownL = UiText.L("RENOWN", "الشهرة"); c.PlaceL = UiText.L("LAST PLACE", "آخر مكان");
            c.SkillsTitle = UiText.L("BEST SKILLS", "أعلى مهاراته");
            object so;
            if (me != null && me.TryGetValue("skills", out so) && so is IEnumerable)
                foreach (var o in (IEnumerable)so)
                {
                    var k = o as Dictionary<string, object>; if (k == null) continue;
                    int i = (int)Num(k, "i", -1); if (i < 0 || i >= SkillNames.Length) continue;
                    int f = (int)Num(k, "f", 0);
                    c.skills.Add(new SkillTileVM { Name = UiText.L(SkillNames[i][0], SkillNames[i][1]), Value = ((int)Num(k, "v", 0)).ToString(CultureInfo.InvariantCulture), IconX = -44 * i, F1 = f >= 1, F2 = f >= 2, F3 = f >= 3, F4 = f >= 4, F5 = f >= 5 });
                }
            c.HasSkills = c.skills.Count > 0;
            c.NoSkillsText = UiText.L("Your best skills show here after your next time in the world", "أعلى مهاراتك هتظهر هنا بعد ما تدخل العالم المرة الجاية");
        }

        static string Ago(string iso)
        {
            DateTime t;
            if (!DateTime.TryParse(iso, CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out t)) return "—";
            var span = DateTime.Now - t;
            if (span.TotalMinutes < 1) return UiText.L("just now", "دلوقتي");
            if (span.TotalMinutes < 60) { var m = (int)span.TotalMinutes; return UiText.L(m + " min ago", Ar(m, "دقيقة", "دقيقتين", "دقايق", "دقيقة")); }
            if (span.TotalHours < 24) { var h = (int)span.TotalHours; return UiText.L(h + (h == 1 ? " hour ago" : " hours ago"), Ar(h, "ساعة", "ساعتين", "ساعات", "ساعة")); }
            var d = (int)span.TotalDays; return UiText.L(d + (d == 1 ? " day ago" : " days ago"), Ar(d, "يوم", "يومين", "أيام", "يوم"));
        }
        // Egyptian Arabic counting: 1 -> "من ساعة", 2 -> "من ساعتين", 3..10 -> "من 3 ساعات", 11+ -> "من 11 ساعة"
        static string Ar(int n, string one, string two, string few, string many)
        {
            if (n <= 1) return "من " + one;
            if (n == 2) return "من " + two;
            return "من " + n + " " + (n <= 10 ? few : many);
        }
    }
}

