// =====================================================================================
//  system/UiCulture.cs — شاشة اختيار الثقافة «قاعة الرايات» + شاشة التحميل بتصميم أوريليون
//  الشاشتين ملفاتهم في GUI\AurelionScreens (CharacterCreationCultureStage.xml و LoadingWindow.xml) وبيتسجّلوا مع باقي شاشاتنا (UiScreens).
//  الكود هنا بيكتب النصوص اللي اللعبة مش بتديها للشاشة (وحدات النخبة، التلميحات، قانون المملكة) بالعربي أو الإنجليزي حسب لغة اللاعب،
//  وبيعيد تحميل شاشة التحميل مرة واحدة (اللعبة بتحمّلها قبل ما مودنا يشتغل)، من غير ما نلمس نصوص Coop ولا الـViewModel بتاعها.
// =====================================================================================
using System;
using System.Collections.Generic;
using HarmonyLib;
using TaleWorlds.Engine.GauntletUI;
using TaleWorlds.GauntletUI;
using TaleWorlds.GauntletUI.BaseTypes;
using TaleWorlds.Library;
using TaleWorlds.ScreenSystem;

namespace Aurelion.Core
{
    static class UiText
    {
        public static bool Arabic
        {
            get
            {
                try { var l = TaleWorlds.Localization.MBTextManager.ActiveTextLanguage ?? ""; return l.IndexOf("arab", StringComparison.OrdinalIgnoreCase) >= 0 || l.IndexOf("عرب", StringComparison.Ordinal) >= 0; }
                catch { return false; }
            }
        }
        public static string L(string en, string ar) { return Arabic ? ar : en; }
        public static void Walk(Widget w, Action<Widget> f)
        {
            if (w == null) return;
            f(w);
            for (int i = 0; i < w.ChildCount; i++) Walk(w.GetChild(i), f);
        }
        public static void Set(Widget w, string text)
        {
            var tw = w as TextWidget;
            if (tw != null && tw.Text != text) tw.Text = text ?? "";
        }
    }

    // ------------------------------------------------------------------ culture select
    public static class UiCulture
    {
        // the design's elite line under each banner (the game has no such text): English, Arabic
        static readonly Dictionary<string, string[]> Elite = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            { "empire",   new[] { "Legionary · Cataphract", "الفيلق · الكاتافراكت" } },
            { "vlandia",  new[] { "Banner Knight",          "فارس الراية" } },
            { "sturgia",  new[] { "Ulfhednar · Druzhnik",   "الأولفهيدنار · الدروجينيك" } },
            { "battania", new[] { "Fian Champion",          "بطل الفيان" } },
            { "khuzait",  new[] { "Khan's Guard",           "حرس الخان" } },
            { "aserai",   new[] { "Faris · Mameluke",       "الفارس · المملوك" } },
        };
        // one short line under the raised banner (the game's own description is a long paragraph that would cover the warrior)
        static readonly Dictionary<string, string[]> Short = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            { "empire",   new[] { "Heirs of a crumbling empire: disciplined legions and armoured cataphracts.", "ورثة إمبراطورية بتتهاوى: فيالق منظمة وفرسان مدرّعين." } },
            { "vlandia",  new[] { "Feudal lords who win their wars at the tip of a couched lance.", "لوردات إقطاع بيكسبوا حروبهم بسن الرمح وهم على الخيل." } },
            { "sturgia",  new[] { "Hard warriors of the north, of the shield wall and the longship.", "محاربين الشمال القاسيين، أهل جدار الدروع والسفن الطويلة." } },
            { "battania", new[] { "Forest clans who strike from the trees and vanish again.", "قبايل الغابة، بيضربوا من بين الشجر ويختفوا تاني." } },
            { "khuzait",  new[] { "Steppe horse archers. Speed decides every battle they choose.", "رماة الخيل في السهوب. السرعة بتحسم كل معركة يختاروها." } },
            { "aserai",   new[] { "Desert merchants and riders who rule the caravan roads.", "تجار وفرسان الصحرا، أسياد طرق القوافل." } },
        };
        static DateTime next = DateTime.MinValue;
        static int errors;

        public static void Tick()
        {
            try
            {
                var t0 = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                UiHerald.Tick(t0 != null && t0.GetType().FullName == "SandBox.View.Map.MapScreen");
            }
            catch { }
            try { Animate(); } catch (Exception e) { if (++errors <= 3) Log.W("UiCulture anim: " + e.Message); kbW = null; }
            if (DateTime.UtcNow < next) return;
            next = DateTime.UtcNow.AddMilliseconds(250);
            try
            {
                var top = ScreenManager.TopScreen;
                var tn = top == null ? "" : top.GetType().Name;
                if (tn.IndexOf("CharacterCreation", StringComparison.Ordinal) < 0 && tn.IndexOf("FaceGen", StringComparison.Ordinal) < 0 && tn.IndexOf("Barber", StringComparison.Ordinal) < 0 && tn.IndexOf("BodyGenerator", StringComparison.Ordinal) < 0) return;
                foreach (var l in top.Layers)
                {
                    var gl = l as GauntletLayer;
                    if (gl != null && gl.UIContext != null) Fill(gl.UIContext.Root);
                }
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiCulture: " + e.Message); }
        }

        // v5 «اختار شعبك»: the record of the chosen people (the game has no such data): army style 1-5, its elite, how it plays
        static readonly Dictionary<string, int[]> Army = new Dictionary<string, int[]>(StringComparer.Ordinal)
        {   // cavalry, infantry, archers, economy
            { "empire", new[] { 4, 4, 3, 4 } }, { "vlandia", new[] { 5, 3, 3, 3 } }, { "sturgia", new[] { 2, 5, 2, 3 } },
            { "battania", new[] { 2, 4, 5, 2 } }, { "khuzait", new[] { 5, 2, 5, 3 } }, { "aserai", new[] { 4, 3, 3, 5 } },
        };
        // the board's line under the name, and the town each people starts near
        static readonly Dictionary<string, string[]> Line5 = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            { "vlandia",  new[] { "Heavy horse that breaks the ranks, and strong castles in the west.", "خيّالة تقيلة بتكسر الصفوف، وقلاع حصينة في الغرب." } },
            { "sturgia",  new[] { "Heavily armoured axemen who do not break in the snow.", "مشاة بدروع تقيلة وفأس، ورجالة ما بيتهزوش في التلج." } },
            { "empire",   new[] { "A disciplined, balanced army, and councils that give more influence than anyone.", "جيش منظم ومتوازن، ومجالس بتدّي نفوذ أكتر من أي حد." } },
            { "aserai",   new[] { "Desert merchants and riders: cheaper caravans and open roads.", "تجار الصحرا وفرسانها؛ قوافل أرخص وطرق مفتوحة." } },
            { "khuzait",  new[] { "Steppe horse archers. Speed decides every battle they choose.", "رماة الخيل في السهوب. السرعة بتحسم كل معركة بيختاروها." } },
            { "battania", new[] { "Forest hunters and ambushers: elite archers and heavy swords.", "صيادين الغابة وكماينها؛ رماة نخبة وسيوف تقيلة." } },
        };
        static readonly Dictionary<string, string[]> Town = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            { "vlandia", new[] { "Pravend", "براڤن" } }, { "sturgia", new[] { "Balgard", "بالتوكا" } }, { "empire", new[] { "Lycaron", "ليكارون" } },
            { "aserai", new[] { "Qasira", "قصار" } }, { "khuzait", new[] { "Makeb", "مكيب" } }, { "battania", new[] { "Marunath", "ماراثيا" } },
        };
        static readonly string[][] StepNames = { new[] { "People", "الشعب" }, new[] { "Family", "العيلة" }, new[] { "Childhood", "الطفولة" }, new[] { "Youth", "المراهقة" },
            new[] { "Adulthood", "الشباب" }, new[] { "Age", "السن" }, new[] { "Face", "الشكل" }, new[] { "Banner", "الراية" }, new[] { "Name", "الاسم" }, new[] { "Review", "المراجعة" } };

        // the board's motion: the portrait slides in and its picture drifts (22 s), the record follows, the meters grow, the ambient light fades in
        static Widget kbW, ambW, portW, infoW; static readonly Widget[] mfW = new Widget[4]; static int[] armyNow = { 0, 0, 0, 0 };
        static string animCid, goText = ""; static DateTime cidAt = DateTime.MinValue, kbStart = DateTime.UtcNow;
        static float E(float x) { if (x <= 0) return 0; if (x >= 1) return 1; return 1f - (float)Math.Pow(1 - x, 3.2); }
        static void SetA(Widget w, float a) { if (w == null) return; w.AlphaFactor = a; for (int i = 0; i < w.ChildCount; i++) SetA(w.GetChild(i), a); }
        static void Animate()
        {
            if (kbW == null) return;
            if (kbW.ParentWidget == null) { kbW = null; return; }
            float t = (float)(DateTime.UtcNow - kbStart).TotalSeconds;
            float ph = (t / 22f) % 2f; float e = ph < 1 ? ph : 2 - ph; e = e < 0.5f ? 2 * e * e : 1 - (float)Math.Pow(-2 * e + 2, 2) / 2;
            float sc = 1.04f + 0.10f * e;
            kbW.SuggestedWidth = 640f * sc; kbW.SuggestedHeight = 800f * sc; kbW.PositionXOffset = -12f * e * sc; kbW.PositionYOffset = 8f * e * sc;
            if (cidAt == DateTime.MinValue) return;
            float c = (float)(DateTime.UtcNow - cidAt).TotalSeconds;
            if (c > 2.4f) return;
            if (portW != null) { var k = E(c / 0.9f); SetA(portW, k); portW.PositionXOffset = -40f * (1 - k); }
            if (infoW != null) { var k = E((c - 0.15f) / 0.8f); SetA(infoW, k); infoW.PositionXOffset = 30f * (1 - k); }
            if (ambW != null) ambW.AlphaFactor = Math.Min(1f, c / 1.1f);
            for (int i = 0; i < 4; i++)
                if (mfW[i] != null) { var k = E((c - 0.3f - 0.1f * i) / 1.2f); mfW[i].SuggestedWidth = 313f * armyNow[i] / 5f * k; }
        }
        static readonly Dictionary<string, string[]> Way = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            { "empire",   new[] { "Disciplined legions", "فيالق منظمة", "Big armies and order", "الجيوش الكبيرة والنظام" } },
            { "vlandia",  new[] { "Heavy knights", "فرسان تقيلة", "The charge that ends a battle", "الهجمة اللي بتنهي المعركة" } },
            { "sturgia",  new[] { "The shield wall", "جدار الدروع", "Holding the line in the cold", "الصمود في الصف وفي البرد" } },
            { "battania", new[] { "Forest archers", "رماة الغابة", "Ambush and vanish", "الكمين والاختفا" } },
            { "khuzait",  new[] { "Horse archers", "رماة خيالة", "Speed and open steppe", "السرعة والسهوب المفتوحة" } },
            { "aserai",   new[] { "Riders and caravans", "فرسان وقوافل", "Trade and the desert roads", "التجارة وطرق الصحرا" } },
        };
        static void FillV5(Widget root)
        {
            string cid = null;
            UiText.Walk(root, c => { if (c.Id == "AurCultV5Key") { var p = c.GetType().GetProperty("CurrentCultureId"); if (p != null) cid = p.GetValue(c, null) as string; } });
            string[] e, sd, wy; int[] ar;
            var elite = cid != null && Elite.TryGetValue(cid, out e) ? UiText.L(e[0], e[1]) : "—";
            var way = cid != null && Way.TryGetValue(cid, out wy) ? wy : null;
            if (cid == null || !Army.TryGetValue(cid, out ar)) ar = new[] { 0, 0, 0, 0 };
            string[] tw; var town = cid != null && Town.TryGetValue(cid, out tw) ? UiText.L(tw[0], tw[1]) : "—";
            int nOf = cid == null ? -1 : UiLoading.CultureCount(cid);
            string capName = null;
            UiText.Walk(root, w =>
            {
                var i = w.Id;
                if (i == "AurCultV5Key") kbW = w;
                else if (i == "AurCuAmbBox") ambW = w;
                else if (i == "AurCultPort") portW = w;
                else if (i == "AurCultInfo") infoW = w;
                else if (i == "AurCultCapN") { var t = w as TextWidget; if (t != null) capName = t.Text; }
