        static void AskLive()
        {
            var host = Slots.LastHost;
            if (string.IsNullOrEmpty(host) || (DateTime.UtcNow - liveAsked).TotalSeconds < 20) return;
            liveAsked = DateTime.UtcNow;
            var th = new System.Threading.Thread(() =>
            {
                try
                {
                    var req = (System.Net.HttpWebRequest)System.Net.WebRequest.Create("http://" + host + ":4201/status");
                    req.Timeout = 3000; req.ReadWriteTimeout = 3000;
                    string r;
                    using (var resp = req.GetResponse())
                    using (var sr = new System.IO.StreamReader(resp.GetResponseStream(), System.Text.Encoding.UTF8)) r = sr.ReadToEnd();
                    var d = Mj.Parse(r) as Dictionary<string, object>;
                    var n = (int)Mj.N(d, "players", -1);
                    if (n > 0) LiveCount = n;
                    object co;
                    if (d != null && d.TryGetValue("cultures", out co) && co is Dictionary<string, object>)
                    {
                        lock (cultures)
                        {
                            cultures.Clear();
                            foreach (var kv in (Dictionary<string, object>)co) { try { cultures[kv.Key] = Convert.ToInt32(kv.Value, System.Globalization.CultureInfo.InvariantCulture); } catch { } }
                        }
                        culturesKnown = true;
