        // ---- progress of the join, read from Coop's own lines (before they are translated). Each step owns a slice of the bar;
        // steps that report a count ("33,814 packets remaining") fill their slice by that count, the others creep inside it.
        // The last count reaching zero and "Entering campaign" make 100 %, right as the player enters.
        static int phase = -1; static float phaseFrac, phaseCreep, shown; static int countMax; static string lastLine = "";
        static readonly float[] PhLo = { 0f, 6f, 12f, 40f, 55f, 60f, 100f }, PhHi = { 6f, 12f, 40f, 55f, 60f, 99f, 100f };
        static readonly int[] PhStep = { 0, 1, 2, 2, 3, 3, 4 };   // which of the four steps a phase belongs to (4 = all done)
        public static void ResetProgress() { phase = -1; phaseFrac = 0; phaseCreep = 0; shown = 0; countMax = 0; lastLine = ""; }
        static bool Has(string s, string part) { return s.IndexOf(part, StringComparison.OrdinalIgnoreCase) >= 0; }
        static int CountBefore(string s, string marker)
        {
            var cut = s.IndexOf(marker, StringComparison.Ordinal);
            if (cut <= 0) return -1;
            int e = cut - 1; while (e >= 0 && s[e] == ' ') e--;
            int b = e; while (b >= 0 && (char.IsDigit(s[b]) || s[b] == ',' || s[b] == '.')) b--;
            if (b >= e) return -1;
            int n; return int.TryParse(s.Substring(b + 1, e - b).Replace(",", "").Replace(".", ""), out n) ? n : -1;
        }
        static void Track(string t, string d)
        {
            try
            {
                var s = (t ?? "") + " | " + (d ?? "");
                if (s == lastLine) return; lastLine = s;
                int ph = -1, n = -1;
                if (Has(s, "Entering campaign")) ph = 6;
                else if (Has(s, "Catching up")) { ph = 5; n = CountBefore(s, " packets remaining"); }
                else if (Has(s, "Creating remote player heroes") || Has(s, "synced object lifetimes") || Has(s, "Sending your character")) ph = 4;
                else if (Has(s, "Loading Host Campaign") || Has(s, "Loading campaign save") || Has(s, "Loading host save data") || Has(s, "save data received")) ph = 3;
                else if (Has(s, "save packets remaining") || Has(s, "host save data") || Has(s, "Joining Coop Campaign") || Has(s, "server to load the campaign")) { ph = 2; n = CountBefore(s, " save packets remaining"); }
                else if (Has(s, "patches")) ph = 1;
                else if (Has(s, "Connecting")) ph = 0;
                if (ph < 0 || ph < phase) return;
                if (ph > phase) { phase = ph; phaseFrac = 0; phaseCreep = 0; countMax = 0; }
                if (n >= 0)
                {
                    if (n > countMax) countMax = n;
                    if (countMax > 0) phaseFrac = Math.Max(phaseFrac, 1f - (float)n / countMax);
                }
            }
            catch { }
        }
        static float Target(float dt)
        {
            if (TaleWorlds.CampaignSystem.Campaign.Current != null && phase >= 5 && phaseFrac >= 0.999f) return 100f;
            int p = Math.Max(0, phase);
            // inside a step with no count the bar creeps toward 70 % of its slice and never past it
            phaseCreep = Math.Min(0.7f, phaseCreep + dt * (0.7f - phaseCreep) / 12f);
            float f = countMax > 0 ? phaseFrac : Math.Max(phaseFrac, phaseCreep);
            return PhLo[p] + (PhHi[p] - PhLo[p]) * f;
        }

        static readonly string[][] Steps = { new[] { "Connection", "الاتصال" }, new[] { "Mods", "المودات" }, new[] { "World data", "بيانات العالم" }, new[] { "Your hero", "بطلك" } };
        static void Progress(Dictionary<string, Widget> d, float dt)
        {
            float target = Target(dt);
            if (target < shown) target = shown;
            shown += (target - shown) * Math.Min(1f, dt * 4f);
            if (target - shown < 0.05f) shown = target;
            Widget w;
            if (d.TryGetValue("AurLoadPct", out w)) UiText.Set(w, ((int)Math.Floor(shown)) + "%");
            if (d.TryGetValue("AurLoadFill", out w)) { var full = (w.ParentWidget != null && w.ParentWidget.SuggestedWidth > 8f) ? w.ParentWidget.SuggestedWidth : 400f; var want = Math.Max(10f, full * shown / 100f); if (Math.Abs(w.SuggestedWidth - want) > 0.25f) w.SuggestedWidth = want; }
            if (d.TryGetValue("AurLoadTitle", out w))
            {
                var tw = w as TextWidget;
                if (tw != null && string.IsNullOrEmpty(tw.Text)) tw.Text = UiText.L("Entering Aurelion", "داخلين عالم أوريليون");
            }
            int s = PhStep[Math.Max(0, phase)];
            for (int i = 0; i < 4; i++)
            {
                Widget ic, tx;
                if (!d.TryGetValue("AurStI" + i, out ic) || !d.TryGetValue("AurStT" + i, out tx)) continue;
                int state = i < s ? 2 : i == s ? 1 : 0;   // 0 waiting, 1 now, 2 done
                bool v6 = ic.SuggestedWidth >= 30f;   // v6 file: a 34 px circle for every step
                if (v6) { if (!ic.IsVisible) ic.IsVisible = true; var sp6 = Spr(ic, state == 2 ? "aur_v6\\step_done" : state == 1 ? "aur_v6\\step_now" : "aur_v6\\step_wait"); if (sp6 != null && ic.Sprite != sp6) ic.Sprite = sp6; }
                else
                {
                    if (ic.IsVisible != (state != 0)) ic.IsVisible = state != 0;
                    if (state != 0) { var sp = Spr(ic, state == 2 ? "aur_v5\\st_ok" : "aur_v5\\st_on"); if (sp != null && ic.Sprite != sp) ic.Sprite = sp; }
                    float mr = state != 0 ? 6 : 0; if (tx.MarginRight != mr) tx.MarginRight = mr;
                }
                var bw = tx as BrushWidget;
                if (bw != null && bw.Context != null)
                {
                    var br = bw.Context.GetBrush(state == 2 ? "Aur.L.StOk" : state == 1 ? "Aur.L.StOn" : "Aur.L.StDim");
                    if (br != null && bw.Brush != br) bw.Brush = br;
                }
                UiText.Set(tx, UiText.L(Steps[i][0], Steps[i][1]));
            }
        }
        static readonly Dictionary<string, TaleWorlds.TwoDimension.Sprite> sprites = new Dictionary<string, TaleWorlds.TwoDimension.Sprite>();
        static TaleWorlds.TwoDimension.Sprite Spr(Widget w, string name)
        {
            TaleWorlds.TwoDimension.Sprite s;
            if (sprites.TryGetValue(name, out s) && s != null) return s;
            try { s = w.Context.SpriteData.GetSprite(name); } catch { s = null; }
            sprites[name] = s; return s;
        }

        static float Ease(float x) { if (x <= 0) return 0; if (x >= 1) return 1; return 1f - (float)Math.Pow(1 - x, 3.2); }   // cubic-bezier(.2,.8,.2,1)
        static float InOut(float x) { return x < 0.5f ? 2 * x * x : 1 - (float)Math.Pow(-2 * x + 2, 2) / 2; }
        static void Alpha(Widget w, float a)
        {
            if (w == null) return;
            if (w.AlphaFactor != a) w.AlphaFactor = a;
            for (int i = 0; i < w.ChildCount; i++) Alpha(w.GetChild(i), a);
        }
        // the board's entrances: fade in while sliding (dx, dy) back to the place the file gives
        static void Enter(Dictionary<string, Widget> d, string id, float t, float delay, float dx, float dy, float baseX)
        {
            Widget w; if (!d.TryGetValue(id, out w)) return;
            float k = Ease((t - delay) / 0.7f);
            if (k >= 1f && w.AlphaFactor >= 1f && w.PositionYOffset == 0f && w.PositionXOffset == baseX) return;
            Alpha(w, k);
            w.PositionXOffset = baseX + dx * (1 - k);
            w.PositionYOffset = dy * (1 - k);
        }
        static void Ring(Dictionary<string, Widget> d, string id, float now)
        {
            Widget w; if (!d.TryGetValue(id, out w)) return;
            int f = (int)((now % 1.1f) / 1.1f * 24f) % 24;   // 22 frames a second: the ring turns smoothly
            var sp = Spr(w, "aur_v5\\ring_f" + f.ToString("00"));
            if (sp != null && w.Sprite != sp) w.Sprite = sp;
        }
        static void KenBurns(Widget w, float now, float period, float baseW, float baseH, float zoom, float dx, float dy)
        {
            if (w == null) return;
            // the picture stands still: resizing it every frame re-laid the whole loading screen and made it stutter
            float s = 1.04f;
            if (w.SuggestedWidth != baseW * s) { w.SuggestedWidth = baseW * s; w.SuggestedHeight = baseH * s; w.PositionXOffset = 0; w.PositionYOffset = 0; }
        }
        static void Embers(Dictionary<string, Widget> d, string px, float now, float[] dur, float[] delay)
        {
            Widget w;
            for (int i = 0; i < dur.Length; i++)
            {
                if (!d.TryGetValue(px + i, out w)) continue;
                float p = ((now + delay[i]) % dur[i]) / dur[i];
                w.PositionYOffset = -760f * p; w.PositionXOffset = 40f * p;
                w.AlphaFactor = p < 0.12f ? 0.9f * p / 0.12f : 0.9f * (1 - (p - 0.12f) / 0.88f);
            }
        }
        static readonly float[] EmbDur = { 13.9f, 11.1f, 10.8f, 10.6f, 14.9f, 7.1f, 8.5f, 9.6f, 8.9f, 7.7f, 15.0f, 13.1f };
        static readonly float[] EmbDel = { 12.9f, 8.8f, 9.2f, 2.1f, 14.5f, 7.9f, 3.6f, 8.9f, 4.4f, 9.8f, 12.6f, 7.7f };
        static readonly float[] WEmbDur = { 14.6f, 13.6f, 8.7f, 8.9f, 8.0f, 11.7f, 11.5f, 11.3f, 11.7f, 11.4f };
        static readonly float[] WEmbDel = { 5.9f, 1.4f, 1.3f, 8.3f, 3.3f, 0.7f, 2.0f, 8.6f, 9.6f, 0.9f };

        // a seal that grows into place and fades in (no turning: the interface turns widgets around a corner)
        static void Seal(Dictionary<string, Widget> d, string id, string shadowId, float t, float size, float shadow)
        {
            Widget w; float k = Ease(t / 1.4f);
            if (d.TryGetValue(id, out w) && (k < 1f || w.AlphaFactor < 1f || w.SuggestedWidth != size))
            { w.AlphaFactor = k; w.SuggestedWidth = w.SuggestedHeight = size * (0.6f + 0.4f * k); w.PositionYOffset = size * 0.2f * (1 - k); }
            if (shadowId != null && d.TryGetValue(shadowId, out w) && (k < 1f || w.AlphaFactor < 1f))
            { w.AlphaFactor = k; w.SuggestedWidth = w.SuggestedHeight = shadow * (0.6f + 0.4f * k); w.PositionYOffset = shadow * 0.2f * (1 - k); }
        }

