        public static void Tick(bool screensReady)
        {
            if (!hooked) Hook();
            var now = DateTime.UtcNow;
            float dt = lastTick == DateTime.MinValue ? 0.016f : (float)Math.Min(0.25, (now - lastTick).TotalSeconds); lastTick = now;
            bool loading = false; try { loading = TaleWorlds.Engine.LoadingWindow.IsLoadingWindowActive; } catch { }
            // our pictures must stay on the graphics card while our screens are up; if anything dropped them, they come back now
            try
            {
                if (ours != null && loading && (now - spriteCheck).TotalSeconds > 0.5)
                {
                    spriteCheck = now;
                    AurelionSkin.EnsureSprite("aur_load", "aur_load_1.png"); AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png"); AurelionSkin.EnsureSprite("aur_v6", "aur_v6_1.png");
                    if (ours == "AurChooserWait") AurelionSkin.EnsureSprite("aur_bg_hall_dim", "aur_bg_hall_dim_1.png");
                }
            }
            catch { }
            try { UiEncounter.Tick(); } catch { }
            try { UiQuest.Tick(); } catch { }
            try { UiInvStrip.Tick(); } catch { }
            try { UiTown.Tick(); } catch { }
            // without AurMotionWidget the game's tick moves what it can
            try
            {
                if (!UiMotion.Ready && ours != null && loading && ids != null)
                {
                    idsSince += dt;
                    Animate(ids, idsMode, idsSince, dt);
                }
            }
            catch (Exception e) { if (++animErrors <= 3) Log.W("UiLoading anim: " + e.Message); }
            // back on the game's main menu with no world: the next loading screen is the game's own again
            try
            {
                var top = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (Slots.Joining && TaleWorlds.CampaignSystem.Campaign.Current == null && top != null && top.GetType().Name == "GauntletInitialScreen"
                    && !loading && !Slots.ChooserOpen)
                {
                    if (menuSince == DateTime.MinValue) menuSince = DateTime.UtcNow;
                    else if ((DateTime.UtcNow - menuSince).TotalSeconds > 5) { Slots.Joining = false; menuSince = DateTime.MinValue; }
                }
                else menuSince = DateTime.MinValue;
            }
            catch { }
        }
