        static string ToArabic(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            var t = s.Trim(); string a;
            if (Ar.TryGetValue(t, out a)) return a;
            // "Catching up to the host... 33,814 packets remaining"
            const string catching = "Catching up to the host...";
            if (t.StartsWith(catching, StringComparison.Ordinal))
            {
                var rest = t.Substring(catching.Length).Trim();
                var cut = rest.IndexOf(" packets remaining", StringComparison.Ordinal);
                if (cut > 0) return "بنلحق بالسيرفر... فاضل " + rest.Substring(0, cut);
                return "بنلحق بالسيرفر...";
            }
            const string waiting = "Waiting for host save data...";
            if (t.StartsWith(waiting, StringComparison.Ordinal)) {
                var r = t.Substring(waiting.Length).Trim();
                var rp = r.IndexOf(" save packets remaining", StringComparison.Ordinal);
                if (rp > 0) return "بنستلم بيانات العالم... فاضل " + r.Substring(0, rp).Trim();
                return "مستنيين بيانات العالم... " + r;
            }
            var sp = t.IndexOf(" save packets remaining", StringComparison.Ordinal);
            if (sp > 0) return "بنستلم بيانات العالم... فاضل " + t.Substring(0, sp).Trim();
            return s;
        }
        public static void Translate(ref string titleText, ref string descriptionText)
        {
            Track(titleText, descriptionText);
            try { if (!UiText.Arabic) return; titleText = ToArabic(titleText); descriptionText = ToArabic(descriptionText); }
            catch { }
        }

        // just before a loading screen shows: ours when the player is going into (or is in) the world, the game's otherwise.
        // The movie is swapped while still hidden, so nothing flashes.
        public static void BeforeEnable(object __instance)
        {
            try
            {
                if (__instance == null) return;
                // into the world: our loading screen. From the launcher's Play until the choice opens: the choice's own hall,
                // so the game's logo is followed straight by the character choice. Anything else: the game's own.
                string want = null;
                if (Slots.Joining || TaleWorlds.CampaignSystem.Campaign.Current != null) want = "AurLoadingWindow";
                else if (Slots.LaunchCover && !Slots.ChooserOpen) want = "AurChooserWait";
                if (want != null && UiScreens.IsOff(want)) want = null;
                if (want == ours) return;
                var t = __instance.GetType();
                var fl = AccessTools.Field(t, "_gauntletLayer"); var fm = AccessTools.Field(t, "_movie"); var fv = AccessTools.Field(t, "_loadingWindowViewModel");
                if (fl == null || fm == null || fv == null) return;
                var layer = fl.GetValue(__instance) as GauntletLayer;
                var vm = fv.GetValue(__instance) as ViewModel;
                var old = fm.GetValue(__instance) as GauntletMovieIdentifier;
                if (layer == null || vm == null) return;
                if (want != null && !AurelionSkin.EnsureSprite("aur_v6", "aur_v6_1.png")) return;
                if (want == "AurLoadingWindow" && (!AurelionSkin.EnsureSprite("aur_load", "aur_load_1.png") || !AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png"))) return;
                if (want == "AurChooserWait" && (!AurelionSkin.EnsureSprite("aur_bg_hall_dim", "aur_bg_hall_dim_1.png") || !AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png"))) return;
                var fresh = layer.LoadMovie(want == null ? "LoadingWindow" : UiMotion.Movie(want), vm);   // built first: if it fails, the old one stays
                if (fresh == null) return;
                if (old != null) layer.ReleaseMovie(old);
                fm.SetValue(__instance, fresh);
                ours = want;
                ids = null;
                Log.W("UiLoading: " + (want == null ? "the game's own loading screen" : want + (UiMotion.Ready ? "" : " (plain motion)")));
            }
            catch (Exception e) { if (++swapErrors <= 3) Log.W("UiLoading swap: " + (e.InnerException ?? e).Message); }
        }

        public static void OnEnable(object __instance)
        {
            try
            {
                if (ours == null || __instance == null) return;
                var f = AccessTools.Field(__instance.GetType(), "_gauntletLayer");
                var layer = f == null ? null : f.GetValue(__instance) as GauntletLayer;
                if (layer == null || layer.UIContext == null) return;
                liveLayer = layer; liveShown = null; AskLive();
                if (UiMotion.Ready) return;   // AurMotionWidget sets the texts and moves the scene itself
                ids = Index(layer.UIContext.Root);
                idsMode = ours == "AurChooserWait" ? "wait" : "load";
                idsSince = Begin(ids, idsMode);
            }
            catch { }
        }
    }


