    // When a player arrives on the map, a short card greets them by name under their culture's medallion: the date of the realm,
    // their clan and kingdom, and how many players are in the world right now. It slides in, the hairline opens from the centre,
    // and it leaves by itself after a few seconds. It never takes the mouse and shows once per arrival.
    public class HeraldVM : TaleWorlds.Library.ViewModel
    {
        float alpha, y, line; string kicker = "", title = "", line3 = "";
        [TaleWorlds.Library.DataSourceProperty] public float Alpha { get { return alpha; } set { if (value != alpha) { alpha = value; OnPropertyChangedWithValue(value, "Alpha"); } } }
        [TaleWorlds.Library.DataSourceProperty] public float Y { get { return y; } set { if (value != y) { y = value; OnPropertyChangedWithValue(value, "Y"); } } }
        [TaleWorlds.Library.DataSourceProperty] public float Line { get { return line; } set { if (value != line) { line = value; OnPropertyChangedWithValue(value, "Line"); } } }
        [TaleWorlds.Library.DataSourceProperty] public string Kicker { get { return kicker; } set { if (value != kicker) { kicker = value ?? ""; OnPropertyChangedWithValue(kicker, "Kicker"); } } }
        [TaleWorlds.Library.DataSourceProperty] public string Title { get { return title; } set { if (value != title) { title = value ?? ""; OnPropertyChangedWithValue(title, "Title"); } } }
        [TaleWorlds.Library.DataSourceProperty] public string Line3 { get { return line3; } set { if (value != line3) { line3 = value ?? ""; OnPropertyChangedWithValue(line3, "Line3"); } } }
    }
    public class UiHerald : GlobalLayer
    {
        static UiHerald open; static object shownFor; static DateTime readySince = DateTime.MinValue; static int errors;
        HeraldVM vm; GauntletLayer layer; object movie; DateTime start;
        const float In = 0.6f, LineFrom = 0.25f, LineTo = 1.2f, Hold = 5.4f, Out = 0.8f;

        // called every frame
        public static void Tick(bool onMap)
        {
            try
            {
                if (open != null) { open.Step(); return; }
                // team machines only (dev-tools marker): Ctrl+Shift+F8 shows the welcome again
                // (the keyboard is not ready during the first frames of the game: that threw "Object reference not set" at every start)
                try
                {
                    if (Dev && TaleWorlds.InputSystem.Input.IsKeyPressed(TaleWorlds.InputSystem.InputKey.F8)
                        && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftControl) && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftShift))
                        shownFor = null;
                }
                catch { }
                var c = TaleWorlds.CampaignSystem.Campaign.Current;
                var h = TaleWorlds.CampaignSystem.Hero.MainHero;
                bool loading = false;
                try { loading = TaleWorlds.Engine.LoadingWindow.IsLoadingWindowActive; } catch { }
                if (!onMap || c == null || h == null || loading || ReferenceEquals(shownFor, c)) { readySince = DateTime.MinValue; return; }
                if (readySince == DateTime.MinValue) { readySince = DateTime.UtcNow; return; }
                if ((DateTime.UtcNow - readySince).TotalSeconds < 1.4) return;   // let the loading screen fade first
                shownFor = c; Show(h);
            }
            catch (Exception e) { if (++errors <= 2) Log.W("UiHerald: " + e.Message); Close(); }
        }

        static void Show(TaleWorlds.CampaignSystem.Hero h)
        {
            AurelionSkin.EnsureSprite("aur_cult", "aur_cult_1.png");
            AurelionSkin.EnsureSprite("aur_skin2", "aur_skin2_1.png");
            var vm = new HeraldVM();
            bool ar = UiText.Arabic;
            string name = h.Name != null ? h.Name.ToString() : "";
            string date = "";
            try { date = TaleWorlds.CampaignSystem.CampaignTime.Now.ToString(); } catch { }
            vm.Kicker = (ar ? "أوريليون" : "AURELION") + (date.Length > 0 ? "  ·  " + date : "");
            vm.Title = ar ? "نوّرت المملكة يا " + name : "The realm greets you, " + name;
            var parts = new List<string>();
            if (h.Clan != null && h.Clan.Name != null) parts.Add(h.Clan.Name.ToString());
            if (h.Clan != null && h.Clan.Kingdom != null && h.Clan.Kingdom.Name != null) parts.Add(h.Clan.Kingdom.Name.ToString());
            else parts.Add(ar ? "من غير مملكة" : "no kingdom yet");
            int n = UiLoading.LiveCount;
            if (n > 0) parts.Add(ar ? (n == 1 ? "لاعب واحد أونلاين" : n == 2 ? "لاعبين أونلاين" : n + (n <= 10 ? " لاعبين" : " لاعب") + " أونلاين")
                                    : n + (n == 1 ? " player online" : " players online"));
            vm.Line3 = string.Join("  ·  ", parts.ToArray());
            vm.Alpha = 0; vm.Y = -18; vm.Line = 0;
            var s = new UiHerald();
            s.vm = vm;
            s.layer = new GauntletLayer("AurelionHerald", 2500, false);
            s.movie = s.layer.LoadMovie("AurWelcome", vm);
            s.Layer = s.layer;
            ScreenManager.AddGlobalLayer(s, false);
            s.start = DateTime.UtcNow;
            open = s;
            // the medallion of the hero's culture (cultures without a medallion keep the Aurelion one)
            try
            {
                var cid = h.Culture != null ? h.Culture.StringId : null;
                var sd = UIResourceManager.SpriteData;
                var sp = cid == null || sd == null ? null : sd.GetSprite("aur_cult\\embs_" + cid);
                if (sp != null && s.layer.UIContext != null)
                    UiText.Walk(s.layer.UIContext.Root, w => { if (w.Id == "AurWEmb") w.Sprite = sp; });
            }
            catch { }
            Log.W("UiHerald: welcome shown");
        }

        static int dev = -1;
        public static bool Dev
        {
            get
            {
                if (dev < 0) { try { dev = System.IO.File.Exists(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Aurelion", "Studio", "dev-tools.txt")) ? 1 : 0; } catch { dev = 0; } }
                return dev == 1;
            }
        }
        static float Ease(float t) { t = t < 0 ? 0 : (t > 1 ? 1 : t); return 1f - (1f - t) * (1f - t) * (1f - t); }
        void Step()
        {
            var t = (float)(DateTime.UtcNow - start).TotalSeconds;
            if (t < Hold) { var a = Ease(t / In); vm.Alpha = a; vm.Y = -18f * (1f - a); }
            else { var a = Ease((t - Hold) / Out); vm.Alpha = 1f - a; vm.Y = -10f * a; }
            vm.Line = 560f * Ease((t - LineFrom) / (LineTo - LineFrom));
            if (t >= Hold + Out) Close();
        }

        static void Close()
        {
            var s = open; open = null; if (s == null) return;
            try { if (s.movie != null) s.layer.ReleaseMovie((GauntletMovieIdentifier)s.movie); } catch { }
            try { AurLayers.Remove(s); } catch (Exception e) { Log.W("UiHerald close: " + e.Message); }
            try { s.vm.OnFinalize(); } catch { }
        }
    }

