        public static bool Message(object[] __args)
        {
            try
            {
                var message = __args != null && __args.Length > 0 ? __args[0] : null;
                if (message == null) return true;
                if (infoProp == null) infoProp = AccessTools.Property(message.GetType(), "Information");
                var t = infoProp == null ? null : infoProp.GetValue(message, null) as string;
                if (t == null) return true;
                foreach (var h in Hidden) if (t.StartsWith(h, StringComparison.Ordinal)) return false;
                var a = To(t);
                if (!ReferenceEquals(a, t))
                {
                    if (infoProp.CanWrite) infoProp.SetValue(message, a, null);
                    else
                    {
                        if (infoField == null) infoField = AccessTools.Field(message.GetType(), "<Information>k__BackingField");
                        if (infoField != null) infoField.SetValue(message, a);
                    }
                }
            }
            catch { }
            return true;
        }

        // the menu entries live in InitialMenuVM.MenuOptions; each one carries its InitialStateOption (field), whose Id names it
        public static void NoHost(object __instance)
        {
            try
            {
                if (__instance == null || UiHerald.Dev) return;
                var lp = __instance.GetType().GetProperty("MenuOptions");
                var list = lp == null ? null : lp.GetValue(__instance, null) as System.Collections.IList;
                if (list == null) return;
                for (int i = list.Count - 1; i >= 0; i--)
                {
                    var o = list[i]; if (o == null) continue;
                    var f = o.GetType().GetField("InitialStateOption");
                    var opt = f == null ? null : f.GetValue(o);
                    var idp = opt == null ? null : opt.GetType().GetProperty("Id");
                    var id = idp == null ? null : idp.GetValue(opt, null) as string;
                    if (id == "CoOp Campaign") list.RemoveAt(i);
                }
            }
            catch { }
        }

        // "Encyclopedia (3 online)" -> "الموسوعة (3 أونلاين)"; the old suffix is taken off first so it is never added twice
        // the encyclopedia breadcrumb starts with the game's untranslated "Home" (plain or inside link markup)
        static readonly System.Text.RegularExpressions.Regex HomeRx = new System.Text.RegularExpressions.Regex(@"(?<a>^|>)\s*Home(?=\s|<|$)");
        static readonly System.Text.RegularExpressions.Regex OnlineRx = new System.Text.RegularExpressions.Regex(@"\s*\((\d+) (online|أونلاين)\)");
        public static void Title(ref string __result)
        {
            try
            {
                if (string.IsNullOrEmpty(__result) || !UiText.Arabic) return;
                var ms = OnlineRx.Matches(__result);
                if (ms.Count == 0) return;
                var n = ms[ms.Count - 1].Groups[1].Value;
                __result = OnlineRx.Replace(__result, "") + " (" + n + " أونلاين)";
            }
            catch { }
        }

        // menus and the join screen: their words are written straight into the widgets, so they are swapped there
        static DateTime next = DateTime.MinValue;
        static int errors;
        public static void Tick(TaleWorlds.ScreenSystem.ScreenBase top, bool onMap, bool mission)
        {
            if (mission || !UiText.Arabic || DateTime.UtcNow < next) return;
            if (TaleWorlds.CampaignSystem.Campaign.Current == null) return;   // main menu / join screen: the game's own words stay
            next = DateTime.UtcNow.AddMilliseconds(400);
            try
            {
                var layers = new List<TaleWorlds.Engine.GauntletUI.GauntletLayer>();
                foreach (var l in top.Layers)
                {
                    var g0 = l as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                    if (g0 != null && (!onMap || g0.Name == "EncyclopediaBar")) layers.Add(g0);   // on the map only the encyclopedia, the map itself is too big to walk
                }
                foreach (var f in typeof(TaleWorlds.ScreenSystem.ScreenManager).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
                {
                    if (f.Name.IndexOf("lobal", StringComparison.OrdinalIgnoreCase) < 0) continue;
                    var en = f.GetValue(null) as System.Collections.IEnumerable;
                    if (en == null) continue;
                    foreach (var gl in en)
                    {
                        var lp = gl == null ? null : gl.GetType().GetProperty("Layer");
                        var g1 = lp == null ? null : lp.GetValue(gl, null) as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                        if (g1 != null && g1.Name != null && (g1.Name.StartsWith("Coop", StringComparison.Ordinal) || g1.Name == "EncyclopediaBar")) layers.Add(g1);
                    }
                }
                foreach (var g in layers)
                {
                    if (g == null || g.UIContext == null) continue;
                    UiText.Walk(g.UIContext.Root, w =>
                    {
                        var rw = w as RichTextWidget;
                        if (rw != null && rw.Text != null && rw.Text.IndexOf("Home", StringComparison.Ordinal) >= 0)
                        {
                            var nt = HomeRx.Replace(rw.Text, "${a}الرئيسية");
                            if (nt != rw.Text) rw.Text = nt;
                            return;
                        }
                        var tw = w as TextWidget;
                        if (tw == null || string.IsNullOrEmpty(tw.Text)) return;
                        var a = To(tw.Text);
                        if (ReferenceEquals(a, tw.Text) && tw.Text.StartsWith("Home", StringComparison.Ordinal)) a = HomeRx.Replace(tw.Text, "${a}الرئيسية");
                        if (a != tw.Text) tw.Text = a;
                    });
                }
            }
            catch (Exception e) { if (++errors <= 2) Log.W("UiWords: " + e.Message); }
        }
    }

    // ------------------------------------------------------------------ map HUD on other campaign screens
    // The game keeps its bottom bar (MapBar layer) on every campaign screen. The left buttons and the centre dial behave, but the
    // resources bar on the right stays up and covers the bottom of the inventory list, the party list and their search boxes.
    // On any screen other than the map it is hidden; back on the map it shows again.
    // The message log (ChatLog layer) also stays on every screen and its lines ran over the panels of the character, inventory,
    // party, clan and kingdom screens. On those full-screen menus it is hidden; on the map and in battles it shows as before.
    public static class UiHud
    {
        static WeakReference infoBar, navList, navFrame, navUnread;
        static DateTime next = DateTime.MinValue;
        static int errors;
        static readonly string[] Menus = { "GauntletInventoryScreen", "GauntletPartyScreen", "GauntletClanScreen", "GauntletKingdomScreen",
            "GauntletCharacterDeveloperScreen", "GauntletQuestsScreen", "GauntletEncyclopediaScreenManager", "GauntletEncyclopediaScreen" };
        public static void Tick()
        {
            try
            {
                var t0 = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                UiHerald.Tick(t0 != null && t0.GetType().FullName == "SandBox.View.Map.MapScreen");
            }
            catch { }
            if (DateTime.UtcNow < next) return;
            next = DateTime.UtcNow.AddMilliseconds(250);
            try
            {
                var top = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (top == null) return;
                var tn = top.GetType().Name;
                bool onMap = top.GetType().FullName == "SandBox.View.Map.MapScreen";
                bool menu = Array.IndexOf(Menus, tn) >= 0;
                // the game binds IsVisible and the vertical offset of these widgets, so they are slid out sideways instead
                var w = Get(ref infoBar, "MapBar", "InfoBarWidget");
                float wx = onMap ? 0f : 900f;
                if (w != null && w.PositionXOffset != wx) w.PositionXOffset = wx;
                // the left island (map menus) slides out the other way while a full-screen menu is open
                float lx = onMap ? 0f : -900f;
                foreach (var nw in new[] { Get(ref navList, "MapBar", "MapBar"), Get(ref navFrame, "MapBar", "AurNavFrame"), Get(ref navUnread, "MapBar", "AurNavUnread") })
                    if (nw != null && nw.PositionXOffset != lx) nw.PositionXOffset = lx;
                bool mission = tn.IndexOf("Mission", StringComparison.Ordinal) >= 0;
                PowerTitle(top);
                UiWords.Tick(top, onMap, mission);
                // the message log over the menus: three ways tried (visibility, offsets, layer suspend), the game undoes all of them,
                // so it is left as the game draws it for now
                if (menu && found.Add("chatlog-note")) Log.W("UiHud: message log left as is on menus");
            }
            catch (Exception e) { if (++errors <= 2) Log.W("UiHud: " + e.Message); }
        }
        // "ميزان القوة" over the game's power comparer in the conversation (it lives in a conversation layer, on the map or in a mission)
        static DateTime powerLook = DateTime.MinValue;
        static readonly System.Runtime.CompilerServices.ConditionalWeakTable<TaleWorlds.GauntletUI.BaseTypes.Widget, object> escSeen = new System.Runtime.CompilerServices.ConditionalWeakTable<TaleWorlds.GauntletUI.BaseTypes.Widget, object>();
        static void PowerTitle(TaleWorlds.ScreenSystem.ScreenBase top)
        {
            if (DateTime.UtcNow < powerLook) return;
            powerLook = DateTime.UtcNow.AddSeconds(0.5);
            foreach (var l in top.Layers)
            {
                var gl = l as GauntletLayer;
                if (gl == null || gl.UIContext == null || gl.UIContext.Root == null) continue;
                var r = gl.UIContext.Root;
                if (r.ChildCount == 0) continue;
                var first = r.GetChild(0);
                if (first == null) continue;
                // each new layer is looked through once for our Esc menu subtitle (the Esc layer is made fresh every time it opens)
                object seen;
                if (!escSeen.TryGetValue(r, out seen))
                {
                    escSeen.Add(r, r);
                    bool hit = false;
                    UiText.Walk(r, x => { if (x.Id == "AurEscSub") { hit = true; UiText.Set(x, UiText.L("The game is paused for you only · the world keeps going", "اللعبة واقفة عندك بس · العالم شغّال")); } });
                    if (hit) continue;
                }
                if (first.GetType().Name != "ConversationScreenButtonWidget") continue;
                UiText.Walk(first, x => { if (x.Id == "AurPowerT") UiText.Set(x, UiText.L("BALANCE OF POWER", "ميزان القوة")); });
            }
        }
        static WeakReference chatLayer; static bool chatSuspended; static DateTime chatCheck = DateTime.MinValue;
        static System.Reflection.MethodInfo suspendM;
        static void SuspendChatLog(bool on)
        {
            var layer = chatLayer == null ? null : chatLayer.Target as TaleWorlds.ScreenSystem.ScreenLayer;
            if (layer == null || DateTime.UtcNow >= chatCheck)
            {
                chatCheck = DateTime.UtcNow.AddSeconds(2);
                var fresh = FindLayer("ChatLog");
                if (fresh != layer) { layer = fresh; chatLayer = fresh == null ? null : new WeakReference(fresh); chatSuspended = false; }
            }
            if (layer == null || on == chatSuspended) return;
            if (suspendM == null) suspendM = typeof(TaleWorlds.ScreenSystem.ScreenManager).GetMethod("SetSuspendLayer", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
            if (suspendM == null) { if (found.Add("nosuspend")) Log.W("UiHud: SetSuspendLayer not found, the message log stays on menus"); return; }
            suspendM.Invoke(null, new object[] { layer, on });
            chatSuspended = on;
        }
        static TaleWorlds.ScreenSystem.ScreenLayer FindLayer(string layerName)
        {
            foreach (var f in typeof(TaleWorlds.ScreenSystem.ScreenManager).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
            {
                if (f.Name.IndexOf("lobal", StringComparison.OrdinalIgnoreCase) < 0) continue;
                var en = f.GetValue(null) as System.Collections.IEnumerable;
                if (en == null) continue;
                foreach (var gl in en)
                {
                    var lp = gl == null ? null : gl.GetType().GetProperty("Layer");
                    var l = lp == null ? null : lp.GetValue(gl, null) as TaleWorlds.ScreenSystem.ScreenLayer;
                    if (l != null && l.Name == layerName) return l;
                }
            }
            return null;
        }
        static TaleWorlds.GauntletUI.BaseTypes.Widget Get(ref WeakReference cache, string layerName, string id)
        {
            var w = cache == null ? null : cache.Target as TaleWorlds.GauntletUI.BaseTypes.Widget;
            // layers are rebuilt when a campaign starts or ends: look again every two seconds instead of trusting an old widget
            DateTime due; recheck.TryGetValue(layerName, out due);
            if (w != null && w.EventManager != null && DateTime.UtcNow < due) return w;
            recheck[layerName] = DateTime.UtcNow.AddSeconds(2);
            w = Find(layerName, id); cache = w == null ? null : new WeakReference(w);
            if (w != null && found.Add(layerName + "/" + id)) Log.W("UiHud: found " + layerName + "/" + (id ?? "root") + " (" + w.GetType().Name + ")");
            if (w == null && missing.Add(layerName + "/" + id)) Log.W("UiHud: " + layerName + "/" + (id ?? "root") + " not found yet; global layers: " + Names());
            return w;
        }
        static readonly HashSet<string> found = new HashSet<string>(), missing = new HashSet<string>();
        static readonly Dictionary<string, DateTime> recheck = new Dictionary<string, DateTime>();
        static string Names()
        {
            var sb = new System.Text.StringBuilder();
            try
            {
                foreach (var f in typeof(TaleWorlds.ScreenSystem.ScreenManager).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
                {
                    if (f.Name.IndexOf("lobal", StringComparison.OrdinalIgnoreCase) < 0) continue;
                    var en = f.GetValue(null) as System.Collections.IEnumerable;
                    if (en == null) { sb.Append(f.Name + "=null "); continue; }
                    foreach (var gl in en)
                    {
                        if (gl == null) continue;
                        var lp = gl.GetType().GetProperty("Layer");
                        var l = lp == null ? null : lp.GetValue(gl, null);
                        sb.Append(gl.GetType().Name + ":" + (l == null ? "-" : l.GetType().FullName + "/" + ((TaleWorlds.ScreenSystem.ScreenLayer)l).Name) + " ");
                    }
                }
            }
            catch (Exception e) { sb.Append("(" + e.Message + ")"); }
            return sb.ToString();
        }
        // id == null: the first child under the layer root (the whole layer's content)
        static TaleWorlds.GauntletUI.BaseTypes.Widget Find(string layerName, string id)
        {
            foreach (var f in typeof(TaleWorlds.ScreenSystem.ScreenManager).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
            {
                if (f.Name.IndexOf("lobal", StringComparison.OrdinalIgnoreCase) < 0) continue;
                var en = f.GetValue(null) as System.Collections.IEnumerable;
                if (en == null) continue;
                foreach (var gl in en)
                {
                    if (gl == null) continue;
                    var lp = gl.GetType().GetProperty("Layer");
                    var layer = lp == null ? null : lp.GetValue(gl, null) as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                    if (layer == null || layer.Name != layerName || layer.UIContext == null || layer.UIContext.Root == null) continue;
                    if (id == null) return layer.UIContext.Root.ChildCount > 0 ? layer.UIContext.Root.GetChild(0) : null;
                    TaleWorlds.GauntletUI.BaseTypes.Widget hit = null;
                    UiText.Walk(layer.UIContext.Root, x => { if (hit == null && x.Id == id) hit = x; });
                    if (hit != null) return hit;
                }
            }
            return null;
        }
    }

    // ------------------------------------------------------------------ the balance of power (board: Encounter.dc.html, top bar)
    // While the player faces a hostile party on the map (its conversation or the encounter menu): both armies, the balance of
    // their strength by the game's own estimate, and a rough chance to win. H hides it and shows it again.
    public class UiEncounter : GlobalLayer
    {
        static UiEncounter open; static int errors; static bool hidden; static DateTime next = DateTime.MinValue;
        GauntletLayer layer; object movie; EncounterVM vm;

        public static void Tick()
        {
            try
            {
                try { if (TaleWorlds.InputSystem.Input.IsKeyPressed(TaleWorlds.InputSystem.InputKey.H) && open != null) hidden = !hidden; } catch { }
                if (DateTime.UtcNow < next && open == null) return;
                next = DateTime.UtcNow.AddSeconds(0.25);
                TaleWorlds.CampaignSystem.Party.PartyBase me, them;
                bool want = Find(out me, out them) && !hidden;
                if (!want) { if (open != null) Close(); if (me == null) hidden = false; return; }
                if (open == null)
                {
                    if (errors >= 3 || !AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png")) return;
                    var s = new UiEncounter(); s.vm = new EncounterVM();
                    s.layer = new GauntletLayer("AurelionEncounter", 3500, false);
                    s.movie = s.layer.LoadMovie("AurEncounterBar", s.vm);
                    s.Layer = s.layer;
                    ScreenManager.AddGlobalLayer(s, false);
                    open = s;
                }
                open.vm.Fill(me, them);
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiEncounter: " + (e.InnerException ?? e).Message); Close(); }
        }

        static bool Find(out TaleWorlds.CampaignSystem.Party.PartyBase me, out TaleWorlds.CampaignSystem.Party.PartyBase them)
        {
            me = null; them = null;
            if (TaleWorlds.CampaignSystem.Campaign.Current == null || !TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.IsActive) return false;
            var top = ScreenManager.TopScreen;
            if (top == null || top.GetType().Name != "MapScreen") return false;   // never over a battle or another screen
            // never over the conversation or the barter of the encounter: the game shows both sides there itself
            try { var cm = TaleWorlds.CampaignSystem.Campaign.Current.ConversationManager; if (cm != null && cm.IsConversationInProgress) return false; } catch { }
            var mp = TaleWorlds.CampaignSystem.Party.MobileParty.MainParty;
            them = TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.EncounteredParty;
            if (mp == null || them == null || them == mp.Party || !them.IsMobile) return false;
            me = mp.Party;
            if (them.NumberOfHealthyMembers <= 0) return false;
            return TaleWorlds.CampaignSystem.FactionManager.IsAtWarAgainstFaction(them.MapFaction, mp.MapFaction);
        }

        static void Close()
        {
            var s = open; open = null; if (s == null || s.layer == null) return;
            try { if (s.movie != null) s.layer.ReleaseMovie((GauntletMovieIdentifier)s.movie); } catch { }
            try { AurLayers.Remove(s); } catch (Exception e) { Log.W("UiEncounter close: " + e.Message); }
        }
    }

