        // one side of the fight: every party in it (the whole battle when it has started, an army when it is one)
        class Side
        {
            public int Men, Inf, Arc, Cav, Her, Wnd, Parties; public float Str, Mor; public int[] Tier = new int[7]; int mn;
            public void Add(TaleWorlds.CampaignSystem.Party.PartyBase p)
            {
                if (p == null) return;
                Parties++;
                try { Str += p.EstimatedStrength; } catch { }
                try
                {
                    var r = p.MemberRoster;
                    for (int i = 0; i < r.Count; i++)
                    {
                        var e = r.GetElementCopyAtIndex(i); var ch = e.Character; if (ch == null) continue;
                        int ok = e.Number - e.WoundedNumber; if (ok < 0) ok = 0; Wnd += e.WoundedNumber; Men += ok;
                        if (ch.IsHero) Her += ok; else if (ch.IsMounted) Cav += ok; else if (ch.IsRanged) Arc += ok; else Inf += ok;
                        int t = 1; try { t = ch.Tier; } catch { }
                        if (t < 1) t = 1; if (t > 6) t = 6; Tier[t] += ok;
                    }
                }
                catch { }
                try { if (p.MobileParty != null) { Mor += p.MobileParty.Morale; mn++; } } catch { }
            }
            public int Morale { get { return mn > 0 ? (int)Math.Round(Mor / mn) : 0; } }
            public void SetMn(Side f) { mn = f.mn; }
        }

        static void Collect(TaleWorlds.CampaignSystem.Party.PartyBase me, TaleWorlds.CampaignSystem.Party.PartyBase them, Side a, Side b)
        {
            // the battle (when the encounter has one): every party on each side, the ones that joined later included
            try
            {
                var ev = TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.Battle ?? TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.EncounteredBattle;
                if (ev != null && (ev.PlayerSide == TaleWorlds.Core.BattleSideEnum.Attacker || ev.PlayerSide == TaleWorlds.Core.BattleSideEnum.Defender))
                {
                    var ps = ev.PlayerSide; var os = ps == TaleWorlds.Core.BattleSideEnum.Attacker ? TaleWorlds.Core.BattleSideEnum.Defender : TaleWorlds.Core.BattleSideEnum.Attacker;
                    foreach (var x in ev.PartiesOnSide(ps)) if (x != null) a.Add(x.Party);
                    foreach (var x in ev.PartiesOnSide(os)) if (x != null) b.Add(x.Party);
                    if (a.Parties > 0 && b.Parties > 0) return;
                }
            }
            catch { }
            a.Parties = 0; b.Parties = 0;
            var na = new Side(); var nb = new Side();
            AddParty(me, na); AddParty(them, nb);
            Copy(na, a); Copy(nb, b);
        }
        static void Copy(Side f, Side t) { t.Men = f.Men; t.Inf = f.Inf; t.Arc = f.Arc; t.Cav = f.Cav; t.Her = f.Her; t.Wnd = f.Wnd; t.Parties = f.Parties; t.Str = f.Str; t.Mor = f.Mor; t.Tier = f.Tier; t.SetMn(f); }
        static void AddParty(TaleWorlds.CampaignSystem.Party.PartyBase p, Side s)
        {
            try
            {
                var mp = p.MobileParty; var army = mp == null ? null : mp.Army;
                if (army != null && army.LeaderParty == mp) { foreach (var x in army.Parties) if (x != null) s.Add(x.Party); return; }
            }
            catch { }
            s.Add(p);
        }

        static string N(int v) { return v.ToString(); }
        static void Pair(float a, float b, out float wa, out float wb) { float t = a + b; if (t <= 0) { wa = 0; wb = 0; return; } wa = 300f * a / t; wb = 300f * b / t; }

        public void Fill(TaleWorlds.CampaignSystem.Party.PartyBase me, TaleWorlds.CampaignSystem.Party.PartyBase them)
        {
            var a = new Side(); var b = new Side();
            Collect(me, them, a, b);
            float sm = Math.Max(0.1f, a.Str), st = Math.Max(0.1f, b.Str);
            Mine = N(a.Men); Theirs = N(b.Men);
            Head = UiText.L("BALANCE OF POWER  \u00b7  H hides it", "\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u0642\u0648\u0629  \u00b7  H \u064a\u062e\u0641\u064a\u0647");
            MineL = UiText.L("Your side", "\u062c\u064a\u0634\u0643") + (a.Parties > 1 ? "  +" + (a.Parties - 1) : "");
            var nm = them.Name == null ? "" : them.Name.ToString();
            if (nm.Length > 22) nm = nm.Substring(0, 22) + "\u2026";
            TheirsL = nm + (b.Parties > 1 ? "  +" + (b.Parties - 1) : "");
            float share = sm / (sm + st);
            MeW = 380f * share; ThemW = 380f * (1 - share);
            float w1, w2;
            string[] lab = { UiText.L("Strength", "\u0627\u0644\u0642\u0648\u0629"), UiText.L("Morale", "\u0627\u0644\u0645\u0639\u0646\u0648\u064a\u0627\u062a"), UiText.L("Infantry", "\u0627\u0644\u0645\u0634\u0627\u0629"), UiText.L("Archers", "\u0627\u0644\u0631\u0645\u0627\u0629"), UiText.L("Cavalry", "\u0627\u0644\u062e\u064a\u0651\u0627\u0644\u0629") };
            float[] va = { sm, a.Morale, a.Inf, a.Arc, a.Cav }, vb = { st, b.Morale, b.Inf, b.Arc, b.Cav };
            L0 = lab[0]; L1 = lab[1]; L2 = lab[2]; L3 = lab[3]; L4 = lab[4];
            V0M = N((int)Math.Round(sm)); V0T = N((int)Math.Round(st)); V1M = N(a.Morale); V1T = N(b.Morale); V2M = N(a.Inf); V2T = N(b.Inf); V3M = N(a.Arc); V3T = N(b.Arc); V4M = N(a.Cav); V4T = N(b.Cav);
            Pair(va[0], vb[0], out w1, out w2); R0M = w1; R0T = w2;
            Pair(va[1], vb[1], out w1, out w2); R1M = w1; R1T = w2;
            Pair(va[2], vb[2], out w1, out w2); R2M = w1; R2T = w2;
            Pair(va[3], vb[3], out w1, out w2); R3M = w1; R3T = w2;
            Pair(va[4], vb[4], out w1, out w2); R4M = w1; R4T = w2;
            // ranks 1..6: bar height from the biggest rank on either side (40 px)
            int top = 1; for (int k = 1; k <= 6; k++) top = Math.Max(top, Math.Max(a.Tier[k], b.Tier[k]));
            Func<int, float> H = v => v <= 0 ? 0f : Math.Max(3f, 40f * v / top);
            T1M = H(a.Tier[1]); T2M = H(a.Tier[2]); T3M = H(a.Tier[3]); T4M = H(a.Tier[4]); T5M = H(a.Tier[5]); T6M = H(a.Tier[6]);
            T1T = H(b.Tier[1]); T2T = H(b.Tier[2]); T3T = H(b.Tier[3]); T4T = H(b.Tier[4]); T5T = H(b.Tier[5]); T6T = H(b.Tier[6]);
            TierLM = UiText.L("Your men by rank", "\u062c\u0646\u0648\u062f\u0643 \u062d\u0633\u0628 \u0627\u0644\u0631\u062a\u0628\u0629");
            TierLT = UiText.L("Theirs by rank", "\u062c\u0646\u0648\u062f\u0647\u0645 \u062d\u0633\u0628 \u0627\u0644\u0631\u062a\u0628\u0629");
            ExtraM = UiText.L("Heroes " + a.Her + " \u00b7 Wounded " + a.Wnd, "\u0623\u0628\u0637\u0627\u0644 " + a.Her + " \u00b7 \u062c\u0631\u062d\u0649 " + a.Wnd);
            ExtraT = UiText.L("Heroes " + b.Her + " \u00b7 Wounded " + b.Wnd, "\u0623\u0628\u0637\u0627\u0644 " + b.Her + " \u00b7 \u062c\u0631\u062d\u0649 " + b.Wnd);
            double pa = Math.Pow(sm, 1.5), pb = Math.Pow(st, 1.5);
            int win = (int)Math.Round(100.0 * pa / (pa + pb));
            Win = win + "%"; WinL = UiText.L("chance to win", "\u0641\u0631\u0635\u0629 \u0627\u0644\u0641\u0648\u0632");
        }
    }

    // ------------------------------------------------------------------ motion that follows the screen, not the game
    // While a loading screen is up the game's own tick can stop for seconds, but the interface is still drawn every frame.
    // This widget sits invisible inside our screens and moves its neighbours (by Id) from the interface's own update,
    // so the motion stays smooth whatever the game is doing. Mode: "load" (loading screen), "wait" (the choice being read
    // at start-up), "chooser" (the character choice).
    public class AurMotionWidget : Widget
    {
        public AurMotionWidget(UIContext context) : base(context) { }

        string mode = "load";
        public string Mode { get { return mode; } set { mode = value ?? "load"; } }

        Dictionary<string, Widget> ids; Widget scope; float since; int errors;

        protected override void OnLateUpdate(float dt)
        {
            base.OnLateUpdate(dt);
            try
            {
                var root = ParentWidget;
                if (root == null) return;
                if (ids == null || scope != root) { scope = root; ids = UiLoading.Index(root); since = UiLoading.Begin(ids, mode); }
                since += dt < 0 ? 0 : (dt > 0.1f ? 0.1f : dt);
                UiLoading.Animate(ids, mode, since, dt);
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiMotion " + mode + ": " + e.Message); }
        }
    }

    public static class UiMotion
    {
        // one clock for every Aurelion scene, so the background and the embers carry on across screens
        public static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
        public static float Now { get { return (float)Clock.Elapsed.TotalSeconds; } }

        static int state;   // 0 unknown, 1 ready, -1 not available
        // true when the interface knows AurMotionWidget; our screens then carry it. Otherwise the plain variants load
        // ("...Lite") and the game's tick drives what it can.
        public static bool Ready
        {
            get
            {
                if (state == 0) state = Register() ? 1 : -1;
                return state == 1;
            }
        }
        public static string Movie(string name) { return Ready ? name : name + "Lite"; }

        static bool Register()
        {
            try
            {
                var t = typeof(AurMotionWidget);
                // the widget list the interface collected at start-up
                var infos = typeof(WidgetInfo).GetField("_widgetInfos", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
                var dict = infos == null ? null : infos.GetValue(null) as System.Collections.IDictionary;
                if (dict != null && !dict.Contains(t)) { dict[t] = new WidgetInfo(t); Log.W("UiMotion: widget info added"); }
                var uiRes = typeof(UIResourceManager);
                var fp = uiRes == null ? null : uiRes.GetProperty("WidgetFactory", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static);
                var factory = fp == null ? null : fp.GetValue(null, null);
                if (factory == null) { Log.W("UiMotion: widget factory not found, screens use the plain motion"); return false; }
                var isB = factory.GetType().GetMethod("IsBuiltinType", new[] { typeof(string) });
                if (isB != null && (bool)isB.Invoke(factory, new object[] { t.Name })) { Log.W("UiMotion: ready"); return true; }
                var bf = factory.GetType().GetField("_builtinTypes", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                var bt = bf == null ? null : bf.GetValue(factory) as System.Collections.IDictionary;
                if (bt == null) { Log.W("UiMotion: widget list not found, screens use the plain motion"); return false; }
                bt[t.Name] = t;
                var ok = isB == null || (bool)isB.Invoke(factory, new object[] { t.Name });
                Log.W(ok ? "UiMotion: ready (registered)" : "UiMotion: registration did not hold, screens use the plain motion");
                return ok;
            }
            catch (Exception e) { Log.W("UiMotion: " + (e.InnerException ?? e).Message + " - screens use the plain motion"); return false; }
        }
    }

    // the current quest as a small card at the top left of the map (the game only shows it in the journal)
    public class UiQuest : GlobalLayer
    {
        static UiQuest open; static int errors; static DateTime next = DateTime.MinValue;
        GauntletLayer layer; object movie; QuestCardVM vm;

        public static void Tick()
        {
            try
            {
                if (DateTime.UtcNow < next) return;
                next = DateTime.UtcNow.AddSeconds(0.5);
                TaleWorlds.CampaignSystem.QuestBase q = Pick();
                if (q == null) { if (open != null) Close(); return; }
                if (open == null)
                {
                    if (errors >= 3 || !AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png")) return;
                    var s = new UiQuest(); s.vm = new QuestCardVM();
                    s.layer = new GauntletLayer("AurelionQuest", 3400, false);
                    s.movie = s.layer.LoadMovie("AurQuestCard", s.vm);
                    s.Layer = s.layer;
                    ScreenManager.AddGlobalLayer(s, false);
                    open = s;
                }
                open.vm.Fill(q);
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiQuest: " + (e.InnerException ?? e).Message); Close(); }
        }

        // only on the bare map: never over a menu, an encounter or another screen
        static TaleWorlds.CampaignSystem.QuestBase Pick()
        {
            var c = TaleWorlds.CampaignSystem.Campaign.Current;
            if (c == null || c.QuestManager == null) return null;
            var top = ScreenManager.TopScreen;
            if (top == null || top.GetType().Name != "MapScreen") return null;
            if (c.CurrentMenuContext != null || TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.IsActive) return null;
            TaleWorlds.CampaignSystem.QuestBase best = null; float bestT = float.MinValue; bool bestTracked = false;
            foreach (var q in c.QuestManager.Quests)
            {
                if (q == null || !q.IsOngoing) continue;
                float t = 0f;
                try { var j = q.JournalEntries; if (j != null && j.Count > 0) t = (float)j[j.Count - 1].LogTime.ToHours; } catch { }
                bool tr = q.IsTrackEnabled;
                if (best == null || (tr && !bestTracked) || (tr == bestTracked && t > bestT)) { best = q; bestT = t; bestTracked = tr; }
            }
            return best;
        }

        static void Close()
        {
            var s = open; open = null; if (s == null || s.layer == null) return;
            try { if (s.movie != null) s.layer.ReleaseMovie((GauntletMovieIdentifier)s.movie); } catch { }
            try { AurLayers.Remove(s); } catch (Exception e) { Log.W("UiQuest close: " + e.Message); }
        }
    }

