            if (st.StringId == mKey && (DateTime.UtcNow - mAt).TotalSeconds < 5) return mText;
            var near = new List<TaleWorlds.CampaignSystem.Settlements.Town>();
            foreach (var t in TaleWorlds.CampaignSystem.Settlements.Town.AllTowns)
                if (t != null && t != town && t.IsTown && t.Settlement != null && t.MarketData != null) near.Add(t);
            near.Sort((x, y) => st.Position.Distance(x.Settlement.Position).CompareTo(st.Position.Distance(y.Settlement.Position)));
            if (near.Count > 3) near.RemoveRange(3, near.Count - 3);
