            var cats = new[] { TaleWorlds.Core.DefaultItemCategories.Grain, TaleWorlds.Core.DefaultItemCategories.Meat, TaleWorlds.Core.DefaultItemCategories.Wool, TaleWorlds.Core.DefaultItemCategories.Iron, TaleWorlds.Core.DefaultItemCategories.Salt, TaleWorlds.Core.DefaultItemCategories.Wine, TaleWorlds.Core.DefaultItemCategories.Oil, TaleWorlds.Core.DefaultItemCategories.Linen, TaleWorlds.Core.DefaultItemCategories.Horse };
            var en = new[] { "Grain", "Meat", "Wool", "Iron", "Salt", "Wine", "Oil", "Linen", "Horses" };
            var ar = new[] { "\u0627\u0644\u0642\u0645\u062d", "\u0627\u0644\u0644\u062d\u0645\u0629", "\u0627\u0644\u0635\u0648\u0641", "\u0627\u0644\u062d\u062f\u064a\u062f", "\u0627\u0644\u0645\u0644\u062d", "\u0627\u0644\u0646\u0628\u064a\u0630", "\u0627\u0644\u0632\u064a\u062a", "\u0627\u0644\u0643\u062a\u0627\u0646", "\u0627\u0644\u062e\u064a\u0644" };
            int lo = -1, hi = -1; float rlo = 0f, rhi = 0f;
            for (int k = 0; k < cats.Length; k++)
            {
                if (cats[k] == null) continue;
                float here = town.MarketData.GetPriceFactor(cats[k]), sum = 0f;
                foreach (var t in near) sum += t.MarketData.GetPriceFactor(cats[k]);
                float avg = sum / near.Count; if (avg <= 0.001f || here <= 0.001f) continue;
                float r = here / avg - 1f;
                if (r < rlo) { rlo = r; lo = k; }
                if (r > rhi) { rhi = r; hi = k; }
            }
            var parts = new List<string>();
            if (lo >= 0 && rlo <= -0.04f) parts.Add(UiText.L(en[lo] + " " + (int)Math.Round(-rlo * 100) + "% cheaper here", ar[lo] + " \u0647\u0646\u0627 \u0623\u0631\u062e\u0635 " + (int)Math.Round(-rlo * 100) + "%"));
            if (hi >= 0 && rhi >= 0.04f) parts.Add(UiText.L(en[hi] + " " + (int)Math.Round(rhi * 100) + "% dearer here", ar[hi] + " \u0647\u0646\u0627 \u0623\u063a\u0644\u0649 " + (int)Math.Round(rhi * 100) + "%"));
            mText = parts.Count == 0 ? UiText.L("Prices here are close to the nearest towns", "\u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0647\u0646\u0627 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0623\u0642\u0631\u0628 \u0627\u0644\u0645\u062f\u0646")
                : UiText.L("Against the 3 nearest towns: ", "\u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0623\u0642\u0631\u0628 3 \u0645\u062f\u0646: ") + string.Join("  \u00b7  ", parts.ToArray());
            mKey = st.StringId; mAt = DateTime.UtcNow;
            return mText;
        }

