    // ------------------------------------------------------------------ the banner board (Banner.dc.html) on the game's banner editor
    // The game's editor stays (its emblem list, colours, size, the shield and the character); our buttons in BannerEditor.xml add
    // what it does not have: emblems by kind, arrangements of several emblems, moving/turning/mirroring, the background pattern,
    // three saved banners, the banner code, undo/redo, and whether a clan of this world already carries the same banner.
    // Every change rebuilds the banner from its code (Banner.Deserialize keeps the same object, so the game's screen, the shield
    // and character creation all see it) and asks the game's view to redraw the flag and the shield next frame.
    public static class UiBanner
    {
        static object view; static Widget root; static Dictionary<string, Widget> ids = new Dictionary<string, Widget>(StringComparer.Ordinal);
        static readonly HashSet<Widget> hooked = new HashSet<Widget>();
        static Widget grid; static int cat, gridCount = -1, preset, slot = -1, errors; static bool linked;
        static string lastCode, openCode, status = ""; static float ratio = 1f;
        static readonly List<string> undo = new List<string>(), redo = new List<string>();
        static string[] slots;
        static DateTime next = DateTime.MinValue;
        static bool Ar { get { return UiText.Arabic; } }
        static string L(string en, string ar) { return UiText.L(en, ar); }

        static object Fld(object o, string name)
        {
            for (var t = o == null ? null : o.GetType(); t != null; t = t.BaseType)
            { var f = t.GetField(name, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic); if (f != null) return f.GetValue(o); }
            return null;
        }
        static void SetFld(object o, string name, object v)
        {
            for (var t = o == null ? null : o.GetType(); t != null; t = t.BaseType)
            { var f = t.GetField(name, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic); if (f != null) { f.SetValue(o, v); return; } }
        }
        static object Prop(object o, string name)
        {
            if (o == null) return null;
            var p = o.GetType().GetProperty(name, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
            return p == null ? null : p.GetValue(o, null);
        }

        // the game's BannerEditorView: inside character creation, or the clan screen's banner editor
        static object FindView()
        {
            var top = ScreenManager.TopScreen;
            if (top == null) return null;
            var tn = top.GetType().Name;
            if (tn.IndexOf("CharacterCreation", StringComparison.Ordinal) >= 0)
            {
                var stage = Fld(top, "_currentStageView");
                return stage == null ? null : Fld(stage, "_bannerEditorView");
            }
            if (tn == "GauntletBannerEditorScreen") return Fld(top, "_bannerEditorLayer");
            return null;
        }

        public static void Tick()
        {
            try
            {
                if (DateTime.UtcNow < next) return;
                next = DateTime.UtcNow.AddMilliseconds(90);
                var v = FindView();
                var layer = v == null ? null : Prop(v, "GauntletLayer") as GauntletLayer;
                var r = layer == null || layer.UIContext == null ? null : layer.UIContext.Root;
                var b = Banner(v);
                if (r == null || b == null) { if (view != null) Reset(); return; }
                if (!ReferenceEquals(v, view)) { Reset(); view = v; openCode = b.Serialize(); lastCode = openCode; LoadSlots(); }
                if (!ReferenceEquals(r, root) || !ids.ContainsKey("AurBnLeft")) Build(r);
                if (!ids.ContainsKey("AurBnLeft")) return;   // not our file (another mod's editor): nothing to do

                var code = b.Serialize();
                if (code != lastCode)
                {
                    // the game's own controls changed the emblem, a colour or the size: remember for undo, and keep our extra emblems with it
                    if (lastCode != null) { Push(undo, lastCode); redo.Clear(); }
                    if (linked && Follow(lastCode, code)) code = b.Serialize();
                    lastCode = code; Check();
                }
                var vm = Prop(v, "DataSource") as TaleWorlds.CampaignSystem.ViewModelCollection.BannerEditorVM;
                if (vm != null && !ReferenceEquals(paletteFor, vm)) { paletteFor = vm; FullPalette(vm); }
                if (grid != null && vm != null && vm.IconsList != null && gridCount != vm.IconsList.Count) { gridCount = vm.IconsList.Count; Filter(vm); }
                Show();
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiBanner: " + e.Message); }
        }

        // every colour of the game in both colour grids (character creation offers only the culture's few), ordered by shade;
        // the new swatches use the editor's own selection handlers, so picking one works exactly like the game's
        static object paletteFor;
        static void FullPalette(TaleWorlds.CampaignSystem.ViewModelCollection.BannerEditorVM vm)
        {
            try
            {
                if (vm.PrimaryColorList == null || vm.SigilColorList == null || vm.PrimaryColorList.Count == 0 || vm.SigilColorList.Count == 0) return;
                var a1 = Fld(vm.PrimaryColorList[0], "_onSelection") as Action<TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM>;
                var a2 = Fld(vm.SigilColorList[0], "_onSelection") as Action<TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM>;
                if (a1 == null || a2 == null) return;
                var all = new List<KeyValuePair<int, uint>>();
                // the palette is not public in this game version: read it by name
                var pp = typeof(TaleWorlds.Core.BannerManager).GetProperty("ColorPalette", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
                var dict = pp == null ? null : pp.GetValue(null, null) as System.Collections.IEnumerable;
                if (dict == null) return;
                foreach (var o in dict)
                {
                    try
                    {
                        var key = (int)o.GetType().GetProperty("Key").GetValue(o, null);
                        var val = o.GetType().GetProperty("Value").GetValue(o, null);
                        var col = (uint)val.GetType().GetProperty("Color").GetValue(val, null);
                        all.Add(new KeyValuePair<int, uint>(key, col));
                    }
                    catch { }
                }
                all.Sort((x, y) => Shade(x.Value).CompareTo(Shade(y.Value)));
                Fill(vm.PrimaryColorList, all, a1);
                Fill(vm.SigilColorList, all, a2);
            }
            catch (Exception e) { if (++errors <= 6) Log.W("UiBanner palette: " + e.Message); }
        }
        static void Fill(TaleWorlds.Library.MBBindingList<TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM> list, List<KeyValuePair<int, uint>> all, Action<TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM> act)
        {
            var have = new HashSet<int>(); foreach (var c in list) have.Add(c.ColorID);
            var keep = new List<TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM>(list);
            foreach (var kv in all) if (!have.Contains(kv.Key)) keep.Add(new TaleWorlds.Core.ViewModelCollection.BannerEditor.BannerColorVM(kv.Key, kv.Value, act));
            keep.Sort((x, y) => Shade(x.Color).CompareTo(Shade(y.Color)));
            list.Clear(); foreach (var c in keep) list.Add(c);
        }
        // greys first (dark to light), then the colours around the wheel, dark to light inside each step of hue
        static double Shade(uint c)
        {
            double r = ((c >> 16) & 255) / 255.0, g = ((c >> 8) & 255) / 255.0, b = (c & 255) / 255.0;
            double mx = Math.Max(r, Math.Max(g, b)), mn = Math.Min(r, Math.Min(g, b)), d = mx - mn, h = 0;
            if (d < 0.08) return mx;   // grey
            if (mx == r) h = ((g - b) / d) % 6; else if (mx == g) h = (b - r) / d + 2; else h = (r - g) / d + 4;
            h = (h * 60 + 360) % 360;
            return 1 + Math.Floor(h / 15) + mx * 0.9;
        }

        static TaleWorlds.Core.Banner Banner(object v) { return v == null ? null : Prop(v, "Banner") as TaleWorlds.Core.Banner; }

        static void Reset()
        {
            view = null; root = null; ids.Clear(); hooked.Clear(); grid = null; cat = 0; gridCount = -1; preset = 0; slot = -1;
            linked = false; lastCode = null; openCode = null; undo.Clear(); redo.Clear(); status = "";
        }

        static void Build(Widget r)
        {
            root = r; ids.Clear(); grid = null;
            UiText.Walk(r, w =>
            {
                if (string.IsNullOrEmpty(w.Id)) return;
                if (w.Id == "IconsGrid") grid = w;
                if (w.Id.StartsWith("AurBn", StringComparison.Ordinal) && !ids.ContainsKey(w.Id)) ids[w.Id] = w;
            });
            foreach (var kv in ids)
            {
                var bw = kv.Value as ButtonWidget;
                if (bw == null || !kv.Key.StartsWith("AurBnB_", StringComparison.Ordinal) || hooked.Contains(bw)) continue;
                var act = kv.Key.Substring(7);
                bw.ClickEventHandlers.Add(w => { try { Do(act); } catch (Exception e) { if (++errors <= 6) Log.W("UiBanner " + act + ": " + e.Message); } });
                hooked.Add(bw);
            }
            gridCount = -1; Texts(); Check();
        }

