        // ---- emblems by kind: icon ids 1xx animals, 2xx plants, 3xx crafted, 4xx signs, 5xx shapes (Native banner_icons.xml)
        static int Kind(int id) { int k = id / 100; return k >= 1 && k <= 5 ? k : 0; }
        static void Filter(TaleWorlds.CampaignSystem.ViewModelCollection.BannerEditorVM vm)
        {
            var n = new int[6];
            for (int i = 0; i < vm.IconsList.Count; i++) { n[0]++; n[Kind(vm.IconsList[i].IconID)]++; }
            for (int c = 0; c < 6; c++) T("Cat" + c, (Ar ? Cats[c][1] : Cats[c][0]) + "\n" + n[c]);
            int shown = 0;
            for (int i = 0; i < grid.ChildCount && i < vm.IconsList.Count; i++)
            {
                bool on = cat == 0 || Kind(vm.IconsList[i].IconID) == cat;
                var w = grid.GetChild(i); if (w.IsVisible != on) w.IsVisible = on;
                if (on) shown++;
            }
            T("Count", Ar ? shown + " شعار" + (cat == 0 ? "" : " في " + Cats[cat][1]) : shown + " emblems" + (cat == 0 ? "" : " in " + Cats[cat][0].ToLowerInvariant()));
        }

        // ---- the banner as numbers: layer = mesh, colour, colour 2, size x, size y, x, y, stroke, mirror, degrees
        static List<int[]> Parse(string code)
        {
            var list = new List<int[]>();
            if (string.IsNullOrEmpty(code)) return list;
            var p = code.Split('.');
            for (int i = 0; i + 9 < p.Length; i += 10)
            {
                var a = new int[10];
                for (int k = 0; k < 10; k++) { int x; if (!int.TryParse(p[i + k], System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out x)) return new List<int[]>(); a[k] = x; }
                list.Add(a);
            }
            return list;
        }
        static string Code(List<int[]> list)
        {
            var sb = new System.Text.StringBuilder();
            foreach (var a in list)
                for (int k = 0; k < 10; k++) { if (sb.Length > 0) sb.Append('.'); sb.Append(a[k].ToString(System.Globalization.CultureInfo.InvariantCulture)); }
            return sb.ToString();
        }
        static int[] Copy(int[] a) { return (int[])a.Clone(); }
        static int Clamp(int v, int lo, int hi) { return v < lo ? lo : v > hi ? hi : v; }

        // put a code on the banner the game is editing; the flag, the shield and the game's lists follow
        static void Apply(string code, bool remember)
        {
            var b = Banner(view);
            if (b == null || string.IsNullOrEmpty(code) || !TaleWorlds.Core.Banner.IsValidBannerCode(code)) return;
            var cur = b.Serialize();
            if (code == cur) return;
            if (remember) { Push(undo, cur); redo.Clear(); }
            b.Deserialize(code);
            var vm = Prop(view, "DataSource") as TaleWorlds.CampaignSystem.ViewModelCollection.BannerEditorVM;
            if (vm != null)
            {
                try
                {
                    var sz = (int)b.GetIconSize().x;
                    if (sz >= vm.MinIconSize && sz <= vm.MaxIconSize && vm.CurrentIconSize != sz) vm.CurrentIconSize = sz;   // the slider follows (same size, nothing changes)
                }
                catch { }
                try
                {
                    int icon = b.GetIconMeshId(), c1 = b.GetPrimaryColorId(), c2 = b.GetIconColorId();
                    foreach (var i in vm.IconsList) { bool s = i.IconID == icon; if (i.IsSelected != s) i.IsSelected = s; }
                    foreach (var c in vm.PrimaryColorList) { bool s = c.ColorID == c1; if (c.IsSelected != s) c.IsSelected = s; }
                    foreach (var c in vm.SigilColorList) { bool s = c.ColorID == c2; if (c.IsSelected != s) c.IsSelected = s; }
                }
                catch { }
                try { if (vm.BannerVM != null) vm.BannerVM.BannerCode = b.Serialize(); } catch { }
            }
            SetFld(view, "_refreshBannersNextFrame", true);
            SetFld(view, "_refreshCharacterAndShieldNextFrame", true);
            lastCode = b.Serialize(); Check();
        }
        static void Push(List<string> st, string code) { if (st.Count > 0 && st[st.Count - 1] == code) return; st.Add(code); if (st.Count > 40) st.RemoveAt(0); }

        // the game changed the main emblem (its picture, colour or size): the repeated emblems take the same change
        static bool Follow(string before, string after)
        {
            var a = Parse(before); var b = Parse(after);
            if (a.Count < 3 || b.Count != a.Count) return false;
            var m0 = a[1]; var m1 = b[1];
            if (m0[0] == m1[0] && m0[1] == m1[1] && m0[2] == m1[2] && m0[3] == m1[3]) return false;
            float k = m0[3] > 0 ? (float)m1[3] / m0[3] : 1f;
            for (int i = 2; i < b.Count; i++)
            {
                b[i][0] = m1[0]; b[i][1] = m1[1]; b[i][2] = m1[2];
                b[i][3] = Clamp((int)Math.Round(b[i][3] * k), 40, 1400); b[i][4] = Clamp((int)Math.Round(b[i][4] * k), 40, 1400);
            }
            var bn = Banner(view); if (bn == null) return false;
            bn.Deserialize(Code(b));
            SetFld(view, "_refreshBannersNextFrame", true); SetFld(view, "_refreshCharacterAndShieldNextFrame", true);
            return true;
        }

        static void Do(string act)
        {
            var b = Banner(view); if (b == null) return;
            var L0 = Parse(b.Serialize()); if (L0.Count < 2) return;
            var bg = L0[0]; var main = L0[1];
            if (act.StartsWith("Cat", StringComparison.Ordinal))
            {
                int c; if (int.TryParse(act.Substring(3), out c)) cat = Clamp(c, 0, 5);
                var vm = Prop(view, "DataSource") as TaleWorlds.CampaignSystem.ViewModelCollection.BannerEditorVM;
                if (vm != null && grid != null) Filter(vm);
                return;
            }
            if (act.StartsWith("Lay", StringComparison.Ordinal))
            {
                int p; if (!int.TryParse(act.Substring(3), out p)) return;
                Apply(Code(Arrange(bg, main, p)), true); preset = p; linked = p != 1 && p != 5; return;
            }
            if (act.StartsWith("Slot", StringComparison.Ordinal))
            {
                int s; if (!int.TryParse(act.Substring(4), out s)) return;
                slot = Clamp(s - 1, 0, 2);
                if (!string.IsNullOrEmpty(slots[slot])) { Apply(slots[slot], true); linked = false; preset = 0; }
                return;
            }
            switch (act)
            {
                case "Up": Shift(L0, 0, -40); break;
                case "Down": Shift(L0, 0, 40); break;
                case "Left": Shift(L0, -40, 0); break;
                case "Right": Shift(L0, 40, 0); break;
                case "Center": Shift(L0, 764 - main[5], 764 - main[6]); break;
                case "RotL": Turn(L0, -15); break;
                case "RotR": Turn(L0, 15); break;
                case "Flip": for (int i = 1; i < L0.Count; i++) L0[i][8] = L0[i][8] == 0 ? 1 : 0; Apply(Code(L0), true); break;
                case "PatPrev": case "PatNext":
                {
                    int m = bg[0] < 1 || bg[0] > 36 ? 1 : bg[0];
                    m = act == "PatNext" ? (m % 36) + 1 : ((m + 34) % 36) + 1;
                    bg[0] = m;
                    if (bg[2] == bg[1]) bg[2] = main[1] != bg[1] ? main[1] : bg[1];   // a pattern needs a second colour: the emblem's
                    Apply(Code(L0), true); break;
                }
                case "Save":
                    if (slot < 0) slot = Array.FindIndex(slots, x => string.IsNullOrEmpty(x)); if (slot < 0) slot = 0;
                    slots[slot] = b.Serialize(); SaveSlots(); break;
                case "Forget": if (slot >= 0) { slots[slot] = null; SaveSlots(); } break;
                case "Copy": status = Clip(b.Serialize()) ? L("Code copied", "اتنسخ الكود") : L("Copy is not available here", "النسخ مش متاح هنا"); stamp = DateTime.UtcNow; break;
                case "Paste":
                {
                    var t = (Clip() ?? "").Trim();
                    if (TaleWorlds.Core.Banner.IsValidBannerCode(t) && Parse(t).Count >= 2 && Parse(t).Count <= 9) { Apply(t, true); linked = false; preset = 0; }
                    else { status = L("No banner code on the clipboard", "مفيش كود راية منسوخ"); stamp = DateTime.UtcNow; }
                    break;
                }
                case "Undo": if (undo.Count > 0) { var c = undo[undo.Count - 1]; undo.RemoveAt(undo.Count - 1); Push(redo, b.Serialize()); Apply(c, false); } break;
                case "Redo": if (redo.Count > 0) { var c = redo[redo.Count - 1]; redo.RemoveAt(redo.Count - 1); Push(undo, b.Serialize()); Apply(c, false); } break;
                case "Random": Apply(TaleWorlds.Core.Banner.CreateRandomClanBanner(new Random().Next()).Serialize(), true); linked = false; preset = 0; break;
                case "Reset": Apply(openCode, true); linked = false; preset = 0; break;
            }
        }

        static void Shift(List<int[]> L0, int dx, int dy)
        {
            for (int i = 1; i < L0.Count; i++) { L0[i][5] = Clamp(L0[i][5] + dx, 0, 1528); L0[i][6] = Clamp(L0[i][6] + dy, 0, 1528); }
            Apply(Code(L0), true);
        }
        static void Turn(List<int[]> L0, int deg)
        {
            for (int i = 1; i < L0.Count; i++) L0[i][9] = ((L0[i][9] + deg) % 360 + 360) % 360;
            Apply(Code(L0), true);
        }

        // the arrangements: the main emblem first (the game edits it), the repeats after it
        static List<int[]> Arrange(int[] bg, int[] main, int p)
        {
            var list = new List<int[]> { Copy(bg) };
            int s = Math.Max(main[3], main[4]);
            Func<int, int, int, int, bool, int[]> at = (x, y, size, rot, mirror) =>
            {
                var a = Copy(main);
                float k = s > 0 ? (float)size / s : 1f;
                a[3] = Clamp((int)Math.Round(main[3] * k), 40, 1400); a[4] = Clamp((int)Math.Round(main[4] * k), 40, 1400);
                a[5] = x; a[6] = y; a[9] = ((rot % 360) + 360) % 360; a[8] = mirror ? 1 : 0; return a;
            };
            switch (p)
            {
                case 2: { int z = Math.Min(s, 400); list.Add(at(764 - 230, 764, z, 0, false)); list.Add(at(764 + 230, 764, z, 0, true)); break; }
                case 3: { int z = Math.Min(s, 330); list.Add(at(764, 764, z, 0, false)); list.Add(at(764, 764 - 380, z, 0, false)); list.Add(at(764, 764 + 380, z, 0, false)); break; }
                case 4: { int z = Math.Min(s, 330); list.Add(at(764 - 250, 764 - 250, z, 0, false)); list.Add(at(764 + 250, 764 - 250, z, 0, true)); list.Add(at(764 - 250, 764 + 250, z, 0, false)); list.Add(at(764 + 250, 764 + 250, z, 0, true)); break; }
                case 5: list.Add(at(764, 764, Clamp((int)(s * 1.6f), 300, 900), 0, false)); break;
                case 6:
                {
                    list.Add(at(764, 764, Math.Min(s, 360), 0, false));
                    for (int i = 0; i < 6; i++)
                    {
                        double a = Math.PI * 2 * i / 6 - Math.PI / 2;
                        list.Add(at(764 + (int)Math.Round(Math.Cos(a) * 470), 764 + (int)Math.Round(Math.Sin(a) * 470), 150, i * 60, false));
                    }
                    break;
                }
                default: list.Add(at(764, 764, s, 0, false)); break;
            }
            return list;
        }

        // ---- the clipboard (the game's own, found by name: absent on some builds)
        static bool Clip(string text)
        {
            try
            {
                var m = typeof(TaleWorlds.InputSystem.Input).GetMethod("SetClipboardText", new[] { typeof(string) });
                if (m == null) return false; m.Invoke(null, new object[] { text }); return true;
            }
            catch { return false; }
        }
        static string Clip()
        {
            try { var m = typeof(TaleWorlds.InputSystem.Input).GetMethod("GetClipboardText", Type.EmptyTypes); return m == null ? null : m.Invoke(null, null) as string; }
            catch { return null; }
        }

        // ---- three saved banners, one code per line, kept with the player's own files
        static string SlotFile { get { return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Aurelion", "banners.txt"); } }
        static void LoadSlots()
        {
            slots = new string[3];
            try
            {
                if (!System.IO.File.Exists(SlotFile)) return;
                var lines = System.IO.File.ReadAllLines(SlotFile);
                for (int i = 0; i < 3 && i < lines.Length; i++) { var t = lines[i].Trim(); slots[i] = TaleWorlds.Core.Banner.IsValidBannerCode(t) ? t : null; }
            }
            catch { }
        }
        static void SaveSlots()
        {
            try
            {
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(SlotFile));
                System.IO.File.WriteAllLines(SlotFile, new[] { slots[0] ?? "", slots[1] ?? "", slots[2] ?? "" });
                status = L("Saved", "اتحفظت"); stamp = DateTime.UtcNow;
            }
            catch { status = L("Could not save", "ما اتحفظتش"); stamp = DateTime.UtcNow; }
        }

        // ---- does a clan of this world already carry this banner
        static DateTime stamp = DateTime.MinValue; static string clash = ""; static int clashLevel;
        static void Check()
        {
            clash = ""; clashLevel = 0;
            try
            {
                if (TaleWorlds.CampaignSystem.Campaign.Current == null) return;
                var b = Banner(view); if (b == null) return;
                var me = Parse(b.Serialize()); if (me.Count < 2) return;
                var own = TaleWorlds.CampaignSystem.Clan.PlayerClan;
                foreach (var c in TaleWorlds.CampaignSystem.Clan.All)
                {
                    if (c == null || c == own || c.Banner == null || ReferenceEquals(c.Banner, b)) continue;
                    var o = Parse(c.Banner.Serialize()); if (o.Count < 2) continue;
                    bool same = Code(o) == Code(me);
                    bool alike = o[1][0] == me[1][0] && o[1][1] == me[1][1] && o[0][1] == me[0][1];
                    if (same) { clashLevel = 2; clash = c.Name != null ? c.Name.ToString() : "?"; break; }
                    if (alike && clashLevel < 1) { clashLevel = 1; clash = c.Name != null ? c.Name.ToString() : "?"; }
                }
            }
            catch { }
        }

        static void Sel(string id, bool on) { Widget w; if (ids.TryGetValue("AurBnB_" + id, out w) && w is ButtonWidget && ((ButtonWidget)w).IsSelected != on) ((ButtonWidget)w).IsSelected = on; }
        static void Show()
        {
            var b = Banner(view); if (b == null) return;
            var L0 = Parse(lastCode ?? b.Serialize());
            for (int c = 0; c < 6; c++) Sel("Cat" + c, c == cat);
            for (int p = 1; p <= 6; p++) Sel("Lay" + p, p == preset);
            for (int s = 0; s < 3; s++)
            {
                bool full = slots != null && !string.IsNullOrEmpty(slots[s]);
                bool here = full && slots[s] == lastCode;
                T("Slot" + (s + 1), (Ar ? "خانة " : "Slot ") + (s + 1) + "\n" + (here ? L("on the banner", "على الراية") : full ? L("saved", "محفوظة") : L("empty", "فاضية")));
                Sel("Slot" + (s + 1), s == slot);
            }
            Widget w;
            if (ids.TryGetValue("AurBnB_Undo", out w) && w.IsEnabled != (undo.Count > 0)) w.IsEnabled = undo.Count > 0;
            if (ids.TryGetValue("AurBnB_Redo", out w) && w.IsEnabled != (redo.Count > 0)) w.IsEnabled = redo.Count > 0;
            if (ids.TryGetValue("AurBnB_Forget", out w) && w.IsEnabled != (slot >= 0 && slots != null && !string.IsNullOrEmpty(slots[slot]))) w.IsEnabled = slot >= 0 && slots != null && !string.IsNullOrEmpty(slots[slot]);
            if (L0.Count >= 2)
            {
                var m = L0[1]; int n = L0.Count - 1;
                T("Pos", Ar ? "المكان " + m[5] + " × " + m[6] + "   ·   لفّة " + m[9] + "°   ·   " + n + (n == 1 ? " شعار" : " شعارات")
                             : "Place " + m[5] + " x " + m[6] + "   ·   turn " + m[9] + "°   ·   " + n + (n == 1 ? " emblem" : " emblems"));
                int pat = L0[0][0];
                T("PatName", Ar ? "نقشة " + pat + " من 36" : "Pattern " + pat + " of 36");
            }
            string line; uint dot;
            if ((DateTime.UtcNow - stamp).TotalSeconds < 2.5 && status.Length > 0) { line = status; dot = 0xE8B94EFF; }
            else if (clashLevel == 2) { line = Ar ? "عشيرة " + clash + " عندها نفس الراية بالظبط" : clash + " already carries this exact banner"; dot = 0xE56B6FFF; }
            else if (clashLevel == 1) { line = Ar ? "شبه راية " + clash + "، غيّر لون أو شعار" : "Close to " + clash + "'s banner: change a colour or the emblem"; dot = 0xE8B94EFF; }
            else { line = L("No clan in this world carries this banner", "محدش في العالم عنده الراية دي"); dot = 0x6FD08CFF; }
            T("Status", line);
            if (ids.TryGetValue("AurBnDotOk", out w))
            {
                var col = new TaleWorlds.Library.Color(((dot >> 24) & 255) / 255f, ((dot >> 16) & 255) / 255f, ((dot >> 8) & 255) / 255f, 1f);
                w.Color = col;
            }
        }
    }

    // ------------------------------------------------------------------ the state of the place (TownMenu board, right panel)
    // While the player stands in a town, castle or village menu on the map: prosperity, loyalty, security and food (or hearths
    // for a village) with bars, garrison and militia, the notables and who is there now. Read only; H hides it, like the battle panel.
    public class UiTown : GlobalLayer
    {
        static UiTown open; static int errors; static bool hidden; static DateTime next = DateTime.MinValue;
        GauntletLayer layer; object movie; TownCardVM vm;

        public static void Tick()
        {
            try
            {
                try { if (TaleWorlds.InputSystem.Input.IsKeyPressed(TaleWorlds.InputSystem.InputKey.H) && open != null) hidden = !hidden; } catch { }
                if (DateTime.UtcNow < next) return;
                next = DateTime.UtcNow.AddSeconds(0.5);
                var s = Where();
                if (s == null || hidden) { if (open != null) Close(); if (s == null) hidden = false; return; }
                if (open == null)
                {
                    if (errors >= 3 || !AurelionSkin.EnsureSprite("aur_v5", "aur_v5_1.png")) return;
                    var u = new UiTown(); u.vm = new TownCardVM();
                    u.layer = new GauntletLayer("AurelionTown", 3400, false);
                    u.movie = u.layer.LoadMovie("AurTownCard", u.vm);
                    u.Layer = u.layer;
                    ScreenManager.AddGlobalLayer(u, false);
                    open = u;
                }
                open.vm.Fill(s);
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiTown: " + (e.InnerException ?? e).Message); Close(); }
        }

        static readonly HashSet<string> Busy = new HashSet<string> { "MapRecruit", "MapTournamentLeaderboard", "MapTownManagement", "MapTroopSelection", "HeirSelectionPopup", "MapIncidents", "MapMarriageOffer", "MapArmyManagement", "MapCampaignOptions" };
        static bool layersLogged;
        static TaleWorlds.CampaignSystem.Settlements.Settlement Where()
        {
            if (TaleWorlds.CampaignSystem.Campaign.Current == null) return null;
            var top = ScreenManager.TopScreen;
            if (top == null || top.GetType().Name != "MapScreen") return null;
            try { var cm = TaleWorlds.CampaignSystem.Campaign.Current.ConversationManager; if (cm != null && cm.IsConversationInProgress) return null; } catch { }
            var s = TaleWorlds.CampaignSystem.Settlements.Settlement.CurrentSettlement;
            if (s == null || !(s.IsTown || s.IsCastle || s.IsVillage)) return null;
            if (!layersLogged) { layersLogged = true; try { var sb = new System.Text.StringBuilder(); foreach (var ly in top.Layers) { if (ly != null) sb.Append(ly.Name).Append(' '); } Log.W("UiTown: map layers " + sb.ToString()); } catch { } }
            try { foreach (var ly in top.Layers) { if (ly != null && ly.Name != null && Busy.Contains(ly.Name)) return null; } } catch { }
            return s;
        }

        static void Close()
        {
            var u = open; open = null; if (u == null || u.layer == null) return;
            try { if (u.movie != null) u.layer.ReleaseMovie((GauntletMovieIdentifier)u.movie); } catch { }
            try { AurLayers.Remove(u); } catch (Exception e) { Log.W("UiTown close: " + e.Message); }
        }
    }

    public class TownCardVM : ViewModel
    {
