        [DataSourceProperty] public float W1 { get { return _W1; } set { F(ref _W1, value, "W1"); } }
        [DataSourceProperty] public float W2 { get { return _W2; } set { F(ref _W2, value, "W2"); } }
        [DataSourceProperty] public float W3 { get { return _W3; } set { F(ref _W3, value, "W3"); } }
        [DataSourceProperty] public bool B0 { get { return _B0; } set { if (value != _B0) { _B0 = value; OnPropertyChangedWithValue(value, "B0"); } } }
        [DataSourceProperty] public bool B1 { get { return _B1; } set { if (value != _B1) { _B1 = value; OnPropertyChangedWithValue(value, "B1"); } } }
        [DataSourceProperty] public bool B2 { get { return _B2; } set { if (value != _B2) { _B2 = value; OnPropertyChangedWithValue(value, "B2"); } } }
        [DataSourceProperty] public bool B3 { get { return _B3; } set { if (value != _B3) { _B3 = value; OnPropertyChangedWithValue(value, "B3"); } } }
        void S(ref string f, string v, string n) { v = v ?? ""; if (v != f) { f = v; OnPropertyChangedWithValue(v, n); } }
        void F(ref float f, float v, string n) { if (Math.Abs(v - f) > 0.5f) { f = v; OnPropertyChangedWithValue(v, n); } }
        static float Bar(float v, float max) { if (max <= 0) return 0; v = v / max; if (v < 0) v = 0; if (v > 1) v = 1; return 110f * v; }
        static string N(float v) { return ((int)Math.Round(v)).ToString("N0", System.Globalization.CultureInfo.InvariantCulture); }
        static string L(string en, string ar) { return UiText.L(en, ar); }

        public void Fill(TaleWorlds.CampaignSystem.Settlements.Settlement s)
        {
            Name = s.Name == null ? "" : s.Name.ToString();
            string owner = "";
            try { if (s.OwnerClan != null && s.OwnerClan.Name != null) owner = s.OwnerClan.Name.ToString(); } catch { }
            try { if (s.MapFaction != null && s.MapFaction.Name != null && s.MapFaction.Name.ToString() != owner) owner += (owner.Length > 0 ? "  \u00b7  " : "") + s.MapFaction.Name.ToString(); } catch { }
            Owner = owner;
            var town = s.IsVillage ? null : s.Town;
            if (town != null)
            {
                L0 = L("Prosperity", "\u0627\u0644\u0627\u0632\u062f\u0647\u0627\u0631"); V0 = N(town.Prosperity); W0 = Bar(town.Prosperity, s.IsCastle ? 3000f : 10000f);
                L1 = L("Loyalty", "\u0627\u0644\u0648\u0644\u0627\u0621"); V1 = N(town.Loyalty); W1 = Bar(town.Loyalty, 100f);
                L2 = L("Security", "\u0627\u0644\u0623\u0645\u0646"); V2 = N(town.Security); W2 = Bar(town.Security, 100f);
                float food = town.FoodStocks, ch = 0; try { ch = town.FoodChange; } catch { }
                string days = ch < -0.01f ? L(" \u00b7 lasts " + (int)(food / -ch) + " days", " \u00b7 \u0628\u064a\u0643\u0641\u064a " + (int)(food / -ch) + " \u064a\u0648\u0645") : (ch > 0.01f ? " \u25b2" : "");
                L3 = L("Food in store", "\u0627\u0644\u0623\u0643\u0644 \u0641\u064a \u0627\u0644\u0645\u062e\u0632\u0646"); V3 = N(food) + days; W3 = Bar(food, 400f);
                B0 = B1 = B2 = B3 = true;
                int g = 0; try { if (town.GarrisonParty != null) g = town.GarrisonParty.MemberRoster.TotalManCount; } catch { }
                G = g.ToString(); GL = L("Garrison", "\u0627\u0644\u062d\u0627\u0645\u064a\u0629");
            }
            else
            {
                float hearth = 0; try { hearth = s.Village.Hearth; } catch { }
                L0 = L("Hearths", "\u0627\u0644\u0628\u064a\u0648\u062a"); V0 = N(hearth); W0 = Bar(hearth, 1000f); B0 = true;
                var bound = (TaleWorlds.CampaignSystem.Settlements.Town)null;
                try { if (s.Village.Bound != null) bound = s.Village.Bound.Town; } catch { }
                if (bound != null)
                {
                    L1 = L("Loyalty of " + bound.Name, "\u0648\u0644\u0627\u0621 " + bound.Name); V1 = N(bound.Loyalty); W1 = Bar(bound.Loyalty, 100f);
                    L2 = L("Security of " + bound.Name, "\u0623\u0645\u0646 " + bound.Name); V2 = N(bound.Security); W2 = Bar(bound.Security, 100f);
                    B1 = B2 = true;
                }
                else { L1 = L2 = V1 = V2 = ""; B1 = B2 = false; }
                L3 = ""; V3 = ""; B3 = false;
                int v = 0; try { foreach (var p in s.Parties) if (p != null && p.IsVillager) v += p.MemberRoster.TotalManCount; } catch { }
                G = v.ToString(); GL = L("Villagers out", "\u0641\u0644\u0627\u062d\u064a\u0646 \u0628\u0631\u0647");
            }
            M = N(s.Militia); ML = L("Militia", "\u0627\u0644\u0645\u064a\u0644\u064a\u0634\u064a\u0627");
            // notables: names only (the game's strip shows their faces)
            var nl = new List<string>();
            try { foreach (var h in s.Notables) if (h != null && h.Name != null) nl.Add(h.Name.ToString()); } catch { }
            NotablesL = L("Notables", "\u0627\u0644\u0623\u0639\u064a\u0627\u0646") + "  " + nl.Count;
            Notables = nl.Count == 0 ? L("none", "\u0645\u0641\u064a\u0634") : string.Join("  \u00b7  ", nl.Count > 4 ? nl.GetRange(0, 4).ToArray() : nl.ToArray()) + (nl.Count > 4 ? "  +" + (nl.Count - 4) : "");
            // who is here now: lords, players and caravans (not the garrison or militia)
            var pl = new List<string>(); int n = 0;
            try
            {
                foreach (var p in s.Parties)
                {
                    if (p == null || p.IsGarrison || p.IsMilitia || p == TaleWorlds.CampaignSystem.Party.MobileParty.MainParty) continue;
                    if (!(p.IsLordParty || p.IsCaravan)) continue;
                    n++;
                    if (pl.Count < 4) pl.Add((p.Name == null ? "?" : p.Name.ToString()) + "  \u00b7  " + p.MemberRoster.TotalManCount);
                }
            }
            catch { }
            PartiesL = L("Here now", "\u0645\u0648\u062c\u0648\u062f\u064a\u0646 \u062f\u0644\u0648\u0642\u062a\u064a") + "  " + n;
            Parties = n == 0 ? L("nobody", "\u0645\u0641\u064a\u0634 \u062d\u062f") : string.Join("\n", pl.ToArray()) + (n > 4 ? "\n+" + (n - 4) : "");
        }
    }
    // Aurelion: a bandit leader is not a hero, so the game leaves his barter portrait empty.
    // After the barter screen model is made, an empty side gets the picture of the party's own leader troop,
    // so looters, sea raiders, forest, mountain, desert and steppe bandits each show their own man.
    public static class UiBarterFace
    {
        static bool done; static int errors;
        public static void Install()
        {
            if (done || SubModule.H == null) return; done = true;
            var t = AccessTools.TypeByName("TaleWorlds.CampaignSystem.ViewModelCollection.Barter.BarterVM");
            if (t == null) { Log.W("UiBarterFace: barter model not found"); return; }
            foreach (var c in t.GetConstructors(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
                SubModule.H.Patch(c, postfix: new HarmonyMethod(typeof(UiBarterFace), "After"));
            Log.W("UiBarterFace: ready");
        }

        static void After(object __instance)
        {
            try
            {
                if (__instance == null) return;
                var t = __instance.GetType();
                var f = AccessTools.Field(t, "_otherCharacter"); if (f == null) return;
                var ch = f.GetValue(__instance); if (ch == null) return;
                var codeT = AccessTools.TypeByName("TaleWorlds.Core.CharacterCode");
                var basicT = AccessTools.TypeByName("TaleWorlds.Core.BasicCharacterObject");
                var imgT = AccessTools.TypeByName("TaleWorlds.Core.ViewModelCollection.ImageIdentifiers.CharacterImageIdentifierVM");
                if (codeT == null || basicT == null || imgT == null) return;
                var create = codeT.GetMethod("CreateFrom", new Type[] { basicT }); if (create == null) return;
                object code = null;
                foreach (var side in new[] { "LeftHero", "RightHero" })
                {
                    var p = AccessTools.Property(t, side); if (p == null) continue;
                    var hv = p.GetValue(__instance, null); if (hv == null) continue;
                    var ip = AccessTools.Property(hv.GetType(), "ImageIdentifier"); if (ip == null || !ip.CanWrite) continue;
                    if (ip.GetValue(hv, null) != null) continue;
                    if (code == null) code = create.Invoke(null, new object[] { ch });
                    if (code == null) return;
                    ip.SetValue(hv, Activator.CreateInstance(imgT, new object[] { code }), null);
                }
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiBarterFace: " + (e.InnerException ?? e).Message); }
        }
    }
