// =====================================================================================
//  system/UiEscape.cs — قايمة Esc عند اللاعبين: بنشيل حفظ / حفظ باسم / تحميل / احفظ واخرج / خيارات الحملة
//  (الحفظ في السيرفر بس، والأزرار دي عند اللاعب إما مقفولة أو بتفتح حاجات ملهاش لازمة في الكوب).
//  بيشتغل بعد باتشات الكوب (Priority.Last) عشان زرار "Coop Options" يتحط الأول جنب "خيارات الحملة" وبعدين نشيلها.
//  المقارنة بالنص المترجم لنفس الـ TextObject بتاع اللعبة، فبتشتغل بأي لغة.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using HarmonyLib;
using TaleWorlds.Localization;

namespace Aurelion.Core
{
    public static class UiEscape
    {
        static bool hooked;
        static readonly string[] Ids = { "{=bV75iwKa}Save", "{=e0KdfaNe}Save As", "{=9NuttOBC}Load", "{=AbEh2y8o}Save And Exit", "{=PXT6aA4J}Campaign Options" };
        static int removedLogged;

        public static void Hook()
        {
            if (hooked) return; hooked = true;
            try
            {
                var map = AccessTools.TypeByName("SandBox.View.Map.MapScreen");
                var m = map == null ? null : AccessTools.Method(map, "GetEscapeMenuItems");
                if (m == null) { Log.W("UiEscape: MapScreen.GetEscapeMenuItems not found, Esc menu keeps every item"); return; }
                var post = new HarmonyMethod(typeof(UiEscape), "Postfix") { priority = Priority.Last };
                var h = new Harmony("aurelion.uiescape");
                h.Patch(m, postfix: post);
                HookQuests(h);
                try
                {
                    var vm = AccessTools.TypeByName("TaleWorlds.MountAndBlade.ViewModelCollection.EscapeMenu.EscapeMenuItemVM");
                    var rv = vm == null ? null : AccessTools.PropertySetter(vm, "ActionText");
                    if (rv != null) { h.Patch(rv, prefix: new HarmonyMethod(typeof(UiEscape), "ItemArabic")); Log.W("UiEscape: coop item names ready"); }
                    else Log.W("UiEscape: EscapeMenuItemVM.ActionText not found, coop items stay English");
                }
                catch (Exception e) { Log.W("UiEscape: coop item names failed: " + e.Message); }
                HookTableauShadow(h);
                Log.W("UiEscape: Esc menu filter ready");
            }
            catch (Exception e) { Log.W("UiEscape: hook failed: " + e.Message); }
        }

        // ---- quests are closed for now (owner's decision 14/11): the map-bar button shows locked with a reason, the J key and every link do nothing
        static void HookQuests(Harmony h)
        {
            try
            {
                var t = AccessTools.TypeByName("SandBox.View.Map.Navigation.NavigationElements.QuestsNavigationElement");
                if (t == null) { Log.W("UiEscape: quests button not found, quests stay open"); return; }
                var perm = AccessTools.Method(t, "GetPermission");
                if (perm != null) h.Patch(perm, postfix: new HarmonyMethod(typeof(UiEscape), "QuestsPermission"));
                int n = 0;
                foreach (var m in AccessTools.GetDeclaredMethods(t))
                    if (m.Name == "OpenView" || m.Name == "GoToLink" || m.Name == "PrepareToOpenQuestsScreen" || m.Name == "OpenQuestsAction")
                    { h.Patch(m, prefix: new HarmonyMethod(typeof(UiEscape), "QuestsBlock")); n++; }
                var map = AccessTools.TypeByName("SandBox.View.Map.MapScreen");
                var oq = map == null ? null : AccessTools.Method(map, "OpenQuestsScreen");
                if (oq != null) { h.Patch(oq, prefix: new HarmonyMethod(typeof(UiEscape), "QuestsBlock")); n++; }
                Log.W("UiEscape: quests locked (" + n + " ways in closed)");
            }
            catch (Exception e) { Log.W("UiEscape: quests lock failed: " + e.Message); }
        }
        public static void QuestsPermission(ref TaleWorlds.CampaignSystem.NavigationPermissionItem __result)
        {
            __result = new TaleWorlds.CampaignSystem.NavigationPermissionItem(false, new TextObject(UiText.L("Quests are locked for now. They open soon.", "المهام مقفولة حالياً، هتفتح قريب.")));
        }
        public static bool QuestsBlock() { return false; }

        // ---- the 3D hero in character / inventory / party / clan screens: the game's own shadow is cut by the edge of the picture
        // (the "headless" shadow on our backgrounds). The game's shadow is switched off; our screens put a soft ground shade under the feet.
        static System.Reflection.FieldInfo tableauScene;
        static void HookTableauShadow(Harmony h)
        {
            try
            {
                var t = AccessTools.TypeByName("TaleWorlds.MountAndBlade.View.Tableaus.CharacterTableau");
                var m = t == null ? null : AccessTools.Method(t, "FirstTimeInit");
                tableauScene = t == null ? null : AccessTools.Field(t, "_tableauScene");
                if (m == null || tableauScene == null) { Log.W("UiEscape: hero picture not found, its shadow stays"); return; }
                h.Patch(m, postfix: new HarmonyMethod(typeof(UiEscape), "TableauNoShadow"));
                Log.W("UiEscape: hero picture shadow off");
            }
            catch (Exception e) { Log.W("UiEscape: shadow hook failed: " + e.Message); }
        }
        static int shadowLogged;
        public static void TableauNoShadow(object __instance)
        {
            try
            {
                var sc = tableauScene.GetValue(__instance);
                if (sc == null) return;
                var set = AccessTools.Method(sc.GetType(), "SetShadow", new[] { typeof(bool) });
                if (set != null) set.Invoke(sc, new object[] { false });
                if (shadowLogged++ < 1) Log.W("UiEscape: hero picture shadow switched off");
            }
            catch (Exception e) { if (shadowLogged++ < 2) Log.W("UiEscape: shadow off failed: " + e.Message); }
        }

        public static void ItemArabic(ref string value)
        {
            try
            {
                if (value == null || !UiText.Arabic) return;
                var t = value.Trim();
                if (t == "Coop Options") value = "إعدادات الأونلاين";
                else if (t == "Report Coop Bug") value = "بلّغ عن مشكلة";
                else if (t == "Invite Friends") value = "ادعي صحابك";
            }
            catch { }
        }

        public static void Postfix(object __result)
        {
            try
            {
                var list = __result as IList;
                if (list == null || list.Count == 0) return;
                var hide = new HashSet<string>(StringComparer.Ordinal);
                foreach (var id in Ids) { var s = new TextObject(id).ToString(); if (!string.IsNullOrEmpty(s)) hide.Add(s.Trim()); }
                var prop = AccessTools.Property(list[0].GetType(), "ActionText");
                if (prop == null) return;
                int n = 0;
                for (int i = list.Count - 1; i >= 0; i--)
                {
                    var t = prop.GetValue(list[i], null) as string;
                    if (t != null && hide.Contains(t.Trim())) { list.RemoveAt(i); n++; }
                }
                if (UiText.Arabic)
                {
                    var fld = AccessTools.Field(list[0].GetType(), "_actionText");
                    var itemObj = AccessTools.Field(list[0].GetType(), "_itemObj");
                    for (int i = 0; i < list.Count; i++)
                    {
                        var t = prop.GetValue(list[i], null) as string;
                        if (t == null) continue;
                        string ar = null;
                        if (t.Trim() == "Coop Options") ar = "إعدادات الأونلاين";
                        else if (t.Trim() == "Report Coop Bug") ar = "بلّغ عن مشكلة";
                        if (ar == null) continue;
                        if (itemObj != null) itemObj.SetValue(list[i], new TextObject(ar));
                        if (prop.CanWrite) prop.SetValue(list[i], ar, null);
                        else if (fld != null) fld.SetValue(list[i], ar);
                    }
                }
                if (removedLogged++ < 2) Log.W("UiEscape: removed " + n + " items, " + list.Count + " left");
            }
            catch (Exception e) { if (removedLogged++ < 2) Log.W("UiEscape: " + e.Message); }
        }
    }
}

src.system/UiScreens.cs:
// =====================================================================================
//  system/UiScreens.cs — شاشات اللعبة بتصميم أوريليون المعتمد (نفس اللوح بالظبط)
//  ملفات الشاشات بتاعتنا في  Modules\Coop\GUI\AurelionScreens\  (مش جوه Prefabs، فمحدش تاني بيقراها ولا بتتعارض مع حد).
//  وقت التشغيل: بنسجّلها عند اللعبة بالاسم الأصلي (ClanScreen ...) وبنشيل النسخة المترجمة (AutoGenerated) بتاعة نفس الاسم،
//  فشاشتنا هي اللي بتفتح دايماً مهما كان فيه مودات تانية. مش بنغيّر ولا ملف من ملفات اللعبة.
//  قبل التسجيل: كل ملف بيتقرا ويتأكد إنه XML سليم، وكل الصور بتتحمّل؛ لو أي حاجة ناقصة مش بنسجّل حاجة والشاشة الأصلية تفضل.
//  وكمان: القيم اللي اللعبة مش بتديها للشاشة (السن، الثقافة، الصحة، المستوى، أسامي المهارات، تنسيق الأرقام) بنكتبها من البطل نفسه.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using TaleWorlds.Engine.GauntletUI;
using TaleWorlds.GauntletUI;
using TaleWorlds.GauntletUI.BaseTypes;
using TaleWorlds.ScreenSystem;
using TaleWorlds.CampaignSystem;
using TaleWorlds.CampaignSystem.ViewModelCollection.ClanManagement;
using TaleWorlds.Core;
using TaleWorlds.ObjectSystem;

namespace Aurelion.Core
{
    public static class UiScreens
    {
        const BindingFlags All = BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;
        // every image a screen of ours draws from: all must be ready before the screen is handed to the game
        static readonly string[] Sheets = { "aur_skin", "aur_skin2", "aur_bg_clan_members", "aur_bg_clan_parties", "aur_bg_clan_fiefs", "aur_bg_clan_other", "aur_cult", "aur_cult_art", "aur_v5", "aur_cult5", "aur_v6" };
        static bool done; static int tries; static DateTime next = DateTime.MinValue;
        static readonly List<string> registered = new List<string>();

        public static void Tick()
        {
            try { SlotsScreen.Tick(); } catch { }
            if (!done && DateTime.UtcNow >= next)
            {
                next = DateTime.UtcNow.AddSeconds(1);
                try { Register(); } catch (Exception e) { done = true; Log.W("UiScreens: not registered, the game's own screens stay: " + (e.InnerException ?? e).Message); }
            }
            if (registered.Count > 0) { try { ApplyDirection(); } catch (Exception e) { if (++fillErrors <= 3) Log.W("UiScreens direction: " + e.Message); } }
            if (registered.Count > 0) { try { Fill(); } catch (Exception e) { if (++fillErrors <= 3) Log.W("UiScreens fill: " + (e.InnerException ?? e).Message); } }
            try { UiLoading.Tick(registered.Contains("AurLoadingWindow")); } catch (Exception e) { if (++fillErrors <= 3) Log.W("UiLoading: " + e.Message); }
            if (registered.Contains("CharacterCreationCultureStage")) { try { UiCulture.Tick(); } catch { } }
            if (registered.Contains("BannerEditor")) { try { UiBanner.Tick(); } catch { } }
            try { UiHud.Tick(); } catch { }
            try { HeroCard.Tick(); } catch { }
            try { UiWatch.Tick(); } catch { }
        }

        // screens we no longer replace. LoadingWindow: ours is now AurLoadingWindow and is shown only on the way into the world
        static readonly HashSet<string> Retired = new HashSet<string>(StringComparer.Ordinal) { "LoadingWindow" };
        // Safety switch: a screen named on its own line in Modules\\Coop\\aurelion\\ui-off.txt is never replaced: the game's own one shows.
        // Lets a broken screen be taken off for every player who edits the file, without a new build. Read once per game start.
        static HashSet<string> off;
        public static bool IsOff(string name)
        {
            if (off == null)
            {
                var s = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                try
                {
                    var f = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(UiScreens).Assembly.Location), "..", "..", "aurelion", "ui-off.txt"));
                    if (File.Exists(f))
                        foreach (var line in File.ReadAllLines(f)) { var n = line.Trim(); if (n.Length > 0 && !n.StartsWith("#")) s.Add(n); }
                    if (s.Count > 0) Log.W("UiScreens: switched off by ui-off.txt: " + string.Join(", ", new List<string>(s).ToArray()));
                }
                catch { }
                off = s;
            }
            return name != null && off.Contains(name);
        }
        static void Register()
        {
            var wf = UIResourceManager.WidgetFactory;
            if (wf == null) return;
            var module = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(UiScreens).Assembly.Location), "..", ".."));
            var dir = Path.Combine(module, "GUI", "AurelionScreens");
            if (!Directory.Exists(dir)) { done = true; Log.W("UiScreens: no Aurelion screens in this build"); return; }

            foreach (var c in Sheets)
                if (!AurelionSkin.EnsureSprite(c, c + "_1.png"))
                {
                    if (++tries >= 15) { done = true; Log.W("UiScreens: image " + c + " could not be loaded, the game's own screens stay"); }
                    return;   // sprite data registers a moment later: try again next second
                }

            var files = Directory.GetFiles(dir, "*.xml");
            foreach (var f in files)
            {
                try { var x = new System.Xml.XmlDocument(); x.Load(f); }
                catch (Exception e) { done = true; Log.W("UiScreens: " + Path.GetFileName(f) + " is not valid, the game's own screens stay: " + e.Message); return; }
            }

            var paths = Fld(wf, "_customTypePaths") as IDictionary;
            var live = Fld(wf, "_liveCustomTypes") as IDictionary;
            var gen = wf.GeneratedPrefabContext;
            var genMap = Fld(gen, "_generatedPrefabs") as IDictionary;
            if (paths == null) { done = true; Log.W("UiScreens: prefab table not found in this game build, the game's own screens stay"); return; }

            var where = dir.Replace('\\', '/') + "/";
            foreach (var f in files)
            {
                var name = Path.GetFileNameWithoutExtension(f);
                if (Retired.Contains(name) || IsOff(name)) continue;   // an old file from an earlier build may still be on the disk: the game's own screen stays
                paths[name] = where;
                if (live != null && live.Contains(name)) live.Remove(name);
                if (genMap != null && genMap.Contains(name)) genMap.Remove(name);
                registered.Add(name);
            }
            // The game ships some screens precompiled (character, inventory, party, quests...). A precompiled screen carries its own copy
            // of every small piece it uses (bottom buttons, popups), so it would never pick up our version of those pieces.
            // Any precompiled screen whose file uses one of our pieces is therefore built from its file instead, which uses ours.
            int rebuilt = 0;
            if (genMap != null)
            {
                var keys = new List<string>();
                foreach (var k in genMap.Keys) { var ks = k as string; if (ks != null && !registered.Contains(ks)) keys.Add(ks); }
                foreach (var k in keys)
                {
                    try
                    {
                        var p = paths[k] as string;
                        if (p == null) continue;
                        var file = Path.Combine(p, k + ".xml");
                        if (!File.Exists(file)) continue;
                        var text = File.ReadAllText(file);
                        foreach (var r in registered)
                            if (text.IndexOf("<" + r + " ", StringComparison.Ordinal) >= 0 || text.IndexOf("<" + r + "/", StringComparison.Ordinal) >= 0 || text.IndexOf("<" + r + ">", StringComparison.Ordinal) >= 0)
                            {
                                genMap.Remove(k); if (live != null && live.Contains(k)) live.Remove(k); rebuilt++; break;
                            }
                    }
                    catch { }
                }
            }
            done = true;
            Log.W("UiScreens: " + rebuilt + " precompiled game screens now built from their files so they use our pieces");
            Log.W("UiScreens: " + registered.Count + " Aurelion screens in use (" + string.Join(", ", registered.ToArray()) + ")");
        }

        // ------------------------------------------------------------------ text direction
        // The boards are laid out left to right and stay that way in every language. Text that starts at the left of its box in
        // English starts at the right of the same box in Arabic. (The Arabic mod centres any Arabic text whose box says "left", by each
        // player's own setting; a box that already says "right" is left alone, so every player sees the same screen.)
        static readonly string[] StartBrushes = { "Aur.V5.Badge", "Aur.V5.Name", "Aur.V5.SecTitle", "Aur.V5.Ttl", "Aur.V5.Body2", "Aur.V5.OptText", "Aur.V5.Huge", "Aur.V5.FeatPos", "Aur.V5.FeatNeg", "Aur.V5.Line", "Aur.V5.Lbl", "Aur.V5.Rank", "Aur.UI.Title", "Aur.UI.Lab", "Aur.UI.Val", "Aur.UI.Body", "Aur.UI.Muted", "Aur.UI.Small",
            "Aur.UI.Tiny", "Aur.UI.Sh", "Aur.UI.SkillName", "Aur.UI.SkillVal", "Aur.UI.Row.Text", "Aur.UI.PopTitle", "Aur.UI.PopBody",
            "Aur.Cult.Desc", "Aur.Cult.Feat.Pos", "Aur.Cult.Feat.Neg", "Aur.Load.Chip", "Aur.Load.Law", "Aur.Load.Tip", "Aur.Load.Title", "Aur.Load.Desc",
            "Aur.V6.Hero", "Aur.V6.H1", "Aur.V6.H2", "Aur.V6.H3", "Aur.V6.Body", "Aur.V6.Text", "Aur.V6.Cap", "Aur.V6.Kick", "Aur.V6.Status", "Aur.V6.Chip", "Aur.V6.ChipB", "Aur.V6.Good", "Aur.V6.Bad", "Aur.V6.Row" };
        static string directionFor;
        static void ApplyDirection()
        {
            string lang;
            try { lang = TaleWorlds.Localization.MBTextManager.ActiveTextLanguage ?? ""; } catch { return; }
            if (lang == directionFor) return;
            var bf = UIResourceManager.BrushFactory;
            if (bf == null) return;
            var a = Arabic ? TaleWorlds.TwoDimension.TextHorizontalAlignment.Right : TaleWorlds.TwoDimension.TextHorizontalAlignment.Left;
            int n = 0;
            foreach (var name in StartBrushes)
            {
                var b = bf.GetBrush(name);
                if (b == null || b.Name != name) continue;   // GetBrush falls back to a default brush for unknown names
                b.TextHorizontalAlignment = a; n++;
            }
            directionFor = lang;
            Log.W("UiScreens: text direction for '" + lang + "' -> " + a + " (" + n + " brushes)");
        }

        // ------------------------------------------------------------------ values the game does not hand to the screen
        static int fillErrors;
        static DateTime nextFill = DateTime.MinValue;
        static bool Arabic
        {
            get
            {
                try { var l = TaleWorlds.Localization.MBTextManager.ActiveTextLanguage ?? ""; return l.IndexOf("arab", StringComparison.OrdinalIgnoreCase) >= 0 || l.IndexOf("عرب", StringComparison.Ordinal) >= 0; }
                catch { return false; }
            }
        }
        static string L(string en, string ar) { return Arabic ? ar : en.ToUpperInvariant(); }
        static string Lw(string en, string ar) { return Arabic ? ar : en; }
        static string N(int v) { return v.ToString("N0", CultureInfo.InvariantCulture); }

        static void Fill()
        {
            var top = ScreenManager.TopScreen;
            if (top == null) return;
            var tn = top.GetType().Name;
            if (tn == "GauntletKingdomScreen") { if (DateTime.UtcNow >= nextFill) { nextFill = DateTime.UtcNow.AddMilliseconds(300); FillKingdom(top); } return; }
            if (tn == "GauntletPartyScreen") { if (DateTime.UtcNow >= nextFill) { nextFill = DateTime.UtcNow.AddMilliseconds(500); FillParty(top); } return; }
            if (tn != "GauntletClanScreen" || !registered.Contains("ClanScreen")) return;
            if (DateTime.UtcNow < nextFill) return;
            nextFill = DateTime.UtcNow.AddMilliseconds(200);
            var layer = Fld(top, "_gauntletLayer") as GauntletLayer;
            var vm = (Prop(top, "_dataSource") ?? Fld(top, "<_dataSource>k__BackingField")) as ClanManagementVM;
            if (layer == null || vm == null || layer.UIContext == null || layer.UIContext.Root == null) return;

            var ids = new Dictionary<string, Widget>(StringComparer.Ordinal);
            var skillNames = new List<TextWidget>();
            Collect(layer.UIContext.Root, ids, skillNames);

            // clan header
            var leader = vm.Leader != null ? vm.Leader.Hero : null;
            Set(ids, "AurLeaderLine", leader != null ? leader.Name + " · " + Lw("Clan leader", "قائد العشيرة") : "");
            // the renown label always sits right next to its number (user 13/11)
            Set(ids, "AurTierR", Lw("Renown ", "الشهرة: ") + (vm.IsRenownProgressComplete ? N(vm.CurrentRenown) : N(vm.CurrentRenown) + " / " + N(vm.NextTierRenown)));
            Set(ids, "AurRenownL", "");
            Set(ids, "AurRenownR", vm.IsRenownProgressComplete ? "" : (Arabic ? N(Math.Max(0, vm.NextTierRenown - vm.CurrentRenown)) + " للرتبة " + vm.NextTier
                                                                         : N(Math.Max(0, vm.NextTierRenown - vm.CurrentRenown)) + " to tier " + vm.NextTier));
            // finance
            Set(ids, "AurFin_Income", N(vm.TotalIncome));
            Set(ids, "AurFin_Expenses", N(vm.TotalExpenses));
            Set(ids, "AurFin_Daily", (vm.DailyChange > 0 ? "+" : "") + N(vm.DailyChange));
            Set(ids, "AurFin_Gold", N(vm.CurrentGold));
            Set(ids, "AurFin_Expected", N(vm.ExpectedGold));

            // selected member
            Set(ids, "AurL_Age", L("Age", "العمر")); Set(ids, "AurL_Culture", L("Culture", "الثقافة")); Set(ids, "AurL_Location", L("Location", "المكان"));
            Set(ids, "AurL_Health", L("Health", "الصحة")); Set(ids, "AurL_Level", L("Level", "المستوى"));
            var m = vm.ClanMembers != null ? vm.ClanMembers.CurrentSelectedMember : null;
            var h = m != null ? m.GetHero() : null;
            if (h != null)
            {
                Set(ids, "AurV_Age", ((int)h.Age).ToString(CultureInfo.InvariantCulture));
                Set(ids, "AurV_Culture", h.Culture != null && h.Culture.Name != null ? h.Culture.Name.ToString() : "-");
                Set(ids, "AurV_Health", (h.MaxHitPoints > 0 ? (int)Math.Round(100.0 * h.HitPoints / h.MaxHitPoints) : 0) + "%");
                Set(ids, "AurV_Level", h.Level.ToString(CultureInfo.InvariantCulture));
                // traits sit under their own label: on the right of the column in Arabic, on the left otherwise
                Widget tr;
                if (ids.TryGetValue("AurTraits", out tr))
                {
                    var ha = Arabic ? HorizontalAlignment.Right : HorizontalAlignment.Left;
                    if (tr.HorizontalAlignment != ha) tr.HorizontalAlignment = ha;
                }
                // the game leaves "location" empty for a hero riding with the player's own party: say where they are
                Widget lw;
                if (ids.TryGetValue("AurV_Location", out lw))
                {
                    var lt = lw as RichTextWidget;
                    if (lt != null && string.IsNullOrEmpty(m.LocationText))
                    {
                        string where = null;
                        if (h.CurrentSettlement != null) where = h.CurrentSettlement.Name.ToString();
                        else if (h.PartyBelongedTo != null && h.PartyBelongedTo.Name != null) where = h.PartyBelongedTo.Name.ToString();
                        if (string.IsNullOrEmpty(where)) where = "—";
                        if (lt.Text != where) lt.Text = where;
                    }
                }
                bool isLeader = h.Clan != null && h.Clan.Leader == h;
                var rel = m.RelationToMainHeroText;
                Set(ids, "AurRole", isLeader ? L("Clan leader", "قائد العشيرة") : (string.IsNullOrEmpty(rel) ? L("Member", "عضو") : (Arabic ? rel : rel.ToUpperInvariant())));
                if (m.Skills != null)
                    for (int i = 0; i < skillNames.Count && i < m.Skills.Count; i++)
                    {
                        var s = MBObjectManager.Instance != null ? MBObjectManager.Instance.GetObject<SkillObject>(m.Skills[i].SkillId) : null;
                        Set(skillNames[i], s != null && s.Name != null ? s.Name.ToString() : m.Skills[i].SkillId);
                    }
            }
        }

        // ------------------------------------------------------------------ our cards on the kingdom and party screens
        // (the game's own screens and order stay; these cards only add numbers the game already knows but does not show)
        static Dictionary<string, Widget> Ids(GauntletLayer layer)
        {
            var ids = new Dictionary<string, Widget>(StringComparer.Ordinal);
            if (layer == null || layer.UIContext == null || layer.UIContext.Root == null) return ids;
            Collect(layer.UIContext.Root, ids, new List<TextWidget>());
            return ids;
        }
        static void Show(Dictionary<string, Widget> ids, string id, bool on) { Widget w; if (ids.TryGetValue(id, out w) && w.IsVisible != on) w.IsVisible = on; }
        static string Days(float stock, float change)
        {
            if (change >= 0f) return Lw("stable", "مستقرة");
            int d = (int)Math.Floor(stock / -change);
            return Arabic ? (d == 1 ? "يوم واحد" : d + " يوم") : (d == 1 ? "1 day" : d + " days");
        }
        static string Sgn(float v) { return (v > 0 ? "+" : (v < 0 ? "−" : "")) + N((int)Math.Round(Math.Abs(v))); }

        static void FillKingdom(ScreenBase top)
        {
            var layer = Fld(top, "_gauntletLayer") as GauntletLayer;
            var vm = Prop(top, "DataSource") as TaleWorlds.CampaignSystem.ViewModelCollection.KingdomManagement.KingdomManagementVM;
            if (layer == null || vm == null) return;
            var ids = Ids(layer);
            if (ids.Count == 0) return;

            // fiefs tab: what the selected castle or town brings and costs every day
            var si = vm.Settlement != null ? vm.Settlement.CurrentSelectedSettlement : null;
            var st = si != null && si.Settlement != null ? si.Settlement.Town : null;
            if (st != null)
            {
                float tax = 0f;
                try { tax = Campaign.Current.Models.SettlementTaxModel.CalculateTownTax(st, false).ResultNumber; } catch { }
                int wage = 0;
                try { if (st.GarrisonParty != null) wage = st.GarrisonParty.TotalWage; } catch { }
                Set(ids, "AurFiefT", Lw("Every day", "في اليوم"));
                Set(ids, "AurFiefR1", Lw("Taxes: ", "الضرايب: ") + Sgn(tax));
                Set(ids, "AurFiefR2", Lw("Garrison wages: ", "أجر الحامية: ") + Sgn(-wage));
                Set(ids, "AurFiefR3", Lw("Net: ", "الصافي: ") + Sgn(tax - wage));
                Set(ids, "AurFiefR4", Lw("Food lasts: ", "المؤن بتكفي: ") + Days(st.FoodStocks, st.FoodChange));
                Set(ids, "AurFiefR5", Lw("Loyalty change: ", "الولاء في اليوم: ") + (st.LoyaltyChange >= 0 ? "+" : "−") + Math.Abs(st.LoyaltyChange).ToString("0.0", CultureInfo.InvariantCulture));
                Set(ids, "AurFiefW", st.Loyalty < 25f ? Lw("Loyalty is low: it may rebel", "الولاء واطي: ممكن تقوم ثورة")
                                    : (st.FoodChange < 0f && st.FoodStocks / -st.FoodChange < 10f ? Lw("Food runs out soon", "المؤن هتخلص قريب") : ""));
                Show(ids, "AurFiefCard", true);
            }
            else Show(ids, "AurFiefCard", false);

            // armies tab: what the selected army can do right now
            var ai = vm.Army != null ? vm.Army.CurrentSelectedArmy : null;
            var army = ai != null ? ai.Army : null;
            if (army != null && army.LeaderParty != null)
            {
                var lp = army.LeaderParty;
                int foodDays = int.MaxValue;
                try { foreach (var p in army.Parties) { if (p == null) continue; int d = p.GetNumDaysForFoodToLast(); if (d < foodDays) foodDays = d; } } catch { }
                Set(ids, "AurArmyT", Lw("Right now", "دلوقتي"));
                Set(ids, "AurArmyR1", Lw("Strength: ", "القوة: ") + N((int)Math.Round(army.EstimatedStrength)));
                Set(ids, "AurArmyR2", Lw("Men: ", "الرجالة: ") + N(army.TotalHealthyMembers));
                Set(ids, "AurArmyR3", Lw("Speed: ", "السرعة: ") + lp.Speed.ToString("0.0", CultureInfo.InvariantCulture));
                Set(ids, "AurArmyR4", Lw("Food lasts: ", "الأكل بيكفي: ") + (foodDays == int.MaxValue ? "—" : (Arabic ? foodDays + " يوم" : foodDays + " days")));
                Set(ids, "AurArmyR5", Lw("Cohesion a day: ", "التماسك في اليوم: ") + (army.DailyCohesionChange >= 0 ? "+" : "−") + Math.Abs(army.DailyCohesionChange).ToString("0.0", CultureInfo.InvariantCulture));
                Set(ids, "AurArmyW", army.Cohesion < army.CohesionThresholdForDispersion + 10 ? Lw("Close to breaking up", "قرّب يتفرّق") : "");
                Show(ids, "AurArmyCard", true);
            }
            else Show(ids, "AurArmyCard", false);
        }

        static void FillParty(ScreenBase top)
        {
            var layer = Fld(top, "_gauntletLayer") as GauntletLayer;
            var mp = TaleWorlds.CampaignSystem.Party.MobileParty.MainParty;
            if (layer == null || mp == null) return;
            var ids = Ids(layer);
            if (!ids.ContainsKey("AurPartyCard")) return;
            Set(ids, "AurPartyR1", Lw("Wages a day: ", "الأجور في اليوم: ") + N(mp.TotalWage));
            int fd = mp.GetNumDaysForFoodToLast();
            Set(ids, "AurPartyR2", Lw("Food lasts: ", "الأكل بيكفي: ") + (mp.FoodChange >= 0f ? Lw("stable", "مستقر") : (Arabic ? fd + " يوم" : fd + " days")));
            Set(ids, "AurPartyR3", Lw("Morale: ", "المعنويات: ") + ((int)Math.Round(mp.Morale)).ToString(CultureInfo.InvariantCulture));
            Set(ids, "AurPartyR4", Lw("Speed: ", "السرعة: ") + mp.Speed.ToString("0.0", CultureInfo.InvariantCulture));
            Show(ids, "AurPartyCard", true);
        }

        static object Fld(object o, string name)
        {
            if (o == null) return null;
            for (var t = o.GetType(); t != null; t = t.BaseType) { var f = t.GetField(name, All); if (f != null) return f.GetValue(o); }
            return null;
        }
        static object Prop(object o, string name)
        {
            if (o == null) return null;
            var p = o.GetType().GetProperty(name, All);
            return p == null ? null : p.GetValue(o, null);
        }

        static void Collect(Widget w, Dictionary<string, Widget> ids, List<TextWidget> skillNames)
        {
            if (w == null) return;
            var id = w.Id;
            if (id != null && id.StartsWith("Aur", StringComparison.Ordinal))
            {
                if (id == "AurSkillName") { var tw = w as TextWidget; if (tw != null) skillNames.Add(tw); }
                else if (!ids.ContainsKey(id)) ids[id] = w;
            }
            for (int i = 0; i < w.ChildCount; i++) Collect(w.GetChild(i), ids, skillNames);
        }

        static void Set(Dictionary<string, Widget> ids, string id, string text) { Widget w; if (ids.TryGetValue(id, out w)) Set(w as TextWidget, text); }
        static void Set(TextWidget tw, string text) { if (tw != null && tw.Text != text) tw.Text = text ?? ""; }
    }

    // ---------------------------------------------------------------- Aurelion watch: our server's own campaign helper (read only, nothing is changed in the world)
    // A short report when a new day starts (gold, men and food since the last report; at most every 90 s); and a warning, at most once a day each, when the food runs out within two days,
    // the purse cannot pay three days of wages, or the morale is low. It only reads the main party, so nothing can drift between players.
    public static class UiWatch
    {
        static DateTime next = DateTime.MinValue, lastReport = DateTime.MinValue; static double day = -1; static int gold0, men0, errors;
        static readonly Dictionary<string, double> said = new Dictionary<string, double>(StringComparer.Ordinal);
        static bool Ar { get { return UiText.Arabic; } }
        static string L(string en, string ar) { return Ar ? ar : en; }

        public static void Tick()
        {
            try
            {
                if (DateTime.UtcNow < next) return;
                next = DateTime.UtcNow.AddSeconds(2);
                if (Campaign.Current == null) { day = -1; said.Clear(); return; }
                var p = TaleWorlds.CampaignSystem.Party.MobileParty.MainParty; var h = Hero.MainHero;
                if (p == null || h == null || p.MemberRoster == null) return;
                try { var top = ScreenManager.TopScreen; if (top != null && top.GetType().Name.IndexOf("Mission", StringComparison.Ordinal) >= 0) return; } catch { }   // not inside a battle or a scene
                double now = CampaignTime.Now.ToDays; int men = p.MemberRoster.TotalManCount;
                if (day < 0) { day = Math.Floor(now); gold0 = h.Gold; men0 = men; return; }

                int food = 99; try { food = p.GetNumDaysForFoodToLast(); } catch { }
                int wage = 0; try { wage = p.TotalWage; } catch { }
                float morale = 50; try { morale = p.Morale; } catch { }
                Warn("food", men > 1 && food < 2, now, L("Aurelion: food runs out " + (food <= 0 ? "today" : "tomorrow") + " - buy grain or meat in the next town",
                    "\u0623\u0648\u0631\u064a\u0644\u064a\u0648\u0646: \u0627\u0644\u0623\u0643\u0644 \u0647\u064a\u062e\u0644\u0635 " + (food <= 0 ? "\u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647" : "\u0628\u0643\u0631\u0629") + "\u060c \u0627\u0634\u062a\u0631\u064a \u0623\u0643\u0644 \u0645\u0646 \u0623\u0642\u0631\u0628 \u0645\u062f\u064a\u0646\u0629"));
                Warn("wage", wage > 0 && h.Gold < wage * 3, now, L("Aurelion: your gold pays less than three days of wages (" + wage + " a day)",
                    "\u0623\u0648\u0631\u064a\u0644\u064a\u0648\u0646: \u062f\u0647\u0628\u0643 \u0645\u0634 \u0647\u064a\u0643\u0641\u064a \u0623\u062c\u0648\u0631 \u062a\u0644\u0627\u062a \u062a\u064a\u0627\u0645 (" + wage + " \u0641\u064a \u0627\u0644\u064a\u0648\u0645)"));
                Warn("morale", men > 1 && morale < 30, now, L("Aurelion: morale is low (" + (int)morale + ") - men may desert",
                    "\u0623\u0648\u0631\u064a\u0644\u064a\u0648\u0646: \u0627\u0644\u0631\u0648\u062d \u0627\u0644\u0645\u0639\u0646\u0648\u064a\u0629 \u0648\u0627\u0637\u064a\u0629 (" + (int)morale + ")\u060c \u0627\u0644\u0639\u0633\u0627\u0643\u0631 \u0645\u0645\u0643\u0646 \u064a\u0647\u0631\u0628\u0648\u0627"));

                if (Math.Floor(now) > day && (DateTime.UtcNow - lastReport).TotalSeconds >= 90)   // fast time: at most one report every minute and a half
                {
                    day = Math.Floor(now);
                    int dg = h.Gold - gold0, dm = men - men0;
                    string sg = (dg >= 0 ? "+" : "") + dg, sm = (dm >= 0 ? "+" : "") + dm;
                    AdminClient.Toast(L("Aurelion report: gold " + sg + " (" + h.Gold + "), men " + sm + " (" + men + "), food for " + food + " days",
                        "\u0623\u0648\u0631\u064a\u0644\u064a\u0648\u0646 - \u064a\u0648\u0645 \u062c\u062f\u064a\u062f: \u0627\u0644\u062f\u0647\u0628 " + sg + " (" + h.Gold + ")\u060c \u0627\u0644\u0631\u062c\u0627\u0644\u0629 " + sm + " (" + men + ")\u060c \u0627\u0644\u0623\u0643\u0644 \u064a\u0643\u0641\u064a " + food + " \u064a\u0648\u0645"), true);
                    gold0 = h.Gold; men0 = men; lastReport = DateTime.UtcNow;
                }
            }
            catch (Exception e) { if (++errors <= 3) Log.W("UiWatch: " + e.Message); }
        }

        static void Warn(string key, bool on, double now, string text)
        {
            double at;
            if (!on) { said.Remove(key); return; }
            if (said.TryGetValue(key, out at) && now - at < 1.0) return;
            said[key] = now; AdminClient.Toast(text, false);
        }
    }
}

