// =====================================================================================
//  system/UiSkin.cs — هوية أوريليون جوه شاشات اللعبة الأصلية (الخط + ألوان النص + قطع التصميم المعتمد مكان قطع اللعبة)
//  بيشتغل وقت التشغيل بس: مش بيغيّر ولا ملف من ملفات اللعبة أو أي مود.
//  بيلمس براشات اللعبة الأصلية بالاسم بس (بيقرا أسماءها من ملفات اللعبة نفسها Native + SandBox)، وبس لو خطها لسه خط اللعبة الأصلي،
//  يعني أي مود ادّى براش خط تاني مش هنقرّب منه.
//  الخط: Galahad ← Aurelion-Bold ، FiraSans ← Aurelion-SemiBold (نفس خط اللانشر Cairo).
//  ألوان النص: الكريمي/الأبيض ← عاجي اللانشر، الدهبي/البرتقالي ← كهرماني اللانشر، بنفس درجة الإضاءة
//  (عشان الترتيب بين العناوين والنص الثانوي يفضل زي ما هو). الأحمر/الأخضر وغيرهم بيفضلوا زي ما هم.
// =====================================================================================
using System;
using System.Collections.Generic;
using TaleWorlds.GauntletUI;
using TaleWorlds.Library;
using TaleWorlds.GauntletUI.BaseTypes;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class UiSkin
    {
        // ضبط الأحجام (Cairo أعرض من FiraSans Extra Condensed)
        public static float GalahadScale = 1.0f, FiraScale = 0.9f;
        public static bool Enabled = true;

        static HashSet<string> native;
        static readonly HashSet<Brush> done = new HashSet<Brush>();
        static bool hooked, dirty = true, dead;
        static DateTime next = DateTime.MinValue;
        static TaleWorlds.TwoDimension.Font fBold, fSemi;
        static int applied, skippedMod, graded, swapped;
        // what each touched brush/style looked like before, so Ctrl+Shift+F11 can compare original and Aurelion side by side
        class Saved { public Brush B; public Style S; public TaleWorlds.TwoDimension.Font F, NF; public int Size, NSize; public Color C, NC; }
        static readonly List<Saved> saved = new List<Saved>();
        static bool showingNative;

        // The compare shortcut exists only on the team's own machines: it needs this marker file, which is never published,
        // so players never get it. (C:\ProgramData\Aurelion\Studio\dev-tools.txt)
        static int devTools = -1;
        static bool DevTools
        {
            get
            {
                if (devTools < 0)
                {
                    try { devTools = System.IO.File.Exists(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Aurelion", "Studio", "dev-tools.txt")) ? 1 : 0; }
                    catch { devTools = 0; }
                }
                return devTools == 1;
            }
        }

        public static void Tick()
        {
            try { UiScreens.Tick(); } catch { }
            // our own screens (character choice, loading) need the Aurelion fonts even while the game's menus keep their look
            try
            {
                // only once a screen is up for a few seconds (Ensure gives up after three failed tries)
                if (!AurFont.Ready && TaleWorlds.ScreenSystem.ScreenManager.TopScreen != null)
                {
                    if (fontTry == DateTime.MinValue) fontTry = DateTime.UtcNow.AddSeconds(4);
                    else if (DateTime.UtcNow >= fontTry)
                    {
                        fontTry = DateTime.UtcNow.AddSeconds(2);
                        if (TaleWorlds.Engine.GauntletUI.UIResourceManager.BrushFactory != null) AurFont.Ensure();
                    }
                }
            }
            catch { }
            // the game's own menus (main menu, options from it, the IP join screen) stay exactly as the game draws them:
            // the Aurelion look starts when a world is loaded (from the launcher's Play that is straight after the character choice)
            try
            {
                bool outside = TaleWorlds.CampaignSystem.Campaign.Current == null;
                if (!dead && outside != lastOutside)
                {
                    lastOutside = outside;
                    if (showingNative != outside) Toggle(true);
                }
            }
            catch { }
            try
            {
                if (!dead && saved.Count > 0 && DevTools && !lastOutside && TaleWorlds.InputSystem.Input.IsKeyPressed(TaleWorlds.InputSystem.InputKey.F11)
                    && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftControl) && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftShift))
                    Toggle();
            }
            catch { }
            try
            {
                if (DevTools && TaleWorlds.InputSystem.Input.IsKeyPressed(TaleWorlds.InputSystem.InputKey.F9)
                    && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftControl) && TaleWorlds.InputSystem.Input.IsKeyDown(TaleWorlds.InputSystem.InputKey.LeftShift))
                    DumpScreen();
            }
            catch (Exception de) { Log.W("UiSkin dump failed: " + de.Message); }
            if (!dead && Enabled && !showingNative) { try { DrainWidgets(); } catch (Exception we) { Log.W("UiSkin widgets: " + we.Message); } }
            if (!dead && !showingNative) { try { FontPolicy(false); } catch (Exception fe) { Log.W("UiSkin fonts: " + fe.Message); } }
            if (dead || !Enabled || !dirty || showingNative) return;
            if (DateTime.UtcNow < next) return;
            next = DateTime.UtcNow.AddSeconds(1);
            try
            {
                var bf = TaleWorlds.Engine.GauntletUI.UIResourceManager.BrushFactory;
                var ff = TaleWorlds.Engine.GauntletUI.UIResourceManager.FontFactory;
                if (bf == null || ff == null) return;
                if (fBold == null || fSemi == null)
                {
                    AurFont.Ensure();
                    fBold = Find(ff, "Aurelion-Bold"); fSemi = Find(ff, "Aurelion-SemiBold");
                    if (fBold == null || fSemi == null) return;   // fonts register a moment later: try again next second
                }
                if (!EnsureSkinSheet()) return;   // design pieces register a moment later: try again next second
                if (!hooked) { bf.BrushChange += OnBrushChange; hooked = true; HookWidgets(); UiEscape.Hook(); }
                if (native == null) { native = LoadNative(); Log.W("UiSkin: " + native.Count + " native brush names read from the game files"); }
                if (native.Count < 1000) { dead = true; Log.W("UiSkin: native brush list incomplete, skin not applied"); return; }
                int before = applied, beforeSkip = skippedMod;
                foreach (var br in bf.Brushes)
                {
                    if (br == null || br.Name == null || done.Contains(br) || !native.Contains(br.Name)) continue;
                    done.Add(br);
                    if (Skin(br)) applied++; else skippedMod++;
                    graded += GradeBrush(br);
                    swapped += SwapBrush(br);
                }
                dirty = false;
                FontPolicy(true);
                Log.W("UiSkin: " + (applied - before) + " native brushes now in Aurelion identity (total " + applied + "), left alone " + (skippedMod - beforeSkip) + "; design layers swapped " + swapped + ", colour-graded " + graded);
            }
            catch (Exception e) { dead = true; Log.W("UiSkin stopped: " + (e.InnerException ?? e)); }
        }

        static void OnBrushChange() { dirty = true; }

        // team test aid (dev machines only, see DevTools): Ctrl+Shift+F11 flips every touched brush between the game's original look and Aurelion (reopen the screen to see it)
        static bool lastOutside;
        static DateTime fontTry = DateTime.MinValue;
        static void Toggle() { Toggle(false); }
        static void Toggle(bool quiet)
        {
            showingNative = !showingNative;
            foreach (var r in saved)
            {
                var f = showingNative ? r.F : r.NF; var s = showingNative ? r.Size : r.NSize; var c = showingNative ? r.C : r.NC;
                if (r.B != null) { r.B.Font = f; r.B.FontSize = s; r.B.FontColor = c; }
                else { r.S.Font = f; r.S.FontSize = s; r.S.FontColor = c; }
            }
            foreach (var g in gradedLayers) { if (showingNative) { g.L.HueFactor = g.H; g.L.SaturationFactor = g.S; g.L.ValueFactor = g.V; g.L.Color = g.C; } else { g.L.HueFactor = g.NH; g.L.SaturationFactor = g.NS; g.L.ValueFactor = g.NV; g.L.Color = g.NC; } }
            foreach (var r in swappedLayers) { if (showingNative) UndoSwap(r); else ApplySwap(r); }
            foreach (var r in swappedIcons) r.L.Sprite = showingNative ? r.Old : r.New;
            foreach (var t in tints) { t.L.Color = showingNative ? t.C : t.NC; t.L.ColorFactor = showingNative ? t.CF : t.NCF; }
            foreach (var w in gradedWidgetsSwap) { Widget x; if (w.W.TryGetTarget(out x) && x != null) { if (showingNative) { x.Sprite = w.Old; x.Color = w.C; x.NinePatchLeft = w.NL; x.NinePatchRight = w.NR; x.NinePatchTop = w.NT; x.NinePatchBottom = w.NB; } else { x.Sprite = w.New; x.Color = new Color(1f, 1f, 1f, w.C.Alpha); x.NinePatchLeft = 0; x.NinePatchRight = 0; x.NinePatchTop = 0; x.NinePatchBottom = 0; } } }
            foreach (var w in gradedWidgets) { Widget x; if (w.W.TryGetTarget(out x) && x != null) { if (showingNative) { x.SaturationFactor = w.S; x.ValueFactor = w.V; x.Color = w.C; } else { x.SaturationFactor = w.NS; x.ValueFactor = w.NV; x.Color = w.NC; } } }
            Log.W("UiSkin: now showing " + (showingNative ? "the original game look" : "the Aurelion look") + " (Ctrl+Shift+F11)");
            if (!quiet) { try { TaleWorlds.Library.InformationManager.DisplayMessage(new TaleWorlds.Library.InformationMessage(showingNative ? "Aurelion skin: OFF (original) — reopen the screen" : "Aurelion skin: ON — reopen the screen")); } catch { } }
        }

        // ------------------------------------------------------------------ languages
        // The Aurelion font (Cairo cut) carries Latin-1 and Arabic only. Languages that need other letters (Turkish, Polish, Russian,
        // Chinese, Japanese, Korean, French with its ligatures...) keep the game's own fonts, which the game maps per language, so no
        // player ever sees empty boxes instead of letters. Colours and the designs stay Aurelion in every language.
        static readonly string[] OurFontLangs = { "english", "deutsch", "german", "español", "espanol", "spanish", "italiano", "italian", "português", "portugues", "portuguese", "arab", "عرب" };
        public static bool FontsOk
        {
            get
            {
                string l;
                try { l = (TaleWorlds.Localization.MBTextManager.ActiveTextLanguage ?? "").ToLowerInvariant(); } catch { return true; }
                if (l.Length == 0) return true;
                foreach (var k in OurFontLangs) if (l.IndexOf(k, StringComparison.Ordinal) >= 0) return true;
                return false;
            }
        }
        class OwnFont { public Brush B; public Style S; public TaleWorlds.TwoDimension.Font F; public int Size; }
        static readonly List<OwnFont> ownFonts = new List<OwnFont>();
        static readonly HashSet<Brush> ownSeen = new HashSet<Brush>();
        static string fontLang; static bool fontOk = true; static int ownCount;
        static void FontPolicy(bool afterSkin)
        {
            string lang;
            try { lang = TaleWorlds.Localization.MBTextManager.ActiveTextLanguage ?? ""; } catch { return; }
            var bf = TaleWorlds.Engine.GauntletUI.UIResourceManager.BrushFactory;
            var ff = TaleWorlds.Engine.GauntletUI.UIResourceManager.FontFactory;
            if (bf == null || ff == null) return;
            bool changed = lang != fontLang;
            int before = ownFonts.Count;
            // our own brushes (Aur.*, admin, culture...) name the Aurelion font directly: remember their font once
            if (changed || afterSkin || bf.Brushes is ICollection<Brush> && ((ICollection<Brush>)bf.Brushes).Count != ownCount)
            {
                int n = 0;
                foreach (var br in bf.Brushes)
                {
                    n++;
                    // a brush is remembered only once its Aurelion font is there (fonts register a moment after the brushes load)
                    if (br == null || ownSeen.Contains(br) || done.Contains(br) || !IsOurs(br.Font)) continue;
                    ownSeen.Add(br);
                    ownFonts.Add(new OwnFont { B = br, F = br.Font, Size = br.FontSize });
                    if (br.DefaultStyle != null && IsOurs(br.DefaultStyle.Font)) ownFonts.Add(new OwnFont { S = br.DefaultStyle, F = br.DefaultStyle.Font, Size = br.DefaultStyle.FontSize });
                    foreach (var st in br.Styles) if (st != null && st != br.DefaultStyle && IsOurs(st.Font)) ownFonts.Add(new OwnFont { S = st, F = st.Font, Size = st.FontSize });
                }
                ownCount = n;
            }
            if (!changed && !afterSkin && ownFonts.Count == before) return;
            fontLang = lang; fontOk = FontsOk;
            TaleWorlds.TwoDimension.Font gal = null, fira = null;
            if (!fontOk)
            {
                foreach (var f in ff.GetFonts())
                {
                    if (f == null || f.Name == null) continue;
                    if (gal == null && f.Name == "Galahad") gal = f;
                    if (f.Name == "FiraSansExtraCondensed-Medium" || (fira == null && f.Name.StartsWith("FiraSansExtraCondensed", StringComparison.Ordinal))) fira = f;
                }
                if (gal == null || fira == null) { Log.W("UiSkin: game fonts not found, Aurelion font kept for '" + lang + "'"); fontOk = true; }
            }
            // native brushes: Aurelion cut (NF) or back to the game's own font (F)
            foreach (var r in saved)
            {
                var f = fontOk ? r.NF : r.F; var z = fontOk ? r.NSize : r.Size;
                if (r.B != null) { r.B.Font = f; r.B.FontSize = z; } else { r.S.Font = f; r.S.FontSize = z; }
            }
            // our brushes: Aurelion, or the game font of the same weight (Bold -> Galahad, the rest -> FiraSans)
            foreach (var o in ownFonts)
            {
                var f = o.F; var z = o.Size;
                if (!fontOk) { f = o.F.Name == "Aurelion-Bold" ? gal : fira; if (z > 0 && f == fira) z = Size(z, 1f / FiraScale); }
                if (o.B != null) { o.B.Font = f; o.B.FontSize = z; } else { o.S.Font = f; o.S.FontSize = z; }
            }
            if (changed) Log.W("UiSkin: language '" + lang + "' -> " + (fontOk ? "Aurelion font" : "game fonts (letters the Aurelion font does not carry)") + ", " + ownFonts.Count + " of our styles");
        }
        static bool IsOurs(TaleWorlds.TwoDimension.Font f) { return f != null && f.Name != null && f.Name.StartsWith("Aurelion-", StringComparison.Ordinal); }

        static TaleWorlds.TwoDimension.Font Find(FontFactory ff, string name)
        {
            foreach (var f in ff.GetFonts()) if (f != null && f.Name == name) return f;
            return null;
        }

        // which Aurelion cut replaces a native font (null = not a native font: leave it alone)
        static TaleWorlds.TwoDimension.Font Cut(TaleWorlds.TwoDimension.Font f, out float scale)
        {
            scale = 1f;
            if (f == null || f.Name == null) return null;
            var n = f.Name;
            if (n == "Galahad" || n == "Galahad_Numbers_Bold") { scale = GalahadScale; return fBold; }
            if (n.StartsWith("FiraSansExtraCondensed", StringComparison.Ordinal) || n.StartsWith("ProximFiraSans", StringComparison.Ordinal)) { scale = FiraScale; return fSemi; }
            return null;
        }

        class Orig { public Style S; public TaleWorlds.TwoDimension.Font F; public int Size; public Color C; }

        // boxes the game sizes for its narrow font: the wider Aurelion cut would wrap ("12370-652"), so these get a smaller size
        static readonly Dictionary<string, float> Tight = new Dictionary<string, float>(StringComparer.Ordinal)
        {
            { "InventoryGoldFontBrush", 0.78f },
        };
        static bool Skin(Brush br)
        {
            float tight; if (br.Name == null || !Tight.TryGetValue(br.Name, out tight)) tight = 1f;
            float sc;
            var bNew = Cut(br.Font, out sc);
            if (bNew == null) return false;   // a mod gave this brush its own font: not ours to touch
            var styles = new List<Style>();
            if (br.DefaultStyle != null) styles.Add(br.DefaultStyle);
            foreach (var s in br.Styles) if (s != null && !styles.Contains(s)) styles.Add(s);
            // read everything first: styles inherit from the default style, so writing as we go would scale twice
            var orig = new List<Orig>();
            foreach (var s in styles) orig.Add(new Orig { S = s, F = s.Font, Size = s.FontSize, C = s.FontColor });
            var bSize = br.FontSize; var bC = br.FontColor;
            var bF = br.Font;
            foreach (var o in orig)
            {
                float k; var nf = Cut(o.F, out k);
                var rec = new Saved { S = o.S, F = o.F, Size = o.Size, C = o.C, NF = o.F, NSize = o.Size, NC = Map(o.C) };
                if (nf != null) { rec.NF = nf; if (o.Size > 0) rec.NSize = Size(o.Size, k * tight); }
                o.S.Font = rec.NF; o.S.FontSize = rec.NSize; o.S.FontColor = rec.NC;
                saved.Add(rec);
            }
            if (br.Name != null && br.Name.EndsWith("TabControl.Text", StringComparison.Ordinal))
                foreach (var r in saved)
                    if (r.S != null && orig.Exists(o => o.S == r.S))
                    {
                        bool on = r.S.Name != null && r.S.Name.IndexOf("Selected", StringComparison.OrdinalIgnoreCase) >= 0;
                        r.NC = on ? Ivory : new Color(Ivory.Red, Ivory.Green, Ivory.Blue, 0.72f); r.S.FontColor = r.NC;
                    }
            var b = new Saved { B = br, F = bF, Size = bSize, C = bC, NF = bNew, NSize = bSize > 0 ? Size(bSize, sc * tight) : bSize, NC = Map(bC) };
            br.Font = b.NF; br.FontSize = b.NSize; br.FontColor = b.NC;
            saved.Add(b);
            return true;
        }

        static readonly Color Ivory = new Color(0xF7 / 255f, 0xF2 / 255f, 0xE0 / 255f, 1f);
        static int Size(int s, float k) { var v = (int)Math.Round(s * k); return v < 8 ? 8 : v; }

        // launcher palette: Ivory #F7F2E0, Amber #E8B94E
        static Color Map(Color c)
        {
            float h, s, v; Hsv(c.Red, c.Green, c.Blue, out h, out s, out v);
            if (v < 0.55f) return c;                                    // dark text (on parchment) stays as is
            if (s < 0.24f) return FromHsv(47f, 0.09f, v, c.Alpha);      // white / cream -> ivory, same brightness
            if (h >= 22f && h <= 52f) return FromHsv(42f, Math.Min(0.66f, Math.Max(0.30f, s)), v, c.Alpha);   // gold / orange -> amber
            return c;                                                   // red, green, blue, magenta: keep their meaning
        }

