        // exact names first, then whole families the game draws the same way (every list's column header strip)
        static Swap Lookup(string name)
        {
            Swap sw; if (SwapMap().TryGetValue(name, out sw)) return sw;
            if (name.IndexOf("_sort_header", StringComparison.Ordinal) >= 0) return SortHeader;
            // the kingdom / army lists draw their column headers as numbered wooden strips
            if ((name.StartsWith("SPKingdom\\", StringComparison.Ordinal) && name.IndexOf("\\header_", StringComparison.Ordinal) > 0 && name.IndexOf("policies", StringComparison.Ordinal) < 0)
                || name.StartsWith("ArmyManagement\\header_gather_army", StringComparison.Ordinal)
                || name.StartsWith("Inventory\\header_button_", StringComparison.Ordinal)
                || name.StartsWith("Crafting\\header_button", StringComparison.Ordinal)) return SortHeader;
            return null;
        }
        static readonly Swap SortHeader = new Swap("sh", null, null);

        static readonly Dictionary<string, TaleWorlds.TwoDimension.Sprite> ourSprites = new Dictionary<string, TaleWorlds.TwoDimension.Sprite>(StringComparer.Ordinal);
