        static bool EnsureSkinSheet()
        {
            if (skinReady) return true;
            if (!AurelionSkin.EnsureSprite("aur_skin", "aur_skin_1.png")) return false;
            var sd = TaleWorlds.Engine.GauntletUI.UIResourceManager.SpriteData;
            foreach (var n in new[] { "glass_9", "clear", "header_fade", "divider", "sh", "tab_9", "tab_hover_9", "tab_on_9", "row_9", "row_hover_9", "row_on", "btn_pr_9", "btn_pr_hover_9", "btn_9", "btn_hover_9" })
            {
                var s = sd.GetSprite("aur_skin\\" + n);
                if (s == null) { Log.W("UiSkin: design piece missing: " + n); return false; }
                ourSprites[n] = s;
            }
            // second sheet: pieces for the game's popups (input field) and tooltips
            if (!AurelionSkin.EnsureSprite("aur_skin2", "aur_skin2_1.png")) return false;
            foreach (var n in new[] { "input_9", "gh_line", "tt_9", "card_9", "pop_9", "bar_bg_9", "bar_fill_9", "thumb_9" })
            {
                var s = sd.GetSprite("aur_skin2\\" + n);
                if (s == null) { Log.W("UiSkin: design piece missing: " + n); return false; }
                ourSprites[n] = s;
            }
            // controls (options arrows, sliders, checkboxes): optional, a missing one only leaves that control as the game draws it
            foreach (var n in new[] { "arr_l", "hud_bar_9", "hud_ring", "hud_disc", "hud_army", "hud_btn", "hud_btn_h", "hud_btn_34", "hud_btn_90", "arr_r", "arr_l_h", "arr_r_h", "sl_track", "sl_fill", "sl_knob", "sl_knob_h", "chk_off", "chk_on", "fp_big_e", "fp_big_f", "fp_e", "fp_f", "fp_lg_e", "fp_lg_f", "plus_77", "plus_77_h", "add_50", "add_35", "rowo_9", "rowo_hover_9", "rowo_on", "perk_tile", "close_btn", "close_btn_h", "back_btn", "back_btn_h", "chk_s_off", "chk_s_on", "perk_band", "perk_band_w", "slot_helmet", "slot_helmet_h", "slot_armor", "slot_armor_h", "slot_glove", "slot_glove_h", "slot_boot", "slot_boot_h", "slot_cloak", "slot_cloak_h", "slot_weapon", "slot_weapon_h", "slot_mount", "slot_mount_h", "slot_marmor", "slot_marmor_h", "slot_banner", "slot_banner_h", "slot_perk", "slot_perk_h" })
            {
