            if (AurelionSkin.EnsureSprite("aur_bg_hall_dim", "aur_bg_hall_dim_1.png"))
            {
                var hd = sd.GetSprite("aur_bg_hall_dim\\bg");
                if (hd != null) ourSprites["hall_dim"] = hd; else Log.W("UiSkin: dim hall painting missing");
