        static TaleWorlds.TwoDimension.Sprite Pick(Swap sw, string styleName)
        {
            string n = sw.N;
            if (styleName != null)
            {
                if (sw.Selected != null && (styleName.IndexOf("Selected", StringComparison.OrdinalIgnoreCase) >= 0 || styleName.IndexOf("Pressed", StringComparison.OrdinalIgnoreCase) >= 0)) n = sw.Selected;
                else if (sw.Hover != null && styleName.IndexOf("Hover", StringComparison.OrdinalIgnoreCase) >= 0) n = sw.Hover;
            }
            TaleWorlds.TwoDimension.Sprite s; return ourSprites.TryGetValue(n, out s) ? s : null;
        }

        class LayerSwap { public bool Keep; public StyleLayer L; public TaleWorlds.TwoDimension.Sprite Old, New; public Color C; public float H, S, V, CF, NCF, ET, EB, EL, ER; }
        static readonly List<LayerSwap> swappedLayers = new List<LayerSwap>();
        static void ApplySwap(LayerSwap r)
        {
            if (r.Keep) { r.L.Sprite = r.New; return; }
            r.L.Sprite = r.New; r.L.Color = new Color(1f, 1f, 1f, r.C.Alpha); r.L.HueFactor = 0f; r.L.SaturationFactor = 0f; r.L.ValueFactor = 0f;
            r.L.ColorFactor = r.NCF; r.L.ExtendTop = 0; r.L.ExtendBottom = 0; r.L.ExtendLeft = 0; r.L.ExtendRight = 0;
        }
        static void UndoSwap(LayerSwap r)
        {
            r.L.Sprite = r.Old; r.L.Color = r.C; r.L.HueFactor = r.H; r.L.SaturationFactor = r.S; r.L.ValueFactor = r.V;
            r.L.ColorFactor = r.CF; r.L.ExtendTop = r.ET; r.L.ExtendBottom = r.EB; r.L.ExtendLeft = r.EL; r.L.ExtendRight = r.ER;
        }

        // swaps where the game says something with colour (perk taken / locked): our picture, the game's tint
        static readonly HashSet<string> KeepTint = new HashSet<string>(StringComparer.Ordinal) { @"CharacterDeveloper\character_perk_background", @"CharacterDeveloper\character_perk_background_active", "battle_header_bar_left_9", "battle_header_bar_right_9" };

        static int SwapBrush(Brush br)
        {
            if (!skinReady) return 0;
            var map = SwapMap(); int n = 0;
            var styles = new List<Style>();
            if (br.DefaultStyle != null) styles.Add(br.DefaultStyle);
            foreach (var s in br.Styles) if (s != null && !styles.Contains(s)) styles.Add(s);
            var todo = new List<LayerSwap>();
            foreach (var s in styles)
                foreach (var l in s.GetLayers())
                {
                    if (l == null || l.Sprite == null || l.Sprite.Name == null) continue;
                    var sw = Lookup(l.Sprite.Name); if (sw == null) continue;
                    var ns = Pick(sw, s.Name); if (ns == null) continue;
                    // our pieces already carry their own hover / selected look: the game's brightening (x1.5, x2 on selected) would wash them out,
                    // and its extends were sized for its own art. Disabled keeps the game's dimming.
                    bool disabled = s.Name != null && s.Name.IndexOf("Disabled", StringComparison.OrdinalIgnoreCase) >= 0;
                    todo.Add(new LayerSwap { Keep = KeepTint.Contains(l.Sprite.Name), L = l, Old = l.Sprite, New = ns, C = l.Color, H = l.HueFactor, S = l.SaturationFactor, V = l.ValueFactor,
                        CF = l.ColorFactor, NCF = disabled ? Math.Min(l.ColorFactor, 0.6f) : 1f, ET = l.ExtendTop, EB = l.ExtendBottom, EL = l.ExtendLeft, ER = l.ExtendRight });
                }
            foreach (var r in todo)
            {
                ApplySwap(r);
                swappedLayers.Add(r); n++;
            }
            if (br.Name == "MapBar.Left.Button") TintMapButtons(br);
            if (IconSources.Contains(br.Name))
                foreach (var bl in br.Layers)
                {
                    if (bl == null || bl.Sprite == null || bl.Sprite.Name == null) continue;
                    var sw = Lookup(bl.Sprite.Name); if (sw == null) continue;
                    var ns = Pick(sw, null); if (ns == null) continue;
                    swappedIcons.Add(new IconSwap { L = bl, Old = bl.Sprite, New = ns });
                    bl.Sprite = ns; n++;
                }
            return n;
        }

        // brushes the game reads a picture FROM (IconBrushWidget copies IconBrush.GetLayer(id).Sprite onto the button at run time):
        // swapping their styles is not enough, the picture lives on the brush layer. Our pieces keep the game's sizes, so nothing moves.
        static readonly HashSet<string> IconSources = new HashSet<string>(StringComparer.Ordinal) { "MapBar.Left.Button.Backgrounds" };
        class IconSwap { public BrushLayer L; public TaleWorlds.TwoDimension.Sprite Old, New; }

        // map bar buttons: the picture is copied onto every state at run time, so the state shows as a tint of our glass tile:
        // amber when the mouse is on it, bordeaux while its screen is open (game: brighter / yellow)
        class Tint { public StyleLayer L; public Color C, NC; public float CF, NCF; }
        static readonly List<Tint> tints = new List<Tint>();
        static readonly HashSet<Brush> tinted = new HashSet<Brush>();
        static void TintMapButtons(Brush br)
        {
            if (!tinted.Add(br)) return;   // once per brush (a brush reload brings a new object)
            foreach (var st in br.Styles)
            {
                if (st == null || st.Name == null) continue;
                Color c; float f;
                if (st.Name == "Hovered" || st.Name == "Pressed") { c = new Color(0.91f, 0.73f, 0.31f, 1f); f = 1.6f; }
                else if (st.Name == "Selected") { c = new Color(0.85f, 0.25f, 0.36f, 1f); f = 1.8f; }
                else continue;
                foreach (var l in st.GetLayers())
                {
                    if (l == null) continue;
                    tints.Add(new Tint { L = l, C = l.Color, CF = l.ColorFactor, NC = c, NCF = f });
                    l.Color = c; l.ColorFactor = f;
                }
            }
        }
        static readonly List<IconSwap> swappedIcons = new List<IconSwap>();

        // brush layers: every style of a native brush, layer by layer (read first, then write)
        static int GradeBrush(Brush br)
        {
            var map = GradeMap(); int n = 0;
            var styles = new List<Style>();
            if (br.DefaultStyle != null) styles.Add(br.DefaultStyle);
            foreach (var s in br.Styles) if (s != null && !styles.Contains(s)) styles.Add(s);
            var todo = new List<LayerSaved>();
            foreach (var s in styles)
            {
                // a "Selected" state keeps the game's meaning (highlighted) but in Aurelion amber, not rotated to red
                bool selectedState = s.Name != null && s.Name.IndexOf("Selected", StringComparison.OrdinalIgnoreCase) >= 0;
                foreach (var l in s.GetLayers())
                {
                    if (l == null || l.Sprite == null || l.Sprite.Name == null) continue;
                    Grade g; if (!map.TryGetValue(l.Sprite.Name, out g)) continue;
                    if (selectedState && g.Hue < -20) g = SELECTED;
                    var rec = new LayerSaved { L = l, H = l.HueFactor, S = l.SaturationFactor, V = l.ValueFactor, C = l.Color };
                    rec.NH = rec.H + g.Hue;
                    rec.NS = Clamp(rec.S + g.Sat, -100f, 100f); rec.NV = Clamp(rec.V + g.Val, -100f, 100f); rec.NC = Mul(rec.C, g);
                    todo.Add(rec);
                }
            }
            foreach (var r in todo) { r.L.HueFactor = r.NH; r.L.SaturationFactor = r.NS; r.L.ValueFactor = r.NV; r.L.Color = r.NC; gradedLayers.Add(r); n++; }
            return n;
        }

        // widgets that set one of these sprites directly in their screen file (backgrounds, headers, the map bar).
        // Widget.set_Sprite is too small (the JIT inlines it into generated prefab code), so the hook sits on Widget.OnRender:
        // a widget is graded the first time it draws with a mapped sprite, and remembered so it is never graded twice.
        static bool widgetsHooked;
        static int widgetHits, widgetSwaps;
        class WidgetSwap { public WeakReference<Widget> W; public TaleWorlds.TwoDimension.Sprite Old, New; public Color C; public int NL, NR, NT, NB; }
        static readonly List<WidgetSwap> gradedWidgetsSwap = new List<WidgetSwap>();
        static void HookWidgets()
        {
            if (widgetsHooked) return; widgetsHooked = true;
            try
            {
                var h = new Harmony("aurelion.uiskin");
                var render = AccessTools.Method(typeof(Widget), "OnRender");
                if (render != null) { h.Patch(render, prefix: new HarmonyMethod(typeof(UiSkin), "RenderPrefix")); Log.W("UiSkin: widget backgrounds hook ready"); }
                else Log.W("UiSkin: Widget.OnRender not found, backgrounds keep the original colour");
            }
            catch (Exception e) { Log.W("UiSkin: widget hook failed: " + e.Message); }
        }

        static readonly Dictionary<TaleWorlds.TwoDimension.Sprite, bool> spriteKnown = new Dictionary<TaleWorlds.TwoDimension.Sprite, bool>();
        public static void RenderPrefix(Widget __instance)
        {
            try
            {
                if (showingNative || dead) return;
                var sp = __instance.Sprite;
                if (sp == null) return;
                if (skinReady && sp.Name != null)
                {
                    var sw = Lookup(sp.Name);
                    if (sw != null)
                    {
                        var ns = Pick(sw, null);
                        if (ns != null)
                        {
                            // a screen file can give a widget its own nine-patch margins sized for the game's art (the map bar's right frame: 70/87/10/11);
                            // on our much smaller piece those margins read pixels from the neighbouring pieces, so our piece uses its own margins
                            gradedWidgetsSwap.Add(new WidgetSwap { W = new WeakReference<Widget>(__instance), Old = sp, New = ns, C = __instance.Color,
                                NL = __instance.NinePatchLeft, NR = __instance.NinePatchRight, NT = __instance.NinePatchTop, NB = __instance.NinePatchBottom });
                            __instance.Sprite = ns; __instance.Color = new Color(1f, 1f, 1f, __instance.Color.Alpha);
                            __instance.NinePatchLeft = 0; __instance.NinePatchRight = 0; __instance.NinePatchTop = 0; __instance.NinePatchBottom = 0;
                            if (++widgetSwaps % 25 == 1) Log.W("UiSkin: design pieces on screen so far " + widgetSwaps + " (last " + sp.Name + ")");
                            return;
                        }
                    }
                }
                bool mapped;
                if (!spriteKnown.TryGetValue(sp, out mapped)) { mapped = sp.Name != null && GradeMap().ContainsKey(sp.Name); spriteKnown[sp] = mapped; }
                if (!mapped) return;
                object o; if (seenWidgets.TryGetValue(__instance, out o)) return;
                seenWidgets.Add(__instance, null);
                var g = GradeMap()[sp.Name];
                var rec = new WidgetSaved { W = new WeakReference<Widget>(__instance), S = __instance.SaturationFactor, V = __instance.ValueFactor, C = __instance.Color };
                // plain widgets have no hue control: the same look is reached with a colour multiply toward bordeaux / amber
                var wg = g.Hue < -20 ? new Grade(0, g.Sat * 0.4f, g.Val, 1.00f, 0.52f, 0.58f) : (g.Hue > 0 ? new Grade(0, g.Sat, g.Val, 1.00f, 0.90f, 0.66f) : g);
                rec.NS = Clamp(rec.S + wg.Sat, -100f, 100f); rec.NV = Clamp(rec.V + wg.Val, -100f, 100f); rec.NC = Mul(rec.C, wg);
                __instance.SaturationFactor = rec.NS; __instance.ValueFactor = rec.NV; __instance.Color = rec.NC;
                gradedWidgets.Add(rec);
                if (++widgetHits % 50 == 1) Log.W("UiSkin: widget backgrounds graded so far " + widgetHits + " (last " + sp.Name + ")");
                if (gradedWidgets.Count > 4000) gradedWidgets.RemoveAll(x => { Widget y; return !x.W.TryGetTarget(out y); });
            }
            catch { }
        }

        static void DrainWidgets() { }

        // team test aid (dev machines only): Ctrl+Shift+F9 writes (F10 belongs to the admin panel) every widget on the open screen (type, id, size, sprite, brush layers)
        // to aurelion\ui-dump-<n>.txt, so each design piece is matched to the exact native piece instead of guessing.
        static int dumpNo;
        static void DumpScreen()
        {
            var sb = new System.Text.StringBuilder();
            var top = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
            sb.AppendLine("screen " + (top == null ? "-" : top.GetType().FullName));
            var screens = new List<object>();
            if (top != null) screens.Add(top);
            foreach (var f in typeof(TaleWorlds.ScreenSystem.ScreenManager).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
            {
                if (f.Name.IndexOf("lobal", StringComparison.OrdinalIgnoreCase) < 0) continue;
                var en = f.GetValue(null) as System.Collections.IEnumerable;
                if (en != null) foreach (var gl in en) if (gl != null) screens.Add(gl);
            }
            foreach (var sc in screens)
            {
                var layers = new List<object>();
                var ls = sc as TaleWorlds.ScreenSystem.ScreenBase;
                if (ls != null) foreach (var l in ls.Layers) layers.Add(l);
                else { var lp = sc.GetType().GetProperty("Layer"); if (lp != null) layers.Add(lp.GetValue(sc, null)); }
                foreach (var l in layers)
                {
                    if (l == null) continue;
                    sb.AppendLine("layer " + l.GetType().Name + " " + (l is TaleWorlds.ScreenSystem.ScreenLayer ? ((TaleWorlds.ScreenSystem.ScreenLayer)l).Name : ""));
                    UIContext ctx = null;
                    foreach (var p in l.GetType().GetProperties(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
                        if (typeof(UIContext).IsAssignableFrom(p.PropertyType)) { try { ctx = p.GetValue(l, null) as UIContext; } catch { } if (ctx != null) break; }
                    if (ctx == null)
                        foreach (var f in l.GetType().GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
                            if (typeof(UIContext).IsAssignableFrom(f.FieldType)) { ctx = f.GetValue(l) as UIContext; if (ctx != null) break; }
                    if (ctx == null || ctx.Root == null) continue;
                    DumpWidget(sb, ctx.Root, 0);
                }
            }
            var asm = typeof(UiSkin).Assembly.Location;
            var dir = System.IO.Path.GetFullPath(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(asm), "..", "..", "aurelion"));
            var file = System.IO.Path.Combine(dir, "ui-dump-" + (++dumpNo) + ".txt");
            System.IO.File.WriteAllText(file, sb.ToString());
            Log.W("UiSkin: screen written to " + file);
            try { TaleWorlds.Library.InformationManager.DisplayMessage(new TaleWorlds.Library.InformationMessage("UI dump " + dumpNo + " saved")); } catch { }
        }

        static void DumpWidget(System.Text.StringBuilder sb, Widget w, int depth)
        {
            if (w == null || depth > 60) return;
            if (!w.IsVisible) return;
            var line = new System.Text.StringBuilder();
            line.Append(new string(' ', depth)).Append(w.GetType().Name);
            if (!string.IsNullOrEmpty(w.Id)) line.Append(" #").Append(w.Id);
            line.Append(" @").Append((int)w.GlobalPosition.X).Append(',').Append((int)w.GlobalPosition.Y).Append(' ').Append((int)w.Size.X).Append('x').Append((int)w.Size.Y);
            if (w.Sprite != null) line.Append(" sprite=").Append(w.Sprite.Name);
            line.Append(" col=").Append(w.Color.ToString()).Append(" a=").Append(w.AlphaFactor.ToString("0.##"));
            var bw = w as BrushWidget;
            if (bw != null && bw.Brush != null)
            {
                line.Append(" brush=").Append(bw.Brush.Name).Append(" state=").Append(w.CurrentState);
                foreach (var bl in bw.Brush.Layers) line.Append(" [").Append(bl.Name).Append(':').Append(bl.Sprite == null ? "-" : bl.Sprite.Name).Append(']');
            }
            var tw = w as TextWidget;
            if (tw != null && !string.IsNullOrEmpty(tw.Text)) { var t = tw.Text.Replace('\n', ' '); line.Append(" text=\"").Append(t.Length > 40 ? t.Substring(0, 40) : t).Append('"'); }
            sb.AppendLine(line.ToString());
            for (int i = 0; i < w.ChildCount; i++) DumpWidget(sb, w.GetChild(i), depth + 1);
        }

        static void Hsv(float r, float g, float b, out float h, out float s, out float v)
        {
            float mx = Math.Max(r, Math.Max(g, b)), mn = Math.Min(r, Math.Min(g, b)), d = mx - mn;
            v = mx; s = mx <= 0f ? 0f : d / mx; h = 0f;
            if (d > 0f)
            {
                if (mx == r) h = 60f * (((g - b) / d) % 6f);
                else if (mx == g) h = 60f * ((b - r) / d + 2f);
                else h = 60f * ((r - g) / d + 4f);
                if (h < 0f) h += 360f;
            }
        }

        static Color FromHsv(float h, float s, float v, float a)
        {
            float c = v * s, x = c * (1f - Math.Abs((h / 60f) % 2f - 1f)), m = v - c, r, g, b;
            if (h < 60f) { r = c; g = x; b = 0f; } else if (h < 120f) { r = x; g = c; b = 0f; } else { r = 0f; g = c; b = x; }
            return new Color(r + m, g + m, b + m, a);
        }

        // brush names of the native game, read from the game's own files (Native + SandBox) on this machine: read only
        static HashSet<string> LoadNative()
        {
            var set = new HashSet<string>(StringComparer.Ordinal);
            var root = System.IO.Path.GetFullPath(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(typeof(Brush).Assembly.Location), "..", "..", "Modules"));
            var rx = new System.Text.RegularExpressions.Regex("<Brush\\s[^>]*?Name\\s*=\\s*\"([^\"]+)\"");
            foreach (var mod in new[] { "Native", "SandBox" })
            {
                var dir = System.IO.Path.Combine(root, mod, "GUI", "Brushes");
                if (!System.IO.Directory.Exists(dir)) { Log.W("UiSkin: native brushes folder missing: " + dir); continue; }
                foreach (var f in System.IO.Directory.GetFiles(dir, "*.xml"))
                    foreach (System.Text.RegularExpressions.Match m in rx.Matches(System.IO.File.ReadAllText(f))) set.Add(m.Groups[1].Value);
            }
            return set;
        }
    }
